import type { RawQ } from "../types";
// ʿAqīda: pillars of īmān and islām, iḥsān, tawḥīd, shirk, the beautiful names and attributes, angels, books, messengers, the Last Day, qadar, īmān, classical creeds and their authors. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "aq-001", s: "aqidah", g: 1, d: 1, t: ["pillars-of-iman", "hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["How many pillars of īmān are listed in the hadith of Jibrīl?", ["Six", "Five", "Four", "Seven"], "In the hadith of Jibrīl the Prophet lists six pillars of faith: belief in Allah, His angels, His books, His messengers, the Last Day and the decree (qadar). Five is the number of the pillars of islām."],
    de: ["Wie viele Säulen des Īmān werden im Hadith von Ǧibrīl genannt?", ["Sechs", "Fünf", "Vier", "Sieben"], "Im Hadith von Ǧibrīl nennt der Prophet sechs Glaubenssäulen: den Glauben an Allah, Seine Engel, Seine Bücher, Seine Gesandten, den Jüngsten Tag und die Vorherbestimmung (qadar). Fünf ist die Zahl der Säulen des Islām."],
    ar: ["كم عدد أركان الإيمان المذكورة في حديث جبريل؟", ["ستة", "خمسة", "أربعة", "سبعة"], "عدّ النبي ﷺ في حديث جبريل أركان الإيمان ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، أما الخمسة فهي أركان الإسلام."] },

  { id: "aq-002", s: "aqidah", g: 1, d: 1, t: ["pillars-of-islam"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Īmān (Islam is built on five)", tr: ["sunni"],
    en: ["What is the first of the five pillars of islām?", ["The two testimonies of faith", "The five daily prayers", "Fasting in Ramaḍān", "Paying the zakāt"], "The hadith of Ibn ʿUmar on which Islam is built begins with testifying that there is no god but Allah and that Muḥammad is His messenger; prayer, zakāt, fasting and ḥajj follow."],
    de: ["Was ist die erste der fünf Säulen des Islām?", ["Das zweifache Glaubensbekenntnis", "Die fünf täglichen Gebete", "Das Fasten im Ramaḍān", "Die Entrichtung der Zakāt"], "Der Hadith von Ibn ʿUmar über die fünf Grundpfeiler des Islam beginnt mit dem Bezeugen, dass es keinen Gott außer Allah gibt und Muḥammad Sein Gesandter ist; danach folgen Gebet, Zakāt, Fasten und Ḥaǧǧ."],
    ar: ["ما أول أركان الإسلام الخمسة؟", ["الشهادتان", "الصلوات الخمس", "صوم رمضان", "إيتاء الزكاة"], "حديث ابن عمر في بناء الإسلام على خمس يبدأ بشهادة أن لا إله إلا الله وأن محمدًا رسول الله، ثم إقام الصلاة وإيتاء الزكاة والحج وصوم رمضان."] },

  { id: "aq-003", s: "aqidah", g: 1, d: 1, t: ["pillars-of-iman", "pillars-of-islam"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["Which of the following is a pillar of īmān rather than a pillar of islām?", ["Belief in the angels", "Fasting in Ramaḍān", "Paying the zakāt", "Pilgrimage to the House"], "Belief in the angels is one of the six pillars of faith. Fasting, zakāt and ḥajj are among the outward pillars of islām named in the same hadith."],
    de: ["Welches der folgenden ist eine Säule des Īmān und nicht des Islām?", ["Der Glaube an die Engel", "Das Fasten im Ramaḍān", "Die Entrichtung der Zakāt", "Die Pilgerfahrt zum Haus"], "Der Glaube an die Engel gehört zu den sechs Glaubenssäulen. Fasten, Zakāt und Ḥaǧǧ gehören zu den äußeren Säulen des Islām, die im selben Hadith genannt werden."],
    ar: ["أيّ مما يلي من أركان الإيمان لا من أركان الإسلام؟", ["الإيمان بالملائكة", "صوم رمضان", "إيتاء الزكاة", "حج البيت"], "الإيمان بالملائكة ركن من أركان الإيمان الستة، أما الصوم والزكاة والحج فمن أركان الإسلام الظاهرة المذكورة في الحديث نفسه."] },

  { id: "aq-004", s: "aqidah", g: 1, d: 1, t: ["ihsan", "hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["How does the hadith of Jibrīl define iḥsān?", ["Worshipping Allah as though you see Him", "Giving charity beyond the obligatory zakāt", "Being kind to parents and relatives", "Reciting the Quran with beautiful tajwīd"], "The Prophet defined iḥsān as worshipping Allah as though you see Him, and if you do not see Him, then knowing that He sees you. Kindness and charity are fruits of it, but not its definition in this hadith."],
    de: ["Wie definiert der Hadith von Ǧibrīl den Iḥsān?", ["Allah anzubeten, als sähe man Ihn", "Spenden über die Pflicht-Zakāt hinaus", "Güte gegenüber Eltern und Verwandten", "Koranrezitation mit schönem Taǧwīd"], "Der Prophet definierte Iḥsān als Anbetung Allahs, als sähe man Ihn, und wenn man Ihn nicht sieht, so sieht Er einen doch. Güte und Spenden sind Früchte davon, aber nicht die Definition in diesem Hadith."],
    ar: ["كيف عُرّف الإحسان في حديث جبريل؟", ["أن تعبد الله كأنك تراه", "التصدق بما يزيد على الزكاة الواجبة", "البر بالوالدين والأقارب", "تلاوة القرآن بتجويد حسن"], "عرّف النبي ﷺ الإحسان بأن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك؛ أما البر والصدقة فمن ثمراته لا من تعريفه في هذا الحديث."] },

  { id: "aq-005", s: "aqidah", g: 1, d: 2, t: ["hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)",
    en: ["In Ṣaḥīḥ Muslim, from which Companion does Ibn ʿUmar narrate the hadith of Jibrīl?", ["His father ʿUmar ibn al-Khaṭṭāb", "Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "ʿAbd Allāh ibn Masʿūd"], "At the start of Kitāb al-Īmān in Ṣaḥīḥ Muslim, ʿAbd Allāh ibn ʿUmar narrates the hadith of Jibrīl from his father ʿUmar, who was present when the stranger in white clothes came to the Prophet."],
    de: ["Von welchem Gefährten überliefert Ibn ʿUmar im Ṣaḥīḥ Muslim den Hadith von Ǧibrīl?", ["Von seinem Vater ʿUmar ibn al-Ḫaṭṭāb", "Von Abū Bakr aṣ-Ṣiddīq", "Von ʿAlī ibn Abī Ṭālib", "Von ʿAbdallāh ibn Masʿūd"], "Am Anfang des Kitāb al-Īmān im Ṣaḥīḥ Muslim überliefert ʿAbdallāh ibn ʿUmar den Hadith von Ǧibrīl von seinem Vater ʿUmar, der dabei war, als der Fremde in weißer Kleidung zum Propheten kam."],
    ar: ["عمّن يروي ابنُ عمر حديثَ جبريل في صحيح مسلم؟", ["عن أبيه عمر بن الخطاب", "عن أبي بكر الصديق", "عن علي بن أبي طالب", "عن عبد الله بن مسعود"], "في أول كتاب الإيمان من صحيح مسلم يروي عبد الله بن عمر حديث جبريل عن أبيه عمر، وكان حاضرًا حين جاء الرجل الشديد بياض الثياب إلى النبي ﷺ."] },

  { id: "aq-006", s: "aqidah", g: 1, d: 1, t: ["tawhid"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["sunni"],
    en: ["What does the word tawḥīd mean linguistically?", ["Making one, affirming oneness", "Submitting and obeying", "Believing and trusting", "Purifying and cleansing"], "Tawḥīd is the verbal noun of waḥḥada, to make one or declare one. In creed it means affirming that Allah is one, without partner. Submission is the meaning of islām, and belief that of īmān."],
    de: ["Was bedeutet das Wort Tauḥīd sprachlich?", ["Eins machen, die Einheit bekräftigen", "Sich ergeben und gehorchen", "Glauben und vertrauen", "Reinigen und säubern"], "Tauḥīd ist das Verbalnomen von waḥḥada, eins machen oder für eins erklären. In der Glaubenslehre bedeutet es, zu bekräftigen, dass Allah einer ist, ohne Teilhaber. Ergebung ist die Bedeutung von Islām, Glauben die von Īmān."],
    ar: ["ما معنى التوحيد في اللغة؟", ["جعل الشيء واحدًا والحكم بوحدته", "الاستسلام والانقياد", "التصديق والثقة", "التطهير والتنقية"], "التوحيد مصدر وحّد يوحّد أي جعل الشيء واحدًا أو حكم بأنه واحد، وفي الاصطلاح إفراد الله بما يختص به؛ أما الاستسلام فمعنى الإسلام، والتصديق معنى الإيمان."] },

  { id: "aq-007", s: "aqidah", g: 1, d: 1, t: ["shirk"], src: "Ibn Kathīr, Tafsīr, on 4:48", tr: ["sunni"], v: "4:48",
    en: ["According to the verse shown, which sin does Allah not forgive (for one who dies upon it)?", ["Associating partners with Him", "Neglecting the prayer", "Consuming usury", "Breaking ties of kinship"], "The verse shown states that Allah does not forgive that partners be associated with Him, and forgives what is less than that for whom He wills. Scholars explain this of one who dies upon shirk without repenting."],
    de: ["Welche Sünde vergibt Allah laut dem angezeigten Vers nicht (wenn jemand darauf stirbt)?", ["Ihm Teilhaber beizugesellen", "Das Gebet zu vernachlässigen", "Zinsen zu verzehren", "Verwandtschaftsbande abzubrechen"], "Der angezeigte Vers sagt, dass Allah nicht vergibt, dass Ihm etwas beigesellt wird, und dass Er, wem Er will, vergibt, was geringer ist. Die Gelehrten beziehen dies auf den, der ohne Reue auf Širk stirbt."],
    ar: ["بحسب الآية المعروضة، ما الذنب الذي لا يغفره الله لمن مات عليه؟", ["الشرك به", "ترك الصلاة", "أكل الربا", "قطيعة الرحم"], "تقرر الآية المعروضة أن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء، وحمله العلماء على من مات على الشرك دون توبة."] },

  { id: "aq-008", s: "aqidah", g: 1, d: 2, t: ["shirk"], src: "Ibn Kathīr, Tafsīr, on 31:13", tr: ["sunni"], v: "31:13", w: 13,
    en: ["In the verse shown, Luqmān warns his son against shirk. How does he describe shirk with the highlighted word and the word after it?", ["A tremendous wrong", "A small slip", "A hidden illness", "An old custom"], "Luqmān calls shirk a tremendous ẓulm, a wrong in its highest form, because it places worship where it does not belong. In Ṣaḥīḥ al-Bukhārī the Prophet explained the ẓulm of 6:82 by this verse."],
    de: ["Im angezeigten Vers warnt Luqmān seinen Sohn vor dem Širk. Wie beschreibt er den Širk mit dem hervorgehobenen Wort und dem folgenden?", ["Als gewaltiges Unrecht", "Als kleinen Fehltritt", "Als verborgene Krankheit", "Als alte Sitte"], "Luqmān nennt den Širk ein gewaltiges Unrecht (ẓulm), denn er stellt die Anbetung an einen Ort, an den sie nicht gehört. Im Ṣaḥīḥ al-Buḫārī erklärte der Prophet das Unrecht in 6:82 mit diesem Vers."],
    ar: ["في الآية المعروضة يحذّر لقمانُ ابنَه من الشرك، فبمَ وصفه بالكلمة المظللة وما بعدها؟", ["ظلم عظيم", "زلة صغيرة", "داء خفي", "عادة قديمة"], "وصف لقمان الشرك بأنه ظلم عظيم لأنه وضعٌ للعبادة في غير موضعها، وفسّر النبي ﷺ الظلم في آية الأنعام بهذه الآية كما في صحيح البخاري."] },

  { id: "aq-009", s: "aqidah", g: 1, d: 1, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 2:97–98", tr: ["sunni"],
    en: ["Which angel was entrusted with bringing revelation to the prophets?", ["Jibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Jibrīl is the angel of revelation, called in the Quran the Trustworthy Spirit (26:193). Mīkāʾīl is commonly associated with rain, Isrāfīl with the trumpet, and Mālik is the keeper of Hell."],
    de: ["Welcher Engel ist damit betraut, den Propheten die Offenbarung zu überbringen?", ["Ǧibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Ǧibrīl ist der Engel der Offenbarung, im Koran der vertrauenswürdige Geist genannt (26:193). Mīkāʾīl wird gewöhnlich mit dem Regen, Isrāfīl mit dem Horn verbunden, und Mālik ist der Hüter der Hölle."],
    ar: ["مَن الملَك الموكَّل بالوحي إلى الأنبياء؟", ["جبريل", "ميكائيل", "إسرافيل", "مالك"], "جبريل هو ملك الوحي، وسمّاه القرآن الروح الأمين (الشعراء 193)، ويُذكر ميكائيل بالقطر، وإسرافيل بالنفخ في الصور، ومالك خازن النار."] },

  { id: "aq-010", s: "aqidah", g: 1, d: 2, t: ["angels"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the creation of the angels", tr: ["sunni"],
    en: ["Which angel is commonly described by the scholars as entrusted with rain and vegetation?", ["Mīkāʾīl", "Jibrīl", "Isrāfīl", "Riḍwān"], "Scholars commonly mention Mīkāʾīl as the angel entrusted with rain and plants. Jibrīl is linked to revelation, which gives life to hearts, and Isrāfīl to the blowing of the trumpet."],
    de: ["Welcher Engel wird von den Gelehrten gewöhnlich als mit Regen und Pflanzenwuchs betraut beschrieben?", ["Mīkāʾīl", "Ǧibrīl", "Isrāfīl", "Riḍwān"], "Die Gelehrten nennen gewöhnlich Mīkāʾīl als den Engel, der mit Regen und Pflanzen betraut ist. Ǧibrīl ist mit der Offenbarung verbunden, die die Herzen belebt, und Isrāfīl mit dem Blasen des Horns."],
    ar: ["أيّ الملائكة يذكره العلماء عادةً موكَّلًا بالقطر والنبات؟", ["ميكائيل", "جبريل", "إسرافيل", "رضوان"], "يذكر العلماء عادةً أن ميكائيل موكّل بالقطر والنبات، وجبريل بالوحي الذي به حياة القلوب، وإسرافيل بالنفخ في الصور."] },

  { id: "aq-011", s: "aqidah", g: 1, d: 1, t: ["angels", "hell"], src: "Ibn Kathīr, Tafsīr, on 43:77", tr: ["sunni"], v: "43:77", w: 2,
    en: ["The people of Hell call out to an angel by name with the highlighted word. Who is he?", ["Mālik, the keeper of Hell", "Riḍwān, the keeper of Paradise", "The angel of death", "Isrāfīl, the blower of the trumpet"], "In the verse shown the people of the Fire call out to Mālik, asking that their Lord put an end to them. Mālik is the keeper of Hell named in the Quran."],
    de: ["Die Bewohner der Hölle rufen mit dem hervorgehobenen Wort einen Engel beim Namen. Wer ist es?", ["Mālik, der Hüter der Hölle", "Riḍwān, der Hüter des Paradieses", "Der Engel des Todes", "Isrāfīl, der das Horn bläst"], "Im angezeigten Vers rufen die Bewohner des Feuers Mālik an und bitten, ihr Herr möge ihrem Dasein ein Ende setzen. Mālik ist der im Koran genannte Hüter der Hölle."],
    ar: ["ينادي أهلُ النار ملَكًا باسمه في الكلمة المظللة، فمن هو؟", ["مالك خازن النار", "رضوان خازن الجنة", "ملك الموت", "إسرافيل صاحب الصور"], "في الآية المعروضة ينادي أهل النار مالكًا يسألونه أن يقضي عليهم ربهم، ومالك هو خازن النار المسمّى في القرآن."] },

  { id: "aq-012", s: "aqidah", g: 1, d: 1, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 4:163 and 5:44–46", tr: ["sunni"],
    en: ["To which prophet was the Tawrāt revealed?", ["Mūsā", "Dāwūd", "ʿĪsā", "Ibrāhīm"], "The Tawrāt was revealed to Mūsā, the Zabūr to Dāwūd and the Injīl to ʿĪsā. The Quran mentions scriptures (ṣuḥuf) of Ibrāhīm as well."],
    de: ["Welchem Propheten wurde die Tora (Tawrāt) offenbart?", ["Mūsā", "Dāwūd", "ʿĪsā", "Ibrāhīm"], "Die Tora wurde Mūsā offenbart, der Psalter (Zabūr) Dāwūd und das Evangelium (Inǧīl) ʿĪsā. Der Koran erwähnt auch Blätter (ṣuḥuf) Ibrāhīms."],
    ar: ["على أيّ نبي أُنزلت التوراة؟", ["موسى", "داود", "عيسى", "إبراهيم"], "أُنزلت التوراة على موسى، والزبور على داود، والإنجيل على عيسى، وذكر القرآن صحف إبراهيم كذلك."] },

  { id: "aq-013", s: "aqidah", g: 1, d: 1, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 4:163", tr: ["sunni"],
    en: ["To which prophet was the Zabūr given?", ["Dāwūd", "Sulaymān", "Mūsā", "Yaḥyā"], "The Quran states that Allah gave Dāwūd the Zabūr (4:163, 17:55). Sulaymān was his son, and Yaḥyā is not associated with a named book."],
    de: ["Welchem Propheten wurde der Psalter (Zabūr) gegeben?", ["Dāwūd", "Sulaimān", "Mūsā", "Yaḥyā"], "Der Koran sagt, dass Allah Dāwūd den Zabūr gab (4:163, 17:55). Sulaimān war sein Sohn, und mit Yaḥyā ist kein namentlich genanntes Buch verbunden."],
    ar: ["على أيّ نبي أُنزل الزبور؟", ["داود", "سليمان", "موسى", "يحيى"], "نصّ القرآن على أن الله آتى داود زبورًا (النساء 163، الإسراء 55)، وسليمان ابنه، ولم يُذكر ليحيى كتاب مسمّى."] },

  { id: "aq-014", s: "aqidah", g: 1, d: 1, t: ["books", "quran-preservation"], src: "Ibn Kathīr, Tafsīr, on 15:9", tr: ["sunni"],
    en: ["Which revealed book has Allah Himself guaranteed to preserve?", ["The Quran", "The Tawrāt", "The Injīl", "The Zabūr"], "In 15:9 Allah says that He sent down the Reminder and will preserve it. The earlier books were entrusted to their communities to guard (5:44) and were not preserved in their original form."],
    de: ["Welches offenbarte Buch hat Allah selbst zu bewahren zugesichert?", ["Den Koran", "Die Tora", "Das Evangelium", "Den Psalter"], "In 15:9 sagt Allah, dass Er die Ermahnung herabgesandt hat und sie bewahren wird. Die früheren Bücher wurden ihren Gemeinschaften zur Bewahrung anvertraut (5:44) und sind nicht in ihrer ursprünglichen Form erhalten."],
    ar: ["أيّ الكتب المنزلة تكفّل الله بنفسه بحفظه؟", ["القرآن", "التوراة", "الإنجيل", "الزبور"], "أخبر الله في سورة الحجر (الآية 9) أنه نزّل الذكر وأنه له حافظ، أما الكتب السابقة فاستُحفظ عليها أهلها (المائدة 44) فلم تبق على أصلها."] },

  { id: "aq-015", s: "aqidah", g: 1, d: 1, t: ["messengers", "finality-of-prophethood"], src: "Ibn Kathīr, Tafsīr, on 33:40", tr: ["ijma"], v: "33:40", w: 11,
    en: ["With the highlighted word and the word after it, how does the verse shown describe the Prophet Muḥammad?", ["As the Seal of the Prophets", "As the first of the messengers", "As the friend of Allah", "As the one spoken to directly"], "The verse calls the Prophet the Seal of the Prophets: no prophet comes after him. This is a matter of consensus; ʿĪsā's return at the end of time does not contradict it, as he was a prophet before."],
    de: ["Wie beschreibt der angezeigte Vers den Propheten Muḥammad mit dem hervorgehobenen Wort und dem folgenden?", ["Als Siegel der Propheten", "Als ersten der Gesandten", "Als Freund Allahs", "Als den, mit dem direkt gesprochen wurde"], "Der Vers nennt den Propheten das Siegel der Propheten: Nach ihm kommt kein Prophet. Darüber besteht Konsens; die Rückkehr ʿĪsās am Ende der Zeit widerspricht dem nicht, da er schon vorher Prophet war."],
    ar: ["بمَ تصف الآية المعروضة النبيَّ محمدًا ﷺ في الكلمة المظللة وما بعدها؟", ["خاتم النبيين", "أول المرسلين", "خليل الله", "كليم الله"], "وصفت الآية النبي ﷺ بأنه خاتم النبيين فلا نبي بعده، وهذا محل إجماع، ونزول عيسى آخر الزمان لا ينافيه لأنه نبي قبله."] },

  { id: "aq-016", s: "aqidah", g: 1, d: 1, t: ["messengers", "divine-speech"], src: "Ibn Kathīr, Tafsīr, on 4:164", tr: ["sunni"], v: "4:164", w: 13,
    en: ["The verse shown states that Allah spoke directly to the prophet named in the highlighted word. Who is he?", ["Mūsā", "Ibrāhīm", "Nūḥ", "ʿĪsā"], "The verse affirms that Allah spoke to Mūsā with real speech, emphasised by the verbal noun after his name. For this he is known as Kalīm Allāh."],
    de: ["Der angezeigte Vers sagt, dass Allah direkt mit dem Propheten sprach, der im hervorgehobenen Wort genannt wird. Wer ist es?", ["Mūsā", "Ibrāhīm", "Nūḥ", "ʿĪsā"], "Der Vers bekräftigt, dass Allah mit Mūsā wirklich sprach, betont durch das Verbalnomen nach seinem Namen. Deshalb ist er als Kalīm Allāh bekannt."],
    ar: ["تذكر الآية المعروضة أن الله كلّم النبيَّ المذكور في الكلمة المظللة تكليمًا، فمن هو؟", ["موسى", "إبراهيم", "نوح", "عيسى"], "أثبتت الآية أن الله كلّم موسى كلامًا حقيقيًا، وأكّده المصدر بعد اسمه، ولذلك لُقّب بكليم الله."] },

  { id: "aq-017", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 6,
    en: ["What does the divine name in the highlighted word mean?", ["The Ever-Living", "The All-Knowing", "The Most Merciful", "The Creator"], "Al-Ḥayy is the Ever-Living, whose life has no beginning and no end and is free of every deficiency. Scholars note that all the attributes of perfection depend on this perfect life."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Ewig-Lebendige", "Der Allwissende", "Der Allbarmherzige", "Der Schöpfer"], "Al-Ḥayy ist der Ewig-Lebendige, dessen Leben weder Anfang noch Ende hat und frei von jedem Mangel ist. Die Gelehrten betonen, dass alle Eigenschaften der Vollkommenheit auf diesem vollkommenen Leben beruhen."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الحي الدائم الحياة", "العليم", "الرحيم", "الخالق"], "الحي هو الذي له الحياة الكاملة التي لا ابتداء لها ولا انتهاء ولا يعتريها نقص، ونبّه العلماء على أن صفات الكمال كلها راجعة إلى كمال الحياة."] },

  { id: "aq-018", s: "aqidah", g: 1, d: 2, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 7,
    en: ["What does the divine name in the highlighted word mean?", ["The Self-Subsisting Sustainer", "The Most High above creation", "The Forgiver of all sins", "The Watcher over all things"], "Al-Qayyūm is the One who subsists by Himself, needing nothing, and by whom everything else subsists and is maintained. Al-ʿAliyy (the Most High) comes at the end of the same verse."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Beständige, der alles erhält", "Der Höchste über der Schöpfung", "Der Vergeber aller Sünden", "Der Wächter über alle Dinge"], "Al-Qayyūm ist der, der durch sich selbst besteht, nichts bedarf und durch den alles andere besteht und erhalten wird. Al-ʿAliyy (der Höchste) steht am Ende desselben Verses."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["القائم بنفسه المقيم لغيره", "العلي فوق كل شيء", "الغافر للذنوب", "الرقيب على كل شيء"], "القيوم هو القائم بنفسه الغني عن كل ما سواه، وبه قام كل شيء، أما العلي فقد جاء في آخر الآية نفسها."] },

  { id: "aq-019", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:2", tr: ["sunni"], v: "112:2", w: 2,
    en: ["Which meaning do the exegetes give for the divine name in the highlighted word?", ["The Master all turn to in need", "The One who is First before all", "The Lord of the daybreak", "The Owner of the mighty Throne"], "Al-Ṣamad is explained by Ibn ʿAbbās and others as the Master perfect in His attributes, to whom all creatures turn in their needs, while He needs no one."],
    de: ["Welche Bedeutung geben die Exegeten dem göttlichen Namen im hervorgehobenen Wort?", ["Der Herr, an den sich alle in Not wenden", "Der Erste vor allen Dingen", "Der Herr der Morgendämmerung", "Der Herr des gewaltigen Thrones"], "Aṣ-Ṣamad wird von Ibn ʿAbbās und anderen erklärt als der in Seinen Eigenschaften vollkommene Herr, an den sich alle Geschöpfe in ihren Bedürfnissen wenden, während Er niemanden braucht."],
    ar: ["ما المعنى الذي يذكره المفسرون للاسم الإلهي في الكلمة المظللة؟", ["السيد الذي تصمد إليه الخلائق", "الأول الذي ليس قبله شيء", "رب الفلق والصبح", "صاحب العرش العظيم"], "فسّر ابن عباس وغيره الصمد بالسيد الكامل في صفاته الذي تقصده الخلائق في حوائجها وهو غني عنها."] },

  { id: "aq-020", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:1", tr: ["sunni"], v: "112:1", w: 4,
    en: ["What does the highlighted word affirm about Allah?", ["That He is One and unique", "That He is the Most Merciful", "That He is the Most High", "That He is the Creator"], "Aḥad affirms that Allah is one and unique in His essence, attributes and acts, with none like Him. This is why Sūrat al-Ikhlāṣ is the sūra of tawḥīd."],
    de: ["Was bekräftigt das hervorgehobene Wort über Allah?", ["Dass Er der Eine und Einzigartige ist", "Dass Er der Allbarmherzige ist", "Dass Er der Höchste ist", "Dass Er der Schöpfer ist"], "Aḥad bekräftigt, dass Allah in Seinem Wesen, Seinen Eigenschaften und Handlungen einer und einzigartig ist, ohne dass Ihm etwas gleicht. Deshalb ist Sūrat al-Iḫlāṣ die Sure des Tauḥīd."],
    ar: ["ماذا تُثبت الكلمة المظللة لله تعالى؟", ["أنه الواحد المتفرد", "أنه الرحيم", "أنه العلي", "أنه الخالق"], "الأحد يثبت أن الله واحد متفرد في ذاته وصفاته وأفعاله لا نظير له، ولذلك كانت سورة الإخلاص سورة التوحيد."] },

  { id: "aq-021", s: "aqidah", g: 1, d: 2, t: ["surat-al-ikhlas", "tawhid"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān", tr: ["sunni"],
    en: ["According to the hadith in Ṣaḥīḥ al-Bukhārī, Sūrat al-Ikhlāṣ is equal to what portion of the Quran?", ["A third", "A quarter", "A half", "A tenth"], "The Prophet said that Sūrat al-Ikhlāṣ equals a third of the Quran. Many scholars explain that the Quran deals with rulings, narratives and tawḥīd, and this sūra is devoted entirely to tawḥīd."],
    de: ["Welchem Teil des Korans entspricht Sūrat al-Iḫlāṣ laut dem Hadith im Ṣaḥīḥ al-Buḫārī?", ["Einem Drittel", "Einem Viertel", "Der Hälfte", "Einem Zehntel"], "Der Prophet sagte, dass Sūrat al-Iḫlāṣ einem Drittel des Korans entspricht. Viele Gelehrte erklären, dass der Koran Bestimmungen, Erzählungen und Tauḥīd behandelt und diese Sure ganz dem Tauḥīd gewidmet ist."],
    ar: ["بحسب الحديث في صحيح البخاري، سورة الإخلاص تعدل كم من القرآن؟", ["ثلثه", "ربعه", "نصفه", "عشره"], "أخبر النبي ﷺ أن سورة الإخلاص تعدل ثلث القرآن، وفسّره كثير من العلماء بأن القرآن أحكام وقصص وتوحيد، وهذه السورة خالصة في التوحيد."] },

  { id: "aq-022", s: "aqidah", g: 1, d: 2, t: ["ayat-al-kursi"], src: "Muslim, al-Ṣaḥīḥ, Kitāb Ṣalāt al-Musāfirīn (virtue of Āyat al-Kursī)", tr: ["sunni"], v: "2:255",
    en: ["According to the hadith of Ubayy ibn Kaʿb in Ṣaḥīḥ Muslim, what is special about the verse shown?", ["It is the greatest verse in the Book of Allah", "It was the first verse revealed", "It was the last verse revealed", "It is the longest verse of the Quran"], "The Prophet asked Ubayy which verse of the Book of Allah is greatest, and he named Āyat al-Kursī, and the Prophet praised his knowledge. The longest verse of the Quran is 2:282, not this one."],
    de: ["Was ist laut dem Hadith von Ubayy ibn Kaʿb im Ṣaḥīḥ Muslim das Besondere am angezeigten Vers?", ["Er ist der gewaltigste Vers im Buch Allahs", "Er war der erste offenbarte Vers", "Er war der letzte offenbarte Vers", "Er ist der längste Vers des Korans"], "Der Prophet fragte Ubayy, welcher Vers im Buch Allahs der gewaltigste sei; er nannte den Thronvers, und der Prophet lobte sein Wissen. Der längste Vers des Korans ist 2:282, nicht dieser."],
    ar: ["بحسب حديث أُبيّ بن كعب في صحيح مسلم، ما الذي تختص به الآية المعروضة؟", ["أنها أعظم آية في كتاب الله", "أنها أول ما نزل", "أنها آخر ما نزل", "أنها أطول آية في القرآن"], "سأل النبي ﷺ أُبيًّا عن أعظم آية في كتاب الله فذكر آية الكرسي، فأثنى على علمه، وأطول آية في القرآن آية الدَّين لا هذه."] },

  { id: "aq-023", s: "aqidah", g: 1, d: 1, t: ["barzakh", "last-day"], src: "Ibn al-Qayyim, Kitāb al-Rūḥ, on the barzakh", tr: ["sunni"],
    en: ["What is meant by the barzakh in creed?", ["The stage between death and the resurrection", "The bridge stretched over Hell", "The wall between Paradise and Hell", "The gathering place on the Day of Judgment"], "Barzakh means a barrier; in creed it is the life of the grave between death and resurrection, in which there is bliss or punishment. The bridge is al-Ṣirāṭ and the wall between Paradise and Hell is linked to al-Aʿrāf."],
    de: ["Was ist in der Glaubenslehre mit dem Barzaḫ gemeint?", ["Die Zwischenstufe zwischen Tod und Auferstehung", "Die Brücke über der Hölle", "Die Mauer zwischen Paradies und Hölle", "Der Versammlungsort am Tag des Gerichts"], "Barzaḫ bedeutet Schranke; in der Glaubenslehre ist es das Leben im Grab zwischen Tod und Auferstehung, in dem es Wonne oder Strafe gibt. Die Brücke ist aṣ-Ṣirāṭ, die Mauer zwischen Paradies und Hölle ist mit al-Aʿrāf verbunden."],
    ar: ["ما المقصود بالبرزخ في العقيدة؟", ["المرحلة بين الموت والبعث", "الجسر المنصوب على جهنم", "السور بين الجنة والنار", "موقف الحشر يوم القيامة"], "البرزخ لغة الحاجز، وهو في العقيدة حياة القبر بين الموت والبعث وفيها نعيم أو عذاب، أما الجسر فهو الصراط، والسور بين الجنة والنار متعلق بالأعراف."] },

  { id: "aq-024", s: "aqidah", g: 1, d: 2, t: ["barzakh", "angels"], src: "al-Tirmidhī, al-Jāmiʿ, Kitāb al-Janāʾiz (questioning in the grave)", tr: ["sunni"],
    en: ["By which names are the two angels who question the dead in the grave known, as in a hadith in Jāmiʿ al-Tirmidhī?", ["Munkar and Nakīr", "Hārūt and Mārūt", "Raqīb and ʿAtīd", "Jibrīl and Mīkāʾīl"], "A hadith in al-Tirmidhī names the two questioning angels Munkar and Nakīr. Hārūt and Mārūt are mentioned in 2:102 in connection with Babylon, and Raqīb and ʿAtīd are descriptions of the recording angels in 50:18."],
    de: ["Unter welchen Namen sind die beiden Engel bekannt, die die Toten im Grab befragen, wie in einem Hadith bei at-Tirmiḏī?", ["Munkar und Nakīr", "Hārūt und Mārūt", "Raqīb und ʿAtīd", "Ǧibrīl und Mīkāʾīl"], "Ein Hadith bei at-Tirmiḏī nennt die beiden befragenden Engel Munkar und Nakīr. Hārūt und Mārūt werden in 2:102 im Zusammenhang mit Babylon erwähnt, Raqīb und ʿAtīd sind Beschreibungen der aufzeichnenden Engel in 50:18."],
    ar: ["ما اسما الملكين اللذين يسألان الميت في قبره كما في حديث عند الترمذي؟", ["منكر ونكير", "هاروت وماروت", "رقيب وعتيد", "جبريل وميكائيل"], "سمّى حديث عند الترمذي ملكي السؤال منكرًا ونكيرًا، أما هاروت وماروت فذُكرا في البقرة (102) في شأن بابل، ورقيب وعتيد وصفان للملكين الكاتبين في سورة ق (18)."] },

  { id: "aq-025", s: "aqidah", g: 1, d: 1, t: ["sirat", "last-day"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya; Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of the intercession)", tr: ["sunni"],
    en: ["What is al-Ṣirāṭ on the Day of Judgment?", ["A bridge set over Hell that people must cross", "The scale on which deeds are weighed", "The basin from which believers drink", "The book of deeds given to each person"], "Al-Ṣirāṭ is a bridge stretched over Hell; people cross it according to their deeds. The scale is the mīzān, the basin is the ḥawḍ, and the record of deeds is the kitāb."],
    de: ["Was ist aṣ-Ṣirāṭ am Tag des Gerichts?", ["Eine Brücke über der Hölle, die die Menschen überqueren müssen", "Die Waage, auf der die Taten gewogen werden", "Das Becken, aus dem die Gläubigen trinken", "Das Buch der Taten, das jeder erhält"], "Aṣ-Ṣirāṭ ist eine über der Hölle gespannte Brücke, die die Menschen gemäß ihren Taten überqueren. Die Waage ist die Mīzān, das Becken der Ḥauḍ, und die Aufzeichnung der Taten das Buch (kitāb)."],
    ar: ["ما الصراط يوم القيامة؟", ["جسر منصوب على متن جهنم يعبره الناس", "الميزان الذي توزن به الأعمال", "الحوض الذي يشرب منه المؤمنون", "كتاب الأعمال الذي يُعطاه كل إنسان"], "الصراط جسر منصوب على جهنم يمرّ عليه الناس على قدر أعمالهم، أما الميزان فتوزن به الأعمال، والحوض يرده المؤمنون، والكتاب صحيفة الأعمال."] },

  { id: "aq-026", s: "aqidah", g: 1, d: 2, t: ["hawd", "last-day"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Riqāq (on the ḥawḍ)", tr: ["sunni"],
    en: ["What is the ḥawḍ affirmed by Ahl al-Sunna?", ["The Prophet's basin from which his community drinks", "A river flowing beneath the Throne of Allah", "The spring in which the dead are washed", "The well of Zamzam brought to the Hereafter"], "The ḥawḍ is the basin granted to the Prophet on the Day of Judgment; authentic hadith describe its water as whiter than milk and sweeter than honey, and whoever drinks from it will never thirst again."],
    de: ["Was ist der von Ahl as-Sunna bekräftigte Ḥauḍ?", ["Das Becken des Propheten, aus dem seine Gemeinschaft trinkt", "Ein Fluss, der unter dem Thron Allahs fließt", "Die Quelle, in der die Toten gewaschen werden", "Der Zamzam-Brunnen, ins Jenseits gebracht"], "Der Ḥauḍ ist das Becken, das dem Propheten am Tag des Gerichts gegeben wird; authentische Hadithe beschreiben sein Wasser als weißer als Milch und süßer als Honig, und wer daraus trinkt, wird nie wieder Durst haben."],
    ar: ["ما الحوض الذي يثبته أهل السنة؟", ["حوض النبي ﷺ الذي ترده أمته", "نهر يجري تحت العرش", "عين يُغسل بها الموتى", "بئر زمزم في الآخرة"], "الحوض هو الحوض المعطى للنبي ﷺ في عرصات القيامة، ووصفت الأحاديث الصحيحة ماءه بأنه أشد بياضًا من اللبن وأحلى من العسل، من شرب منه لم يظمأ بعده أبدًا."] },

  { id: "aq-027", s: "aqidah", g: 1, d: 2, t: ["qadar"], src: "Ibn Kathīr, Tafsīr, on 54:49", tr: ["sunni"], v: "54:49", w: 5,
    en: ["The highlighted word states that Allah created everything with what?", ["With a decree and measure (qadar)", "With a fixed number of days", "With a written covenant", "With the help of the angels"], "The verse states that Allah created everything according to qadar: a measure and decree He determined beforehand. Scholars cite it among the main Quranic proofs of the sixth pillar of faith."],
    de: ["Womit hat Allah laut dem hervorgehobenen Wort alles erschaffen?", ["Nach einem Maß und einer Bestimmung (qadar)", "In einer festen Zahl von Tagen", "Mit einem schriftlichen Bund", "Mit Hilfe der Engel"], "Der Vers sagt, dass Allah alles gemäß dem Qadar erschaffen hat: einem Maß und einer Bestimmung, die Er vorher festgelegt hat. Die Gelehrten nennen ihn unter den wichtigsten Koranbelegen der sechsten Glaubenssäule."],
    ar: ["بمَ خلق الله كل شيء بحسب الكلمة المظللة؟", ["بقدر وتقدير سابق", "في عدد معلوم من الأيام", "بعهد مكتوب", "بمعونة الملائكة"], "تقرر الآية أن الله خلق كل شيء بقدر، أي بتقدير سابق منه، ويذكرها العلماء من أظهر أدلة القرآن على الركن السادس من أركان الإيمان."] },

  { id: "aq-028", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 8,
    en: ["What does the divine name in the highlighted word mean?", ["The King, the Sovereign", "The Most Holy", "The Guardian", "The Compeller"], "Al-Malik is the King who owns and governs all things with complete authority. Al-Quddūs (the Most Holy), al-Muhaymin (the Guardian) and al-Jabbār (the Compeller) follow in the same verse."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der König, der Herrscher", "Der Allheilige", "Der Wächter", "Der Allgewaltige"], "Al-Malik ist der König, der alle Dinge mit vollkommener Macht besitzt und lenkt. Al-Quddūs (der Allheilige), al-Muhaimin (der Wächter) und al-Ǧabbār (der Allgewaltige) folgen im selben Vers."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الملك ذو السلطان التام", "القدوس", "المهيمن", "الجبار"], "الملك هو المالك لكل شيء المتصرف فيه بسلطان تام، أما القدوس والمهيمن والجبار فجاءت بعده في الآية نفسها."] },

  { id: "aq-029", s: "aqidah", g: 1, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:24", tr: ["sunni"], v: "59:24", w: 3,
    en: ["What does the divine name in the highlighted word mean?", ["The Creator who determines all things", "The Fashioner who gives forms", "The Originator who brings into being", "The All-Wise in His decisions"], "Al-Khāliq is the Creator who determines and brings things about. The verse then names al-Bāriʾ (the Originator) and al-Muṣawwir (the Fashioner), and closes with al-ʿAzīz al-Ḥakīm."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Schöpfer, der alle Dinge bestimmt", "Der Gestalter, der die Formen gibt", "Der Erschaffer, der ins Dasein bringt", "Der Allweise in Seinen Entscheidungen"], "Al-Ḫāliq ist der Schöpfer, der die Dinge bestimmt und hervorbringt. Der Vers nennt danach al-Bāriʾ (den Erschaffer) und al-Muṣawwir (den Gestalter) und schließt mit al-ʿAzīz al-Ḥakīm."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الخالق المقدّر للأشياء", "المصوّر الذي يعطي الصور", "البارئ الموجد", "الحكيم في تدبيره"], "الخالق هو المقدّر الموجد للأشياء، ثم ذكرت الآية البارئ والمصوّر، وختمت بالعزيز الحكيم."] },

  { id: "aq-030", s: "aqidah", g: 2, d: 2, t: ["hadith-jibril", "ihsan"], src: "al-Nawawī, al-Arbaʿūn al-Nawawiyya, hadith 2", tr: ["sunni"],
    en: ["At the end of the hadith of Jibrīl, what did the Prophet say was the purpose of Jibrīl's visit?", ["To teach the people their religion", "To announce the signs of the Hour", "To test the knowledge of ʿUmar", "To bring a new revelation of the Quran"], "The Prophet said that it was Jibrīl, who came to teach the people their religion. Scholars therefore see islām, īmān and iḥsān together as the levels of the whole religion."],
    de: ["Was nannte der Prophet am Ende des Hadith von Ǧibrīl als Zweck seines Besuchs?", ["Den Menschen ihre Religion zu lehren", "Die Zeichen der Stunde anzukündigen", "Das Wissen ʿUmars zu prüfen", "Eine neue Koranoffenbarung zu bringen"], "Der Prophet sagte, es sei Ǧibrīl gewesen, der kam, um die Menschen ihre Religion zu lehren. Deshalb sehen die Gelehrten Islām, Īmān und Iḥsān zusammen als die Stufen der ganzen Religion."],
    ar: ["ماذا ذكر النبي ﷺ في آخر حديث جبريل غرضًا لمجيئه؟", ["أن يعلّم الناس دينهم", "أن يخبر بأشراط الساعة", "أن يختبر علم عمر", "أن ينزل بقرآن جديد"], "قال النبي ﷺ إنه جبريل أتى يعلّم الناس دينهم، ولذلك عدّ العلماء الإسلام والإيمان والإحسان مراتب الدين كله."] },

  { id: "aq-031", s: "aqidah", g: 2, d: 2, t: ["hadith-jibril", "signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["When asked in the hadith of Jibrīl about the time of the Hour, what did the Prophet reply?", ["The one asked knows no more than the one asking", "It will come after a thousand years", "It will come on a Friday in Muḥarram", "Only Jibrīl has been told its time"], "The Prophet answered that the one asked knows no better than the questioner, showing that knowledge of the Hour belongs to Allah alone. He then mentioned some of its signs."],
    de: ["Was antwortete der Prophet im Hadith von Ǧibrīl auf die Frage nach dem Zeitpunkt der Stunde?", ["Der Gefragte weiß darüber nicht mehr als der Fragende", "Sie kommt nach tausend Jahren", "Sie kommt an einem Freitag im Muḥarram", "Nur Ǧibrīl kennt ihre Zeit"], "Der Prophet antwortete, der Gefragte wisse darüber nicht mehr als der Fragende; das Wissen um die Stunde gehört allein Allah. Danach nannte er einige ihrer Zeichen."],
    ar: ["بمَ أجاب النبي ﷺ في حديث جبريل حين سُئل عن وقت الساعة؟", ["ما المسؤول عنها بأعلم من السائل", "تقوم بعد ألف سنة", "تقوم يوم جمعة في المحرم", "لم يُخبَر بوقتها إلا جبريل"], "أجاب النبي ﷺ بأن المسؤول ليس أعلم بها من السائل، فعلم الساعة مما استأثر الله به، ثم ذكر بعض أماراتها."] },

  { id: "aq-032", s: "aqidah", g: 2, d: 3, t: ["hadith-jibril", "signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["Which sign of the Hour is mentioned in the hadith of Jibrīl?", ["Barefoot shepherds competing in tall buildings", "The sun rising from the place of its setting", "The emergence of the Beast from the earth", "The descent of ʿĪsā son of Maryam"], "In the hadith of Jibrīl the Prophet mentions that the slave woman gives birth to her mistress and that barefoot, destitute shepherds compete in constructing tall buildings. The other three are major signs from other hadith."],
    de: ["Welches Zeichen der Stunde wird im Hadith von Ǧibrīl erwähnt?", ["Barfüßige Hirten wetteifern im Bau hoher Gebäude", "Die Sonne geht an ihrem Untergangsort auf", "Das Tier kommt aus der Erde hervor", "ʿĪsā, der Sohn Maryams, steigt herab"], "Im Hadith von Ǧibrīl erwähnt der Prophet, dass die Sklavin ihre Herrin gebärt und barfüßige, mittellose Hirten im Bau hoher Gebäude wetteifern. Die anderen drei sind große Zeichen aus anderen Hadithen."],
    ar: ["أيّ أمارات الساعة ورد في حديث جبريل؟", ["تطاول الحفاة العراة رعاء الشاء في البنيان", "طلوع الشمس من مغربها", "خروج الدابة", "نزول عيسى"], "ذكر النبي ﷺ في حديث جبريل أن تلد الأمة ربتها وأن يتطاول الحفاة العراة العالة رعاء الشاء في البنيان، أما الثلاثة الأخرى فمن العلامات الكبرى في أحاديث أخرى."] },

  { id: "aq-033", s: "aqidah", g: 2, d: 2, t: ["tawhid", "tawhid-categories"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["athari"],
    en: ["In the threefold division of tawḥīd common in the Atharī tradition, what is tawḥīd al-rubūbiyya?", ["Affirming Allah alone as Creator, Owner and Disposer", "Directing all acts of worship to Allah alone", "Affirming Allah's names and attributes", "Following the Prophet alone in religion"], "Tawḥīd al-rubūbiyya is singling Allah out in His acts: creating, owning, providing and governing. Directing worship to Him alone is tawḥīd al-ulūhiyya, and affirming His names and attributes is tawḥīd al-asmāʾ wa-l-ṣifāt."],
    de: ["Was ist in der im atharitischen Lehrstrang üblichen Dreiteilung des Tauḥīd der Tauḥīd ar-rubūbiyya?", ["Allah allein als Schöpfer, Besitzer und Lenker zu bekräftigen", "Alle Gottesdienste allein an Allah zu richten", "Allahs Namen und Eigenschaften zu bekräftigen", "Allein dem Propheten in der Religion zu folgen"], "Tauḥīd ar-rubūbiyya heißt, Allah in Seinen Handlungen einzig zu machen: Erschaffen, Besitzen, Versorgen und Lenken. Die Anbetung allein an Ihn zu richten ist Tauḥīd al-ulūhiyya, Seine Namen und Eigenschaften zu bekräftigen Tauḥīd al-asmāʾ wa-ṣ-ṣifāt."],
    ar: ["في التقسيم الثلاثي للتوحيد المشهور عند الأثرية، ما توحيد الربوبية؟", ["إفراد الله بالخلق والملك والتدبير", "إفراد الله بجميع أنواع العبادة", "إثبات أسماء الله وصفاته", "إفراد النبي ﷺ بالاتباع"], "توحيد الربوبية إفراد الله بأفعاله من الخلق والملك والرزق والتدبير، أما إفراده بالعبادة فتوحيد الألوهية، وإثبات الأسماء والصفات توحيد الأسماء والصفات."] },

  { id: "aq-034", s: "aqidah", g: 2, d: 2, t: ["tawhid", "tawhid-categories"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["athari"],
    en: ["In the same threefold division, what does tawḥīd al-ulūhiyya mean?", ["Directing all worship to Allah alone", "Believing that Allah alone creates", "Affirming that Allah has no beginning", "Believing that Allah alone knows the unseen"], "Tawḥīd al-ulūhiyya (also called tawḥīd al-ʿibāda) is singling Allah out with every act of worship: prayer, supplication, sacrifice, vows, reliance and the like. It is the meaning of the testimony that there is no god but Allah."],
    de: ["Was bedeutet in derselben Dreiteilung der Tauḥīd al-ulūhiyya?", ["Jede Anbetung allein an Allah zu richten", "Zu glauben, dass allein Allah erschafft", "Zu bekräftigen, dass Allah keinen Anfang hat", "Zu glauben, dass allein Allah das Verborgene kennt"], "Tauḥīd al-ulūhiyya (auch Tauḥīd al-ʿibāda) heißt, Allah mit jeder Form der Anbetung allein zu meinen: Gebet, Bittgebet, Opfer, Gelübde, Gottvertrauen und Ähnliches. Das ist die Bedeutung des Bekenntnisses, dass es keinen Gott außer Allah gibt."],
    ar: ["في التقسيم نفسه، ما معنى توحيد الألوهية؟", ["إفراد الله بجميع العبادات", "اعتقاد أن الله وحده الخالق", "إثبات أن الله لا ابتداء له", "اعتقاد أن الله وحده يعلم الغيب"], "توحيد الألوهية ويسمّى توحيد العبادة هو إفراد الله بكل عبادة من صلاة ودعاء وذبح ونذر وتوكل ونحوها، وهو معنى شهادة أن لا إله إلا الله."] },

  { id: "aq-035", s: "aqidah", g: 2, d: 3, t: ["tawhid", "tawhid-categories"], src: "al-Bayjūrī, Tuḥfat al-Murīd sharḥ Jawharat al-Tawḥīd, on waḥdāniyya", tr: ["ashari", "maturidi"],
    en: ["Ashʿarī and Māturīdī texts commonly explain Allah's oneness (waḥdāniyya) as oneness in which three respects?", ["Essence, attributes and acts", "Lordship, worship and names", "Knowledge, power and will", "Speech, hearing and sight"], "Kalām manuals explain waḥdāniyya as oneness in essence (no composition and no second), in attributes (none like His) and in acts (no creator besides Him). The lordship–worship–names scheme is the common Atharī division."],
    de: ["Wie erklären ašʿaritische und māturīditische Texte die Einheit Allahs (waḥdāniyya) üblicherweise, nämlich als Einheit in welchen drei Hinsichten?", ["Wesen, Eigenschaften und Handlungen", "Herrschaft, Anbetung und Namen", "Wissen, Macht und Wille", "Rede, Hören und Sehen"], "Die Kalām-Handbücher erklären die Waḥdāniyya als Einheit im Wesen (keine Zusammensetzung, kein Zweiter), in den Eigenschaften (keine gleichen den Seinen) und in den Handlungen (kein Schöpfer außer Ihm). Das Schema Herrschaft–Anbetung–Namen ist die übliche atharitische Einteilung."],
    ar: ["كيف تشرح كتب الأشاعرة والماتريدية الوحدانية عادةً، أي وحدانية في أيّ ثلاثة أمور؟", ["في الذات والصفات والأفعال", "في الربوبية والألوهية والأسماء", "في العلم والقدرة والإرادة", "في الكلام والسمع والبصر"], "تشرح كتب الكلام الوحدانية بأنها وحدانية الذات فلا تركيب ولا ثاني، ووحدانية الصفات فلا مثيل لصفاته، ووحدانية الأفعال فلا خالق سواه، أما تقسيم الربوبية والألوهية والأسماء فهو التقسيم المشهور عند الأثرية."] },

  { id: "aq-036", s: "aqidah", g: 2, d: 2, t: ["shirk", "minor-shirk"], src: "Aḥmad, al-Musnad, hadith of Maḥmūd ibn Labīd (the minor shirk)", tr: ["sunni"],
    en: ["What did the Prophet call \"the minor shirk\", which he feared most for his community?", ["Showing off in worship (riyāʾ)", "Praying to idols", "Denying the Last Day", "Swearing falsely in trade"], "In the hadith of Maḥmūd ibn Labīd in the Musnad, the Prophet said what he feared most for them was the minor shirk, and when asked, he said it is riyāʾ: doing a deed of worship to be seen by people."],
    de: ["Was nannte der Prophet „den kleinen Širk“, den er für seine Gemeinschaft am meisten fürchtete?", ["Das Zur-Schau-Stellen im Gottesdienst (riyāʾ)", "Das Beten zu Götzen", "Das Leugnen des Jüngsten Tages", "Das falsche Schwören im Handel"], "Im Hadith von Maḥmūd ibn Labīd im Musnad sagte der Prophet, er fürchte für sie am meisten den kleinen Širk; auf Nachfrage sagte er, es sei Riyāʾ: eine gottesdienstliche Handlung zu verrichten, um von Menschen gesehen zu werden."],
    ar: ["ما الذي سمّاه النبي ﷺ «الشرك الأصغر» وكان أخوف ما يخافه على أمته؟", ["الرياء في العبادة", "دعاء الأصنام", "إنكار اليوم الآخر", "الحلف الكاذب في البيع"], "في حديث محمود بن لبيد في المسند أخبر النبي ﷺ أن أخوف ما يخاف عليهم الشرك الأصغر، فلما سُئل عنه قال: الرياء، وهو أن يعمل العبادة ليراه الناس."] },

  { id: "aq-037", s: "aqidah", g: 2, d: 3, t: ["shirk", "minor-shirk"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on shirk", tr: ["sunni"],
    en: ["What is the main difference between major and minor shirk according to the scholars?", ["Major shirk takes one out of Islam; minor shirk does not by itself", "Minor shirk is in the heart; major shirk only on the tongue", "Major shirk is forgiven by good deeds; minor is not", "Minor shirk concerns other religions; major concerns Muslims"], "Major shirk, such as worshipping other than Allah, takes a person out of Islam and is not forgiven if one dies upon it. Minor shirk, such as slight riyāʾ, is a grave sin and a means to major shirk, but does not by itself remove one from Islam."],
    de: ["Was ist laut den Gelehrten der Hauptunterschied zwischen großem und kleinem Širk?", ["Großer Širk führt aus dem Islam; kleiner Širk für sich allein nicht", "Kleiner Širk ist im Herzen, großer nur auf der Zunge", "Großer Širk wird durch gute Taten getilgt, kleiner nicht", "Kleiner Širk betrifft andere Religionen, großer die Muslime"], "Großer Širk, etwa die Anbetung von etwas außer Allah, führt aus dem Islam und wird nicht vergeben, wenn man darauf stirbt. Kleiner Širk, etwa ein wenig Riyāʾ, ist eine schwere Sünde und ein Weg zum großen, führt aber für sich allein nicht aus dem Islam."],
    ar: ["ما الفرق الأساسي بين الشرك الأكبر والأصغر عند العلماء؟", ["الأكبر يخرج من الملة والأصغر لا يخرج بذاته", "الأصغر في القلب والأكبر باللسان فقط", "الأكبر تكفّره الحسنات والأصغر لا", "الأصغر في سائر الأديان والأكبر في المسلمين"], "الشرك الأكبر كعبادة غير الله يخرج من الملة ولا يُغفر لمن مات عليه، والأصغر كيسير الرياء كبيرة من الكبائر ووسيلة إلى الأكبر لكنه لا يخرج من الملة بذاته."] },

  { id: "aq-038", s: "aqidah", g: 2, d: 3, t: ["shirk", "tawhid"], src: "al-Tirmidhī, al-Jāmiʿ, Kitāb al-Daʿawāt (supplication is worship)", tr: ["sunni"],
    en: ["Which hadith, narrated by al-Nuʿmān ibn Bashīr in the Sunan, shows that supplication must be directed to Allah alone?", ["Supplication is worship", "Actions are by intentions", "The religion is sincere counsel", "Leave what makes you doubt"], "The Prophet said that supplication is worship and then recited 40:60. Since duʿāʾ is worship, directing it to anyone besides Allah contradicts tawḥīd al-ʿibāda."],
    de: ["Welcher Hadith, überliefert von an-Nuʿmān ibn Bašīr in den Sunan, zeigt, dass das Bittgebet allein an Allah zu richten ist?", ["Das Bittgebet ist Anbetung", "Die Taten gelten nach den Absichten", "Die Religion ist aufrichtiger Rat", "Das Meiden dessen, was Zweifel weckt"], "Der Prophet sagte, das Bittgebet sei Anbetung, und rezitierte dann 40:60. Da Duʿāʾ Anbetung ist, widerspricht es dem Tauḥīd der Anbetung, es an jemand anderen als Allah zu richten."],
    ar: ["أيّ حديث يرويه النعمان بن بشير في السنن يدل على أن الدعاء لا يُصرف إلا لله؟", ["الدعاء هو العبادة", "إنما الأعمال بالنيات", "الدين النصيحة", "دع ما يريبك"], "قال النبي ﷺ: الدعاء هو العبادة، ثم تلا آية غافر (60)، فإذا كان الدعاء عبادة كان صرفه لغير الله منافيًا لتوحيد العبادة."] },

  { id: "aq-039", s: "aqidah", g: 2, d: 2, t: ["beautiful-names"], src: "Ibn Kathīr, Tafsīr, on 7:180", tr: ["sunni"], v: "7:180",
    en: ["What does the verse shown instruct the believers to do with Allah's beautiful names?", ["To call upon Him by them", "To write them on their homes", "To count them on their fingers", "To keep them secret from others"], "The verse states that the most beautiful names belong to Allah and commands that He be called upon by them, and warns against those who deviate regarding His names."],
    de: ["Wozu fordert der angezeigte Vers die Gläubigen in Bezug auf Allahs schönste Namen auf?", ["Ihn mit ihnen anzurufen", "Sie an ihre Häuser zu schreiben", "Sie an den Fingern abzuzählen", "Sie vor anderen geheim zu halten"], "Der Vers sagt, dass Allah die schönsten Namen gehören, befiehlt, Ihn mit ihnen anzurufen, und warnt vor denen, die bei Seinen Namen abweichen."],
    ar: ["بمَ تأمر الآية المعروضة المؤمنين في شأن أسماء الله الحسنى؟", ["أن يدعوه بها", "أن يكتبوها على بيوتهم", "أن يعدّوها على أصابعهم", "أن يكتموها عن الناس"], "تقرر الآية أن لله الأسماء الحسنى وتأمر بدعائه بها، وتحذّر من الذين يلحدون في أسمائه."] },

  { id: "aq-040", s: "aqidah", g: 2, d: 2, t: ["beautiful-names"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tawḥīd (Allah has ninety-nine names)", tr: ["sunni"],
    en: ["According to the hadith of Abū Hurayra in al-Bukhārī and Muslim, whoever does what with Allah's ninety-nine names enters Paradise?", ["Whoever enumerates (aḥṣā) them", "Whoever writes them down", "Whoever hangs them in his house", "Whoever hears them once"], "The hadith says that Allah has ninety-nine names, one hundred less one, and whoever enumerates them (aḥṣāhā) enters Paradise. Scholars explain this as learning them, understanding their meanings and acting by them."],
    de: ["Wer tritt laut dem Hadith von Abū Huraira bei al-Buḫārī und Muslim ins Paradies, in Bezug auf Allahs neunundneunzig Namen?", ["Wer sie erfasst (aḥṣā)", "Wer sie aufschreibt", "Wer sie in seinem Haus aufhängt", "Wer sie einmal hört"], "Der Hadith sagt, dass Allah neunundneunzig Namen hat, hundert weniger einen, und wer sie erfasst (aḥṣāhā), ins Paradies eintritt. Die Gelehrten erklären dies als Lernen der Namen, Verstehen ihrer Bedeutungen und Handeln danach."],
    ar: ["بحسب حديث أبي هريرة في الصحيحين، مَن الذي يدخل الجنة في شأن أسماء الله التسعة والتسعين؟", ["من أحصاها", "من كتبها", "من علّقها في بيته", "من سمعها مرة"], "في الحديث أن لله تسعة وتسعين اسمًا مائة إلا واحدًا من أحصاها دخل الجنة، وفسّر العلماء الإحصاء بحفظها وفهم معانيها والعمل بمقتضاها."] },

  { id: "aq-041", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 9,
    en: ["What does the divine name in the highlighted word mean?", ["The Most Holy, free of every imperfection", "The Source of peace and safety", "The Guardian over all things", "The Supreme in greatness"], "Al-Quddūs is the One utterly pure and free from every deficiency and fault, deserving every praise. Al-Salām, which follows, is often explained as the One free of defects and the source of safety."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Allheilige, frei von jedem Mangel", "Die Quelle des Friedens und der Sicherheit", "Der Wächter über alle Dinge", "Der in Größe Erhabene"], "Al-Quddūs ist der völlig Reine, frei von jedem Mangel und Fehler, dem jedes Lob gebührt. As-Salām, das folgt, wird oft als der Makellose und die Quelle der Sicherheit erklärt."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["المنزّه المطهّر عن كل نقص", "مصدر السلام والأمان", "المهيمن على كل شيء", "المتعالي في عظمته"], "القدوس هو الطاهر المنزه عن كل نقص وعيب المستحق لكل ثناء، والسلام بعده يُفسَّر غالبًا بالسالم من العيوب الذي منه السلامة."] },

  { id: "aq-042", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 12,
    en: ["Which meaning do the exegetes give for the divine name in the highlighted word?", ["The Witness and Guardian over His creation", "The One who grants security", "The Mighty who is never overcome", "The One who mends what is broken"], "Al-Muhaymin is explained by Ibn ʿAbbās and others as the Witness over the deeds of His creatures, watching and guarding them. Granting security belongs to al-Muʾmin just before it, and might to al-ʿAzīz after it."],
    de: ["Welche Bedeutung geben die Exegeten dem göttlichen Namen im hervorgehobenen Wort?", ["Der Zeuge und Wächter über Seine Schöpfung", "Der Sicherheit gewährt", "Der Mächtige, der nie besiegt wird", "Der heilt, was zerbrochen ist"], "Al-Muhaimin wird von Ibn ʿAbbās und anderen als Zeuge über die Taten Seiner Geschöpfe erklärt, der sie beobachtet und behütet. Sicherheit zu gewähren gehört zu al-Muʾmin direkt davor, Macht zu al-ʿAzīz danach."],
    ar: ["ما المعنى الذي يذكره المفسرون للاسم الإلهي في الكلمة المظللة؟", ["الشاهد الرقيب على خلقه", "الذي يمنح الأمن", "الغالب الذي لا يُغلب", "الذي يجبر الكسير"], "فسّر ابن عباس وغيره المهيمن بالشاهد على أعمال خلقه الرقيب الحافظ لها، أما منح الأمن فمن معنى المؤمن قبله، والغلبة من معنى العزيز بعده."] },

  { id: "aq-043", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:22", tr: ["sunni"], v: "59:22", w: 8,
    en: ["The highlighted word and the two after it describe Allah as the Knower of what?", ["The unseen and the witnessed", "The past and the future", "The heavens and the earth", "The hearts and the tongues"], "The verse describes Allah as the Knower of the ghayb and the shahāda: what is hidden from creatures and what they perceive. Nothing in either realm is hidden from Him."],
    de: ["Das hervorgehobene Wort und die zwei folgenden beschreiben Allah als Kenner wovon?", ["Des Verborgenen und des Offenbaren", "Der Vergangenheit und der Zukunft", "Der Himmel und der Erde", "Der Herzen und der Zungen"], "Der Vers beschreibt Allah als Kenner des Ġaib und der Šahāda: dessen, was den Geschöpfen verborgen ist, und dessen, was sie wahrnehmen. Nichts in beiden Bereichen ist Ihm verborgen."],
    ar: ["تصف الكلمة المظللة وما بعدها الله بأنه عالم ماذا؟", ["الغيب والشهادة", "الماضي والمستقبل", "السماوات والأرض", "القلوب والألسنة"], "وصفت الآية الله بأنه عالم الغيب والشهادة، أي ما غاب عن الخلق وما شاهدوه، فلا يخفى عليه شيء في العالمين."] },

  { id: "aq-044", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:24", tr: ["sunni"], v: "59:24", w: 5,
    en: ["What does the divine name in the highlighted word mean?", ["The Fashioner who gives each thing its form", "The Creator who determines measures", "The Originator who brings into being", "The Mighty, the Invincible"], "Al-Muṣawwir is the One who gives every creature its particular shape and form. Scholars describe the sequence of the verse as determining (al-Khāliq), bringing into being (al-Bāriʾ) and forming (al-Muṣawwir)."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Gestalter, der jedem Ding seine Form gibt", "Der Schöpfer, der die Maße bestimmt", "Der Erschaffer, der ins Dasein bringt", "Der Mächtige, der Unbesiegbare"], "Al-Muṣawwir ist der, der jedem Geschöpf seine besondere Gestalt und Form gibt. Die Gelehrten beschreiben die Abfolge des Verses als Bestimmen (al-Ḫāliq), Ins-Dasein-Bringen (al-Bāriʾ) und Formen (al-Muṣawwir)."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["المصوّر الذي يعطي كل شيء صورته", "الخالق المقدّر", "البارئ الموجد", "العزيز الغالب"], "المصوّر هو الذي يعطي كل مخلوق صورته وهيئته الخاصة، ويذكر العلماء ترتيب الآية: التقدير (الخالق) ثم الإيجاد (البارئ) ثم التصوير (المصوّر)."] },

  { id: "aq-045", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 42,
    en: ["According to the verse shown, what of Allah's encompasses the heavens and the earth (highlighted word)?", ["His Kursī", "His Throne", "His Tablet", "His Pen"], "The verse states that His Kursī extends over the heavens and the earth, which is why it is called Āyat al-Kursī. Many scholars distinguish the Kursī from the Throne (ʿArsh), which is greater still."],
    de: ["Was von Allah umfasst laut dem angezeigten Vers die Himmel und die Erde (hervorgehobenes Wort)?", ["Sein Kursī (Schemel)", "Sein Thron", "Seine Tafel", "Seine Feder"], "Der Vers sagt, dass Sein Kursī die Himmel und die Erde umfasst; daher heißt er Thronvers (Āyat al-Kursī). Viele Gelehrte unterscheiden den Kursī vom Thron (ʿArš), der noch gewaltiger ist."],
    ar: ["بحسب الآية المعروضة، ما الذي وسع السماوات والأرض (الكلمة المظللة)؟", ["كرسيه", "عرشه", "لوحه", "قلمه"], "تذكر الآية أن كرسيه وسع السماوات والأرض، ولذلك سُمّيت آية الكرسي، وكثير من العلماء يفرّقون بين الكرسي والعرش الذي هو أعظم منه."] },

  { id: "aq-046", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 49,
    en: ["What does the divine name in the highlighted word mean?", ["The Most High", "The Magnificent", "The Ever-Living", "The Most Generous"], "Al-ʿAliyy is the Most High, exalted in rank, in power and above His creation. Al-ʿAẓīm (the Magnificent) is the name that closes the verse right after it."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Höchste", "Der Gewaltige", "Der Ewig-Lebendige", "Der Freigebigste"], "Al-ʿAliyy ist der Höchste, erhaben an Rang, an Macht und über Seiner Schöpfung. Al-ʿAẓīm (der Gewaltige) ist der Name, der den Vers direkt danach abschließt."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["العلي", "العظيم", "الحي", "الأكرم"], "العلي ذو العلو في قدره وقهره وفوق خلقه، والعظيم هو الاسم الذي خُتمت به الآية بعده مباشرة."] },

  { id: "aq-047", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:4", tr: ["sunni"], v: "112:4", w: 4,
    en: ["What does the highlighted word negate of Allah?", ["Any equal or peer", "Any beginning in time", "Any need for sleep", "Any limit to His knowledge"], "Kufuw means an equal or match. The verse negates that anyone is comparable to Allah, completing the sūra's affirmation of His oneness and His freedom from begetting and being begotten."],
    de: ["Was verneint das hervorgehobene Wort in Bezug auf Allah?", ["Jeden Gleichen oder Ebenbürtigen", "Jeden zeitlichen Anfang", "Jedes Bedürfnis nach Schlaf", "Jede Grenze Seines Wissens"], "Kufuw bedeutet ein Gleicher oder Ebenbürtiger. Der Vers verneint, dass irgendjemand Allah gleichkommt, und vollendet so die Bekräftigung Seiner Einheit und dass Er weder zeugt noch gezeugt wurde."],
    ar: ["ماذا تنفي الكلمة المظللة عن الله تعالى؟", ["الكفء والنظير", "الابتداء في الزمن", "الحاجة إلى النوم", "حدًّا لعلمه"], "الكفء هو المثيل والنظير، فالآية تنفي أن يكون لله مكافئ، وبها تتم السورة في إثبات وحدانيته ونفي الولد والوالد عنه."] },

  { id: "aq-048", s: "aqidah", g: 2, d: 2, t: ["angels"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Zuhd (creation of angels from light)", tr: ["sunni"],
    en: ["According to the hadith of ʿĀʾisha in Ṣaḥīḥ Muslim, from what were the angels created?", ["From light", "From smokeless fire", "From clay", "From water"], "The hadith states that the angels were created from light, the jinn from a smokeless flame of fire, and Ādam from what has been described (clay)."],
    de: ["Woraus wurden die Engel laut dem Hadith von ʿĀʾiša im Ṣaḥīḥ Muslim erschaffen?", ["Aus Licht", "Aus rauchlosem Feuer", "Aus Lehm", "Aus Wasser"], "Der Hadith sagt, dass die Engel aus Licht erschaffen wurden, die Dschinn aus einer rauchlosen Feuerflamme und Ādam aus dem, was beschrieben wurde (Lehm)."],
    ar: ["بحسب حديث عائشة في صحيح مسلم، مِمَّ خُلقت الملائكة؟", ["من نور", "من مارج من نار", "من طين", "من ماء"], "في الحديث أن الملائكة خُلقت من نور، والجان من مارج من نار، وآدم مما وُصف لكم أي من طين."] },

  { id: "aq-049", s: "aqidah", g: 2, d: 2, t: ["angels", "jinn"], src: "Ibn Kathīr, Tafsīr, on 18:50", tr: ["sunni"], v: "18:50",
    en: ["According to the verse shown, to which kind of creation did Iblīs belong?", ["The jinn", "The angels", "The humans", "The beasts"], "The verse states explicitly that Iblīs was of the jinn and departed from his Lord's command. Angels do not disobey Allah (66:6), which is one reason scholars distinguish him from them."],
    de: ["Zu welcher Art von Geschöpfen gehörte Iblīs laut dem angezeigten Vers?", ["Zu den Dschinn", "Zu den Engeln", "Zu den Menschen", "Zu den Tieren"], "Der Vers sagt ausdrücklich, dass Iblīs zu den Dschinn gehörte und sich dem Befehl seines Herrn widersetzte. Engel widersetzen sich Allah nicht (66:6), was ein Grund ist, weshalb die Gelehrten ihn von ihnen unterscheiden."],
    ar: ["بحسب الآية المعروضة، إلى أيّ صنف من الخلق كان إبليس؟", ["الجن", "الملائكة", "الإنس", "البهائم"], "نصّت الآية على أن إبليس كان من الجن ففسق عن أمر ربه، والملائكة لا يعصون الله (التحريم 6)، وهذا من أسباب تفريق العلماء بينه وبينهم."] },

  { id: "aq-050", s: "aqidah", g: 2, d: 3, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 2:102", tr: ["sunni"], v: "2:102",
    en: ["Which two angels are named in the verse shown, in connection with Babylon?", ["Hārūt and Mārūt", "Munkar and Nakīr", "Jibrīl and Mīkāʾīl", "Raqīb and ʿAtīd"], "The verse mentions what was sent down to the two angels in Babylon, Hārūt and Mārūt, who warned that they were only a trial. Jibrīl and Mīkāʾīl are named together in 2:98."],
    de: ["Welche zwei Engel werden im angezeigten Vers im Zusammenhang mit Babylon genannt?", ["Hārūt und Mārūt", "Munkar und Nakīr", "Ǧibrīl und Mīkāʾīl", "Raqīb und ʿAtīd"], "Der Vers erwähnt, was auf die beiden Engel in Babylon, Hārūt und Mārūt, herabgesandt wurde, die warnten, sie seien nur eine Prüfung. Ǧibrīl und Mīkāʾīl werden zusammen in 2:98 genannt."],
    ar: ["ما اسما الملكين المذكورين في الآية المعروضة في شأن بابل؟", ["هاروت وماروت", "منكر ونكير", "جبريل وميكائيل", "رقيب وعتيد"], "تذكر الآية ما أُنزل على الملكين ببابل هاروت وماروت، وكانا يحذّران بأنهما فتنة، أما جبريل وميكائيل فذُكرا معًا في البقرة (98)."] },

  { id: "aq-051", s: "aqidah", g: 2, d: 3, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 32:11", tr: ["sunni"], v: "32:11",
    en: ["By what title does the verse shown refer to the angel who takes the souls?", ["The angel of death", "The keeper of the Fire", "The Trustworthy Spirit", "The noble scribe"], "The Quran calls him malak al-mawt, the angel of death. The name ʿAzrāʾīl is widespread among Muslims, but scholars note that it is not found in the Quran or in an authentic hadith."],
    de: ["Mit welchem Titel bezeichnet der angezeigte Vers den Engel, der die Seelen nimmt?", ["Der Engel des Todes", "Der Hüter des Feuers", "Der vertrauenswürdige Geist", "Der edle Schreiber"], "Der Koran nennt ihn malak al-maut, den Engel des Todes. Der Name ʿAzrāʾīl ist unter Muslimen verbreitet, doch die Gelehrten weisen darauf hin, dass er weder im Koran noch in einem authentischen Hadith vorkommt."],
    ar: ["بأيّ لقب تذكر الآية المعروضة الملَك الذي يقبض الأرواح؟", ["ملك الموت", "خازن النار", "الروح الأمين", "الكاتب الكريم"], "سمّاه القرآن ملك الموت، واسم عزرائيل شائع بين المسلمين لكن العلماء ينبّهون على أنه لم يرد في القرآن ولا في حديث صحيح."] },

  { id: "aq-052", s: "aqidah", g: 2, d: 2, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 87:18–19", tr: ["sunni"], v: "87:19",
    en: ["The verse shown mentions the scriptures (ṣuḥuf) of which two prophets?", ["Ibrāhīm and Mūsā", "Nūḥ and Ibrāhīm", "Dāwūd and Sulaymān", "Mūsā and ʿĪsā"], "Sūrat al-Aʿlā closes by referring to the earlier scriptures, the ṣuḥuf of Ibrāhīm and Mūsā. Belief in the books includes believing in every book Allah revealed, named or unnamed."],
    de: ["Der angezeigte Vers erwähnt die Blätter (ṣuḥuf) welcher zwei Propheten?", ["Ibrāhīm und Mūsā", "Nūḥ und Ibrāhīm", "Dāwūd und Sulaimān", "Mūsā und ʿĪsā"], "Sūrat al-Aʿlā schließt mit dem Verweis auf die früheren Schriften, die Blätter Ibrāhīms und Mūsās. Der Glaube an die Bücher umfasst jedes von Allah offenbarte Buch, ob namentlich genannt oder nicht."],
    ar: ["تذكر الآية المعروضة صحف أيّ نبيين؟", ["إبراهيم وموسى", "نوح وإبراهيم", "داود وسليمان", "موسى وعيسى"], "خُتمت سورة الأعلى بذكر الصحف الأولى صحف إبراهيم وموسى، والإيمان بالكتب يشمل كل كتاب أنزله الله سُمّي لنا أو لم يُسمَّ."] },

  { id: "aq-053", s: "aqidah", g: 2, d: 2, t: ["messengers", "prophet-and-messenger"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on prophethood", tr: ["sunni"],
    en: ["Which statement reflects the common view on the relation between nabī (prophet) and rasūl (messenger)?", ["Every messenger is a prophet, but not every prophet is a messenger", "Every prophet is a messenger, but not every messenger is a prophet", "The two words always mean exactly the same", "A messenger is an angel, a prophet a human"], "Most scholars hold that rasūl is more specific: every messenger is a prophet, but not every prophet is a messenger. They differ on the exact criterion, for example being sent with a new law or to a people who reject."],
    de: ["Welche Aussage gibt die verbreitete Ansicht über das Verhältnis von Nabī (Prophet) und Rasūl (Gesandter) wieder?", ["Jeder Gesandte ist ein Prophet, aber nicht jeder Prophet ein Gesandter", "Jeder Prophet ist ein Gesandter, aber nicht jeder Gesandte ein Prophet", "Beide Wörter bedeuten immer genau dasselbe", "Ein Gesandter ist ein Engel, ein Prophet ein Mensch"], "Die meisten Gelehrten sehen Rasūl als den engeren Begriff: Jeder Gesandte ist ein Prophet, aber nicht jeder Prophet ein Gesandter. Über das genaue Kriterium gibt es Unterschiede, etwa die Sendung mit einem neuen Gesetz oder zu einem ablehnenden Volk."],
    ar: ["أيّ العبارات تعبّر عن القول المشهور في العلاقة بين النبي والرسول؟", ["كل رسول نبي وليس كل نبي رسولًا", "كل نبي رسول وليس كل رسول نبيًّا", "اللفظان مترادفان دائمًا", "الرسول ملَك والنبي بشر"], "الجمهور على أن الرسول أخص: فكل رسول نبي وليس كل نبي رسولًا، واختلفوا في ضابط الفرق كالإرسال بشرع جديد أو إلى قوم مخالفين."] },

  { id: "aq-054", s: "aqidah", g: 2, d: 2, t: ["messengers"], src: "Ibn Kathīr, Qaṣaṣ al-Anbiyāʾ, introduction", tr: ["sunni"],
    en: ["How many prophets and messengers are commonly counted as named in the Quran?", ["Twenty-five", "Nineteen", "Thirty-three", "Twelve"], "Scholars commonly count twenty-five prophets named in the Quran, eighteen of them in 6:83–86. The Quran states that there are others not narrated to the Prophet (4:164)."],
    de: ["Wie viele Propheten und Gesandte werden gewöhnlich als im Koran namentlich genannt gezählt?", ["Fünfundzwanzig", "Neunzehn", "Dreiunddreißig", "Zwölf"], "Die Gelehrten zählen gewöhnlich fünfundzwanzig im Koran genannte Propheten, achtzehn davon in 6:83–86. Der Koran sagt, dass es weitere gibt, von denen dem Propheten nicht berichtet wurde (4:164)."],
    ar: ["كم عدد الأنبياء والرسل المذكورين بأسمائهم في القرآن في العدّ المشهور؟", ["خمسة وعشرون", "تسعة عشر", "ثلاثة وثلاثون", "اثنا عشر"], "المشهور أن المذكورين بأسمائهم في القرآن خمسة وعشرون، منهم ثمانية عشر في الأنعام (83–86)، وأخبر القرآن أن هناك رسلًا لم يُقصصوا على النبي ﷺ (النساء 164)."] },

  { id: "aq-055", s: "aqidah", g: 2, d: 3, t: ["messengers", "ulu-al-azm"], src: "Ibn Kathīr, Tafsīr, on 33:7 and 46:35", tr: ["sunni"],
    en: ["Which prophet is commonly counted among the Ulū al-ʿAzm (the messengers of firm resolve)?", ["Nūḥ", "Yūsuf", "Sulaymān", "Yaḥyā"], "The most widespread view counts five as Ulū al-ʿAzm: Nūḥ, Ibrāhīm, Mūsā, ʿĪsā and Muḥammad, who are named together in 33:7 and 42:13."],
    de: ["Welcher Prophet wird gewöhnlich zu den Ulū l-ʿAzm (den Gesandten der Standhaftigkeit) gezählt?", ["Nūḥ", "Yūsuf", "Sulaimān", "Yaḥyā"], "Nach der verbreitetsten Ansicht gehören fünf zu den Ulū l-ʿAzm: Nūḥ, Ibrāhīm, Mūsā, ʿĪsā und Muḥammad, die in 33:7 und 42:13 zusammen genannt werden."],
    ar: ["أيّ الأنبياء يُعدّ في القول المشهور من أولي العزم من الرسل؟", ["نوح", "يوسف", "سليمان", "يحيى"], "المشهور أن أولي العزم خمسة: نوح وإبراهيم وموسى وعيسى ومحمد ﷺ، وقد ذُكروا معًا في الأحزاب (7) والشورى (13)."] },

  { id: "aq-056", s: "aqidah", g: 2, d: 2, t: ["messengers", "isma"], src: "al-Qāḍī ʿIyāḍ, al-Shifā, section on the ʿiṣma of the prophets", tr: ["ijma"],
    en: ["On which aspect of the prophets' protection (ʿiṣma) is there consensus?", ["Protection from error in conveying the message", "Protection from all illness and hardship", "Protection from ever being harmed by enemies", "Protection from forgetting worldly matters"], "Scholars agree that the prophets are protected from lying or erring in conveying what Allah revealed. Prophets did suffer illness, hardship and harm from enemies, which does not contradict their ʿiṣma."],
    de: ["Über welchen Aspekt des Schutzes der Propheten (ʿiṣma) besteht Konsens?", ["Schutz vor Irrtum bei der Übermittlung der Botschaft", "Schutz vor jeder Krankheit und Not", "Schutz davor, je von Feinden verletzt zu werden", "Schutz vor dem Vergessen weltlicher Dinge"], "Die Gelehrten sind sich einig, dass die Propheten davor geschützt sind, bei der Übermittlung der Offenbarung zu lügen oder zu irren. Krankheit, Not und Leid durch Feinde haben sie erfahren; das widerspricht ihrer ʿIṣma nicht."],
    ar: ["في أيّ جانب من عصمة الأنبياء وقع الإجماع؟", ["العصمة من الخطأ في تبليغ الرسالة", "العصمة من كل مرض وشدة", "العصمة من أن يصيبهم أذى الأعداء", "العصمة من نسيان أمور الدنيا"], "أجمع العلماء على عصمة الأنبياء من الكذب والخطأ في تبليغ ما أوحى الله إليهم، وقد أصابهم المرض والشدة وأذى الأعداء ولا ينافي ذلك عصمتهم."] },

  { id: "aq-057", s: "aqidah", g: 2, d: 2, t: ["messengers", "miracles"], src: "Ibn Kathīr, Tafsīr, on 17:88", tr: ["sunni"],
    en: ["What do the scholars regard as the greatest miracle of the Prophet Muḥammad?", ["The Quran", "The splitting of the moon", "Water flowing from his fingers", "The night journey to Jerusalem"], "The Quran is his greatest and lasting miracle, with which he challenged the Arabs to produce anything like it. The other miracles were witnessed at their time; the Quran remains for every generation."],
    de: ["Was sehen die Gelehrten als das größte Wunder des Propheten Muḥammad?", ["Den Koran", "Die Spaltung des Mondes", "Das Wasser, das aus seinen Fingern floss", "Die Nachtreise nach Jerusalem"], "Der Koran ist sein größtes und bleibendes Wunder, mit dem er die Araber herausforderte, Gleiches hervorzubringen. Die anderen Wunder wurden zu ihrer Zeit bezeugt; der Koran bleibt für jede Generation."],
    ar: ["ما الذي يعدّه العلماء أعظم معجزات النبي ﷺ؟", ["القرآن", "انشقاق القمر", "نبع الماء من بين أصابعه", "الإسراء إلى بيت المقدس"], "القرآن أعظم معجزاته الباقية، تحدّى به العرب أن يأتوا بمثله، وسائر المعجزات شوهدت في وقتها، أما القرآن فباقٍ لكل جيل."] },

  { id: "aq-058", s: "aqidah", g: 2, d: 3, t: ["resurrection", "last-day"], src: "Ibn Kathīr, Tafsīr, on 39:68", tr: ["sunni"], v: "39:68",
    en: ["How many blowings of the trumpet are explicitly mentioned in the verse shown?", ["Two: one causing all to swoon, one raising them", "One: the blowing that resurrects", "Three: terror, swoon and resurrection", "Four: one for each corner of the earth"], "The verse mentions a first blowing at which all in the heavens and earth swoon, except whom Allah wills, and then another blowing at which they stand looking on. Some scholars add a blowing of terror from 27:87, but this verse names two."],
    de: ["Wie viele Stöße in das Horn werden im angezeigten Vers ausdrücklich erwähnt?", ["Zwei: einer lässt alle niederstürzen, einer erweckt sie", "Einer: der Stoß der Auferweckung", "Drei: Schrecken, Niederstürzen und Auferstehung", "Vier: einer für jede Ecke der Erde"], "Der Vers erwähnt einen ersten Stoß, bei dem alle in den Himmeln und auf der Erde niederstürzen, außer wen Allah will, und dann einen weiteren, bei dem sie aufstehen und schauen. Manche Gelehrte fügen einen Stoß des Schreckens aus 27:87 hinzu, doch dieser Vers nennt zwei."],
    ar: ["كم نفخة في الصور ذُكرت صراحةً في الآية المعروضة؟", ["نفختان: صعق ثم قيام", "نفخة واحدة هي نفخة البعث", "ثلاث: فزع وصعق وبعث", "أربع: لكل جهة من الأرض نفخة"], "ذكرت الآية نفخة يصعق بها من في السماوات والأرض إلا من شاء الله ثم نفخة أخرى فإذا هم قيام ينظرون، وزاد بعض العلماء نفخة الفزع من سورة النمل (87)، لكن هذه الآية ذكرت اثنتين."] },

  { id: "aq-059", s: "aqidah", g: 2, d: 2, t: ["intercession", "last-day"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tawḥīd (hadith of the intercession)", tr: ["sunni"],
    en: ["What is \"the great intercession\" (al-shafāʿa al-ʿuẓmā)?", ["The Prophet's intercession for the judgment to begin", "The angels' intercession for children", "The martyrs' intercession for their families", "The Quran's intercession for its reciters"], "In the long hadith of intercession people go from prophet to prophet until they come to Muḥammad, who intercedes for all of creation so that the judgment may begin. Scholars connect this with the Praised Station (17:79), and it is specific to him."],
    de: ["Was ist „die große Fürsprache“ (aš-šafāʿa al-ʿuẓmā)?", ["Die Fürsprache des Propheten, damit das Gericht beginnt", "Die Fürsprache der Engel für die Kinder", "Die Fürsprache der Märtyrer für ihre Familien", "Die Fürsprache des Korans für seine Rezitatoren"], "Im langen Hadith der Fürsprache gehen die Menschen von Prophet zu Prophet, bis sie zu Muḥammad kommen, der für die ganze Schöpfung Fürsprache einlegt, damit das Gericht beginnt. Die Gelehrten verbinden dies mit der gepriesenen Stellung (17:79); sie ist ihm vorbehalten."],
    ar: ["ما الشفاعة العظمى؟", ["شفاعة النبي ﷺ في بدء فصل القضاء", "شفاعة الملائكة في الأطفال", "شفاعة الشهداء في أهليهم", "شفاعة القرآن لأصحابه"], "في حديث الشفاعة الطويل يأتي الناس الأنبياء واحدًا بعد واحد حتى يأتوا محمدًا ﷺ فيشفع للخلق كلهم في فصل القضاء، وهي المقام المحمود (الإسراء 79) وخاصة به."] },

  { id: "aq-060", s: "aqidah", g: 2, d: 3, t: ["intercession", "ayat-al-kursi"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on intercession", tr: ["sunni"], v: "2:255", w: 23,
    en: ["The highlighted word concerns intercession. Which two conditions do scholars derive from this and related verses (20:109, 53:26)?", ["Allah's permission and His being pleased with the one interceded for", "The intercessor's lineage and the sinner's wealth", "A request in writing and witnesses for it", "The intercessor's presence at the grave and a sacrifice"], "The verse states that none intercedes with Him except by His permission. Combined with verses on His being pleased with the one interceded for, scholars derive two conditions: the permission of Allah and His acceptance of the person concerned."],
    de: ["Das hervorgehobene Wort betrifft die Fürsprache. Welche zwei Bedingungen leiten die Gelehrten aus diesem und verwandten Versen (20:109, 53:26) ab?", ["Allahs Erlaubnis und Sein Wohlgefallen an dem, für den Fürsprache eingelegt wird", "Die Abstammung des Fürsprechers und das Vermögen des Sünders", "Eine schriftliche Bitte und Zeugen dafür", "Anwesenheit des Fürsprechers am Grab und ein Opfer"], "Der Vers sagt, dass niemand bei Ihm Fürsprache einlegt außer mit Seiner Erlaubnis. Zusammen mit den Versen über Sein Wohlgefallen an dem Betreffenden leiten die Gelehrten zwei Bedingungen ab: Allahs Erlaubnis und Seine Zustimmung zur betreffenden Person."],
    ar: ["الكلمة المظللة في شأن الشفاعة، فما الشرطان اللذان يستنبطهما العلماء منها ومن آيات أخرى (طه 109، النجم 26)؟", ["إذن الله ورضاه عن المشفوع له", "نسب الشافع ومال المذنب", "طلب مكتوب وشهود عليه", "حضور الشافع عند القبر وذبيحة"], "تقرر الآية أنه لا يشفع أحد عنده إلا بإذنه، ومع الآيات في رضاه عن المشفوع له استنبط العلماء شرطين: إذن الله للشافع ورضاه عن المشفوع له."] },

  { id: "aq-061", s: "aqidah", g: 2, d: 2, t: ["paradise-and-hell", "seeing-allah"], src: "Ibn Kathīr, Tafsīr, on 75:22–23", tr: ["sunni"], v: "75:23",
    en: ["Ahl al-Sunna cite the verse shown (with the one before it) as proof of what?", ["That the believers will see their Lord in the Hereafter", "That Paradise has eight gates for the believers", "That the righteous will intercede for their families", "That the sun will be brought near to the creatures"], "The verses describe radiant faces looking at their Lord. Together with mass-transmitted hadith, Ahl al-Sunna across the Atharī, Ashʿarī and Māturīdī schools affirm that the believers will see Allah in the Hereafter."],
    de: ["Als Beleg wofür führen Ahl as-Sunna den angezeigten Vers (mit dem vorangehenden) an?", ["Dass die Gläubigen ihren Herrn im Jenseits sehen werden", "Dass das Paradies acht Tore für die Gläubigen hat", "Dass die Rechtschaffenen für ihre Familien Fürsprache einlegen", "Dass die Sonne den Geschöpfen nahe gebracht wird"], "Die Verse beschreiben strahlende Gesichter, die zu ihrem Herrn schauen. Zusammen mit massenhaft überlieferten Hadithen bekräftigen Ahl as-Sunna in der atharitischen, ašʿaritischen und māturīditischen Schule, dass die Gläubigen Allah im Jenseits sehen werden."],
    ar: ["بمَ يستدل أهل السنة بالآية المعروضة مع التي قبلها؟", ["رؤية المؤمنين ربهم في الآخرة", "أن للجنة ثمانية أبواب للمؤمنين", "شفاعة الصالحين في أهليهم", "دنو الشمس من الخلائق يوم القيامة"], "تصف الآيتان وجوهًا ناضرة إلى ربها ناظرة، ومع الأحاديث المتواترة أثبت أهل السنة من الأثرية والأشاعرة والماتريدية رؤية المؤمنين ربهم في الآخرة."] },

  { id: "aq-062", s: "aqidah", g: 2, d: 3, t: ["paradise-and-hell", "last-day"], src: "Ibn Kathīr, Tafsīr, on 7:46–49", tr: ["sunni"],
    en: ["The people standing on the heights between Paradise and Hell give their name to which sūra?", ["Al-Aʿrāf", "Al-Ḥadīd", "Al-Ḥijr", "Al-Burūj"], "Sūrat al-Aʿrāf (7:46–49) describes people on the heights of the partition between the two abodes; many scholars explain them as those whose good and bad deeds are equal, who will eventually enter Paradise."],
    de: ["Die Menschen, die auf den Höhen zwischen Paradies und Hölle stehen, geben welcher Sure ihren Namen?", ["Al-Aʿrāf", "Al-Ḥadīd", "Al-Ḥiǧr", "Al-Burūǧ"], "Sūrat al-Aʿrāf (7:46–49) beschreibt Menschen auf den Höhen der Trennwand zwischen den beiden Wohnstätten; viele Gelehrte erklären sie als jene, deren gute und schlechte Taten gleich sind und die schließlich ins Paradies eingehen."],
    ar: ["أهل المكان المرتفع بين الجنة والنار سُمّيت باسمهم أيّ سورة؟", ["الأعراف", "الحديد", "الحجر", "البروج"], "وصفت سورة الأعراف (46–49) رجالًا على أعراف الحجاب بين الدارين، وكثير من العلماء على أنهم من استوت حسناتهم وسيئاتهم ثم يدخلون الجنة."] },

  { id: "aq-063", s: "aqidah", g: 2, d: 3, t: ["iman-increase", "iman-definition"], src: "Ibn Kathīr, Tafsīr, on 8:2", tr: ["sunni"], v: "8:2", w: 13,
    en: ["What does the highlighted verb state happens to the believers when Allah's verses are recited to them?", ["Their faith is increased", "Their sins are erased", "Their hearts become hard", "Their reward is doubled"], "The verse says that the recitation of His verses increases them in faith. Scholars who hold that īmān increases and decreases cite this verse, together with 48:4 and others."],
    de: ["Was geschieht laut dem hervorgehobenen Verb mit den Gläubigen, wenn ihnen Allahs Verse vorgetragen werden?", ["Ihr Glaube wird gemehrt", "Ihre Sünden werden getilgt", "Ihre Herzen verhärten sich", "Ihr Lohn wird verdoppelt"], "Der Vers sagt, dass das Vortragen Seiner Verse ihren Glauben mehrt. Gelehrte, die lehren, dass der Īmān zu- und abnimmt, führen diesen Vers zusammen mit 48:4 und anderen an."],
    ar: ["ماذا يحدث للمؤمنين إذا تُليت عليهم آيات الله بحسب الفعل المظلل؟", ["يزدادون إيمانًا", "تُمحى سيئاتهم", "تقسو قلوبهم", "يُضاعف أجرهم"], "تذكر الآية أن تلاوة آياته تزيدهم إيمانًا، ويستدل بها مع آية الفتح (4) وغيرها من قال بزيادة الإيمان ونقصانه."] },

  { id: "aq-064", s: "aqidah", g: 2, d: 2, t: ["divine-speech", "creeds-and-authors"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Aḥmad ibn Ḥanbal", tr: ["sunni"],
    en: ["Which imam is famous for his steadfastness during the Miḥna over the claim that the Quran is created?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "Sufyān al-Thawrī"], "Aḥmad ibn Ḥanbal refused under imprisonment and flogging to say that the Quran is created, affirming that it is the uncreated speech of Allah. Mālik, Abū Ḥanīfa and Sufyān al-Thawrī had died before the Miḥna."],
    de: ["Welcher Imam ist für seine Standhaftigkeit während der Miḥna um die Behauptung, der Koran sei erschaffen, berühmt?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "Sufyān aṯ-Ṯaurī"], "Aḥmad ibn Ḥanbal weigerte sich trotz Haft und Auspeitschung zu sagen, der Koran sei erschaffen, und bekräftigte, dass er die unerschaffene Rede Allahs ist. Mālik, Abū Ḥanīfa und Sufyān aṯ-Ṯaurī waren vor der Miḥna gestorben."],
    ar: ["أيّ الأئمة اشتهر بثباته في المحنة في القول بخلق القرآن؟", ["أحمد بن حنبل", "مالك بن أنس", "أبو حنيفة", "سفيان الثوري"], "رفض الإمام أحمد مع السجن والضرب أن يقول بخلق القرآن، وأثبت أنه كلام الله غير مخلوق، أما مالك وأبو حنيفة والثوري فتوفّوا قبل المحنة."] },

  { id: "aq-065", s: "aqidah", g: 3, d: 3, t: ["divine-attributes", "ashari-maturidi"], src: "al-Sanūsī, Umm al-Barāhīn, on the attributes of maʿānī", tr: ["ashari"],
    en: ["In the Ashʿarī scheme, which of the following belongs to the seven attributes of maʿānī (attributes of meaning)?", ["Will (irāda)", "Everlastingness (baqāʾ)", "Self-subsistence (qiyām bi-l-nafs)", "Oneness (waḥdāniyya)"], "The seven maʿānī are life, knowledge, power, will, hearing, sight and speech. Baqāʾ, qiyām bi-l-nafs and waḥdāniyya are counted among the negating (salbī) attributes in the same scheme."],
    de: ["Welche der folgenden Eigenschaften gehört im ašʿaritischen Schema zu den sieben Eigenschaften des Maʿānī (Bedeutungseigenschaften)?", ["Der Wille (irāda)", "Die Fortdauer (baqāʾ)", "Das Durch-sich-selbst-Bestehen (qiyām bi-n-nafs)", "Die Einheit (waḥdāniyya)"], "Die sieben Maʿānī sind Leben, Wissen, Macht, Wille, Hören, Sehen und Rede. Baqāʾ, qiyām bi-n-nafs und waḥdāniyya zählen im selben Schema zu den verneinenden (salbī) Eigenschaften."],
    ar: ["في التقسيم الأشعري، أيّ مما يلي من صفات المعاني السبع؟", ["الإرادة", "البقاء", "القيام بالنفس", "الوحدانية"], "صفات المعاني سبع: الحياة والعلم والقدرة والإرادة والسمع والبصر والكلام، أما البقاء والقيام بالنفس والوحدانية فمن الصفات السلبية في التقسيم نفسه."] },

  { id: "aq-066", s: "aqidah", g: 3, d: 3, t: ["creeds-and-authors", "ashari-maturidi"], src: "Ibn ʿAsākir, Tabyīn Kadhib al-Muftarī, on the lineage of al-Ashʿarī", tr: ["ashari"],
    en: ["Abū al-Ḥasan al-Ashʿarī descended from which Companion?", ["Abū Mūsā al-Ashʿarī", "Abū Ayyūb al-Anṣārī", "Abū Dharr al-Ghifārī", "Abū ʿUbayda ibn al-Jarrāḥ"], "Abū al-Ḥasan ʿAlī ibn Ismāʿīl al-Ashʿarī traced his lineage to the Companion Abū Mūsā al-Ashʿarī, which is why Ibn ʿAsākir and others connect him with the Prophet's praise of the Ashʿarī tribe."],
    de: ["Von welchem Gefährten stammte Abū l-Ḥasan al-Ašʿarī ab?", ["Abū Mūsā al-Ašʿarī", "Abū Ayyūb al-Anṣārī", "Abū Ḏarr al-Ġifārī", "Abū ʿUbaida ibn al-Ǧarrāḥ"], "Abū l-Ḥasan ʿAlī ibn Ismāʿīl al-Ašʿarī führte seine Abstammung auf den Gefährten Abū Mūsā al-Ašʿarī zurück; deshalb verbinden Ibn ʿAsākir und andere ihn mit dem Lob des Propheten für den Stamm der Ašʿariten."],
    ar: ["إلى أيّ صحابي ينتسب أبو الحسن الأشعري؟", ["أبي موسى الأشعري", "أبي أيوب الأنصاري", "أبي ذر الغفاري", "أبي عبيدة بن الجراح"], "ينتهي نسب أبي الحسن علي بن إسماعيل الأشعري إلى الصحابي أبي موسى الأشعري، ولذلك ربطه ابن عساكر وغيره بثناء النبي ﷺ على الأشعريين."] },

  { id: "aq-067", s: "aqidah", g: 3, d: 3, t: ["creeds-and-authors", "ashari-maturidi"], src: "Ibn Abī al-Wafāʾ, al-Jawāhir al-Muḍiyya, biography of al-Māturīdī", tr: ["maturidi"],
    en: ["In which city did Abū Manṣūr al-Māturīdī, author of Kitāb al-Tawḥīd and Taʾwīlāt Ahl al-Sunna, live and teach?", ["Samarqand", "Baghdad", "Basra", "Cairo"], "Al-Māturīdī was a Ḥanafī theologian of Samarqand in Transoxiana; Māturīd is a quarter of that city. Al-Ashʿarī was active in Basra and Baghdad, and al-Ṭaḥāwī in Egypt."],
    de: ["In welcher Stadt lebte und lehrte Abū Manṣūr al-Māturīdī, Verfasser des Kitāb at-Tauḥīd und der Taʾwīlāt Ahl as-Sunna?", ["Samarkand", "Bagdad", "Basra", "Kairo"], "Al-Māturīdī war ein ḥanafitischer Theologe aus Samarkand in Transoxanien; Māturīd ist ein Viertel dieser Stadt. Al-Ašʿarī wirkte in Basra und Bagdad, aṭ-Ṭaḥāwī in Ägypten."],
    ar: ["في أيّ مدينة عاش أبو منصور الماتريدي صاحب كتاب التوحيد وتأويلات أهل السنة ودرّس؟", ["سمرقند", "بغداد", "البصرة", "القاهرة"], "الماتريدي متكلم حنفي من سمرقند فيما وراء النهر، وماتريد محلّة بها، أما الأشعري فكان بالبصرة وبغداد، والطحاوي بمصر."] },

  { id: "aq-068", s: "aqidah", g: 3, d: 4, t: ["creeds-and-authors", "tahawiyya"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya, introduction", tr: ["sunni"],
    en: ["Al-Ṭaḥāwī says in the introduction of his creed that it presents the doctrine of which scholars?", ["Abū Ḥanīfa, Abū Yūsuf and Muḥammad al-Shaybānī", "Mālik, al-Shāfiʿī and Aḥmad", "Al-Ashʿarī, al-Bāqillānī and al-Juwaynī", "Al-Bukhārī, Muslim and Abū Dāwūd"], "Abū Jaʿfar al-Ṭaḥāwī, himself a Ḥanafī jurist of Egypt, states that he presents the creed of Ahl al-Sunna according to Abū Ḥanīfa and his two companions Abū Yūsuf and Muḥammad ibn al-Ḥasan al-Shaybānī."],
    de: ["Aṭ-Ṭaḥāwī sagt in der Einleitung seines Glaubensbekenntnisses, es gebe die Lehre welcher Gelehrten wieder?", ["Abū Ḥanīfa, Abū Yūsuf und Muḥammad aš-Šaibānī", "Mālik, aš-Šāfiʿī und Aḥmad", "Al-Ašʿarī, al-Bāqillānī und al-Ǧuwainī", "Al-Buḫārī, Muslim und Abū Dāwūd"], "Abū Ǧaʿfar aṭ-Ṭaḥāwī, selbst ḥanafitischer Rechtsgelehrter in Ägypten, erklärt, er lege die Lehre der Ahl as-Sunna nach Abū Ḥanīfa und seinen beiden Gefährten Abū Yūsuf und Muḥammad ibn al-Ḥasan aš-Šaibānī dar."],
    ar: ["ذكر الطحاوي في مقدمة عقيدته أنها بيان عقيدة أيّ العلماء؟", ["أبي حنيفة وأبي يوسف ومحمد بن الحسن الشيباني", "مالك والشافعي وأحمد", "الأشعري والباقلاني والجويني", "البخاري ومسلم وأبي داود"], "ذكر أبو جعفر الطحاوي، وهو فقيه حنفي مصري، أنه يبيّن عقيدة أهل السنة على مذهب أبي حنيفة وصاحبيه أبي يوسف ومحمد بن الحسن الشيباني."] },

  { id: "aq-069", s: "aqidah", g: 3, d: 3, t: ["creeds-and-authors", "lumat-al-itiqad"], src: "Ibn Rajab, Dhayl Ṭabaqāt al-Ḥanābila, biography of Ibn Qudāma", tr: ["athari"],
    en: ["Which Ḥanbalī scholar, also author of the fiqh encyclopedia al-Mughnī, wrote the short creed Lumʿat al-Iʿtiqād?", ["Muwaffaq al-Dīn Ibn Qudāma", "Taqī al-Dīn Ibn Taymiyya", "Zayn al-Dīn Ibn Rajab", "Jamāl al-Dīn Ibn al-Jawzī"], "Muwaffaq al-Dīn ʿAbd Allāh ibn Qudāma al-Maqdisī wrote Lumʿat al-Iʿtiqād as well as al-Mughnī and al-ʿUmda. Ibn Taymiyya wrote al-ʿAqīda al-Wāsiṭiyya."],
    de: ["Welcher ḥanbalitische Gelehrte, auch Verfasser der Fiqh-Enzyklopädie al-Muġnī, schrieb das kurze Glaubensbekenntnis Lumʿat al-Iʿtiqād?", ["Muwaffaq ad-Dīn Ibn Qudāma", "Taqī ad-Dīn Ibn Taimiyya", "Zain ad-Dīn Ibn Raǧab", "Ǧamāl ad-Dīn Ibn al-Ǧauzī"], "Muwaffaq ad-Dīn ʿAbdallāh ibn Qudāma al-Maqdisī schrieb Lumʿat al-Iʿtiqād sowie al-Muġnī und al-ʿUmda. Ibn Taimiyya schrieb al-ʿAqīda al-Wāsiṭiyya."],
    ar: ["أيّ عالم حنبلي، صاحب موسوعة المغني في الفقه، ألّف العقيدة المختصرة لمعة الاعتقاد؟", ["موفق الدين ابن قدامة", "تقي الدين ابن تيمية", "زين الدين ابن رجب", "جمال الدين ابن الجوزي"], "ألّف موفق الدين عبد الله بن قدامة المقدسي لمعة الاعتقاد كما ألّف المغني والعمدة، أما ابن تيمية فصاحب العقيدة الواسطية."] },

  { id: "aq-070", s: "aqidah", g: 3, d: 4, t: ["creeds-and-authors", "nasafiyya"], src: "Ḥājjī Khalīfa, Kashf al-Ẓunūn, entry on al-ʿAqāʾid al-Nasafiyya", tr: ["maturidi"],
    en: ["Who wrote the most famous commentary on al-ʿAqāʾid al-Nasafiyya of Najm al-Dīn ʿUmar al-Nasafī?", ["Saʿd al-Dīn al-Taftāzānī", "Ibn Abī al-ʿIzz al-Ḥanafī", "Ibrāhīm al-Bayjūrī", "Mullā ʿAlī al-Qārī"], "Al-Taftāzānī's Sharḥ al-ʿAqāʾid al-Nasafiyya became a standard text in madrasas and attracted many glosses. Ibn Abī al-ʿIzz commented on the Ṭaḥāwiyya, al-Bayjūrī on Jawharat al-Tawḥīd, and al-Qārī on al-Fiqh al-Akbar."],
    de: ["Wer verfasste den berühmtesten Kommentar zu al-ʿAqāʾid an-Nasafiyya von Naǧm ad-Dīn ʿUmar an-Nasafī?", ["Saʿd ad-Dīn at-Taftāzānī", "Ibn Abī l-ʿIzz al-Ḥanafī", "Ibrāhīm al-Bāǧūrī", "Mullā ʿAlī al-Qārī"], "At-Taftāzānīs Šarḥ al-ʿAqāʾid an-Nasafiyya wurde ein Standardtext der Madrasas und zog viele Glossen nach sich. Ibn Abī l-ʿIzz kommentierte die Ṭaḥāwiyya, al-Bāǧūrī die Ǧauharat at-Tauḥīd und al-Qārī al-Fiqh al-Akbar."],
    ar: ["مَن صاحب أشهر شرح على العقائد النسفية لنجم الدين عمر النسفي؟", ["سعد الدين التفتازاني", "ابن أبي العز الحنفي", "إبراهيم البيجوري", "ملا علي القاري"], "صار شرح التفتازاني على العقائد النسفية من متون المدارس المعتمدة وكثرت عليه الحواشي، أما ابن أبي العز فشرح الطحاوية، والبيجوري شرح جوهرة التوحيد، والقاري شرح الفقه الأكبر."] },

  { id: "aq-071", s: "aqidah", g: 3, d: 3, t: ["creeds-and-authors"], src: "Mullā ʿAlī al-Qārī, Minaḥ al-Rawḍ al-Azhar fī Sharḥ al-Fiqh al-Akbar, introduction", tr: ["maturidi"],
    en: ["The short creed al-Fiqh al-Akbar is traditionally attributed to which imam?", ["Abū Ḥanīfa", "Mālik ibn Anas", "Al-Shāfiʿī", "Aḥmad ibn Ḥanbal"], "Al-Fiqh al-Akbar is attributed to Abū Ḥanīfa through the transmission of his students, and was commented on by Mullā ʿAlī al-Qārī and others. Here 'fiqh' means understanding of the religion's foundations, not law."],
    de: ["Das kurze Glaubensbekenntnis al-Fiqh al-Akbar wird traditionell welchem Imam zugeschrieben?", ["Abū Ḥanīfa", "Mālik ibn Anas", "Aš-Šāfiʿī", "Aḥmad ibn Ḥanbal"], "Al-Fiqh al-Akbar wird über die Überlieferung seiner Schüler Abū Ḥanīfa zugeschrieben und wurde unter anderem von Mullā ʿAlī al-Qārī kommentiert. ‚Fiqh‘ bedeutet hier das Verständnis der Grundlagen der Religion, nicht das Recht."],
    ar: ["إلى أيّ إمام يُنسب متن الفقه الأكبر في العقيدة؟", ["أبي حنيفة", "مالك بن أنس", "الشافعي", "أحمد بن حنبل"], "يُنسب الفقه الأكبر إلى أبي حنيفة من رواية تلاميذه، وشرحه ملا علي القاري وغيره، والمراد بالفقه هنا فهم أصول الدين لا الأحكام العملية."] },

  { id: "aq-072", s: "aqidah", g: 3, d: 3, t: ["iman-definition"], src: "Ibn Taymiyya, Kitāb al-Īmān", tr: ["athari"],
    en: ["How do the Atharī scholars, following the early ahl al-ḥadīth, commonly define īmān?", ["Belief of the heart, statement of the tongue and action of the limbs", "Assent of the heart alone, without speech or deeds", "Statement of the tongue alone, even without belief", "Knowledge of Allah by the intellect, without assent"], "The ahl al-ḥadīth define īmān as belief in the heart, speech on the tongue and deeds of the limbs, and say it increases with obedience and decreases with disobedience. The Ḥanafī-Māturīdī tradition defines its core differently."],
    de: ["Wie definieren die atharitischen Gelehrten im Anschluss an die frühen Ahl al-Ḥadīṯ den Īmān gewöhnlich?", ["Überzeugung des Herzens, Wort der Zunge und Tat der Glieder", "Allein die Bestätigung des Herzens, ohne Wort und Tat", "Allein das Wort der Zunge, auch ohne Überzeugung", "Erkenntnis Allahs durch den Verstand, ohne Bestätigung"], "Die Ahl al-Ḥadīṯ definieren den Īmān als Überzeugung im Herzen, Bekenntnis mit der Zunge und Taten der Glieder und sagen, er nehme durch Gehorsam zu und durch Ungehorsam ab. Die ḥanafitisch-māturīditische Tradition bestimmt seinen Kern anders."],
    ar: ["كيف يعرّف الأثرية تبعًا لأهل الحديث المتقدمين الإيمانَ عادةً؟", ["اعتقاد بالقلب وقول باللسان وعمل بالأركان", "تصديق القلب وحده دون قول أو عمل", "قول اللسان وحده ولو بلا اعتقاد", "معرفة الله بالعقل دون تصديق"], "عرّف أهل الحديث الإيمان بأنه اعتقاد بالجنان وقول باللسان وعمل بالأركان، يزيد بالطاعة وينقص بالمعصية، وللحنفية الماتريدية تحديد آخر لحقيقته."] },

  { id: "aq-073", s: "aqidah", g: 3, d: 4, t: ["iman-definition", "tahawiyya"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya, on īmān", tr: ["maturidi"],
    en: ["How does al-ʿAqīda al-Ṭaḥāwiyya, in line with the Ḥanafī tradition, define īmān?", ["Affirmation with the tongue and assent with the heart", "Assent of the heart, speech and deeds of the limbs", "Knowledge of the heart without any statement", "Outward deeds accompanied by intention"], "Al-Ṭaḥāwī defines īmān as affirmation (iqrār) with the tongue and assent (taṣdīq) with the heart, reflecting the view of Abū Ḥanīfa. Deeds are required and rewarded but not counted as part of the essence of īmān in this definition."],
    de: ["Wie definiert al-ʿAqīda aṭ-Ṭaḥāwiyya im Einklang mit der ḥanafitischen Tradition den Īmān?", ["Bekenntnis mit der Zunge und Bestätigung mit dem Herzen", "Bestätigung des Herzens, Wort und Taten der Glieder", "Wissen des Herzens ohne jedes Bekenntnis", "Äußere Taten, begleitet von der Absicht"], "Aṭ-Ṭaḥāwī definiert den Īmān als Bekenntnis (iqrār) mit der Zunge und Bestätigung (taṣdīq) mit dem Herzen, entsprechend der Ansicht Abū Ḥanīfas. Taten sind geboten und werden belohnt, zählen in dieser Definition aber nicht zum Wesen des Īmān."],
    ar: ["كيف عرّفت العقيدة الطحاوية الإيمانَ موافقةً للمذهب الحنفي؟", ["الإقرار باللسان والتصديق بالجنان", "تصديق بالقلب وقول وعمل بالجوارح", "معرفة القلب دون إقرار", "أعمال ظاهرة تصحبها النية"], "عرّف الطحاوي الإيمان بأنه الإقرار باللسان والتصديق بالجنان، على قول أبي حنيفة، فالأعمال مطلوبة يُثاب عليها لكنها ليست داخلة في حقيقة الإيمان في هذا التعريف."] },

  { id: "aq-074", s: "aqidah", g: 3, d: 4, t: ["iman-increase", "iman-definition"], src: "al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya, on the increase and decrease of īmān", tr: ["maturidi", "athari", "ashari"],
    en: ["Which statement correctly describes the positions on whether īmān increases and decreases?", ["Many Ḥanafī-Māturīdīs hold its core does not vary; Atharīs and most Ashʿarīs affirm increase and decrease", "All Sunni schools deny that īmān increases or decreases in any sense whatsoever", "The Ḥanafīs affirm increase and decrease, while the Atharīs and Ashʿarīs deny it entirely", "Only the Ashʿarīs hold that īmān increases, and only through more knowledge of the proofs"], "The Atharīs and most Ashʿarīs affirm that īmān increases and decreases. Many Ḥanafī-Māturīdīs hold that its core (taṣdīq) does not increase or decrease, while its strength and fruits do vary; several scholars therefore regard much of the difference as verbal."],
    de: ["Welche Aussage beschreibt die Positionen zur Frage, ob der Īmān zu- und abnimmt, zutreffend?", ["Viele Ḥanafiten-Māturīditen: der Kern ändert sich nicht; Athariten und die meisten Ašʿariten bejahen Zu- und Abnahme", "Alle sunnitischen Schulen verneinen jede Zu- oder Abnahme des Īmān in jeglichem Sinn", "Die Ḥanafiten bejahen Zu- und Abnahme, Athariten und Ašʿariten verneinen sie völlig", "Nur die Ašʿariten lehren eine Zunahme, und zwar nur durch mehr Kenntnis der Beweise"], "Die Athariten und die meisten Ašʿariten bejahen, dass der Īmān zu- und abnimmt. Viele Ḥanafiten-Māturīditen lehren, sein Kern (taṣdīq) nehme weder zu noch ab, während seine Stärke und Früchte variieren; mehrere Gelehrte sehen den Unterschied daher weitgehend als sprachlich."],
    ar: ["أيّ العبارات تصف الأقوال في زيادة الإيمان ونقصانه وصفًا صحيحًا؟", ["كثير من الحنفية الماتريدية: أصله لا يتفاوت، والأثرية وأكثر الأشاعرة يثبتون الزيادة والنقصان", "جميع مذاهب أهل السنة تنفي زيادة الإيمان ونقصانه بأي وجه كان", "الحنفية يثبتون الزيادة والنقصان، والأثرية والأشاعرة ينفونهما مطلقًا", "الأشاعرة وحدهم يقولون بالزيادة، وإنما تكون بكثرة العلم بالأدلة"], "يثبت الأثرية وأكثر الأشاعرة زيادة الإيمان ونقصانه، ويرى كثير من الحنفية الماتريدية أن أصله وهو التصديق لا يزيد ولا ينقص وإنما تتفاوت قوته وثمراته، ولذلك عدّ جماعة من العلماء كثيرًا من الخلاف لفظيًّا."] },

  { id: "aq-075", s: "aqidah", g: 3, d: 3, t: ["major-sins", "tahawiyya"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya, on the people of major sins", tr: ["sunni"],
    en: ["According to al-ʿAqīda al-Ṭaḥāwiyya, what is the state in the Hereafter of a believer who dies with major sins unrepented?", ["Under Allah's will: He may forgive or punish, but not eternally", "Certainly in Hell forever", "Certainly forgiven without any reckoning", "Neither a believer nor a disbeliever, in an intermediate station"], "Ahl al-Sunna hold that such a person remains a believer whose fate is under Allah's will: He may forgive him by His grace or punish him by His justice, then bring him out of the Fire. He does not remain in it forever."],
    de: ["Wie ist laut al-ʿAqīda aṭ-Ṭaḥāwiyya der Zustand eines Gläubigen im Jenseits, der mit unbereuten großen Sünden stirbt?", ["Unter Allahs Willen: Er kann vergeben oder strafen, aber nicht ewig", "Mit Sicherheit für immer in der Hölle", "Mit Sicherheit ohne Abrechnung vergeben", "Weder Gläubiger noch Ungläubiger, in einer Zwischenstellung"], "Ahl as-Sunna lehren, dass ein solcher Mensch Gläubiger bleibt und sein Schicksal unter Allahs Willen steht: Er kann ihm aus Gnade vergeben oder ihn aus Gerechtigkeit bestrafen und dann aus dem Feuer herausholen. Ewig bleibt er nicht darin."],
    ar: ["بحسب العقيدة الطحاوية، ما حال المؤمن في الآخرة إذا مات مصرًّا على كبائر لم يتب منها؟", ["في مشيئة الله إن شاء غفر له وإن شاء عذّبه ولا يُخلَّد", "في النار خالدًا قطعًا", "مغفور له قطعًا بلا حساب", "لا مؤمن ولا كافر في منزلة بين المنزلتين"], "مذهب أهل السنة أنه مؤمن ناقص الإيمان، أمره إلى الله إن شاء عفا عنه بفضله وإن شاء عذّبه بعدله ثم يخرجه من النار، ولا يخلد فيها."] },

  { id: "aq-076", s: "aqidah", g: 3, d: 3, t: ["qadar", "levels-of-qadar"], src: "Ibn al-Qayyim, Shifāʾ al-ʿAlīl, on the levels of qadar", tr: ["sunni"],
    en: ["Which list gives the four levels (marātib) of belief in qadar as commonly taught?", ["Knowledge, writing, will, creation", "Knowledge, power, speech, life", "Intention, action, reward, punishment", "Writing, recitation, memorising, acting"], "Scholars commonly teach four levels: Allah's eternal knowledge of everything, His writing of it in the Preserved Tablet, His will by which whatever He wills happens, and His creation of all things, including the acts of His servants."],
    de: ["Welche Liste nennt die vier Stufen (marātib) des Glaubens an den Qadar, wie sie gewöhnlich gelehrt werden?", ["Wissen, Niederschrift, Wille, Erschaffung", "Wissen, Macht, Rede, Leben", "Absicht, Handlung, Lohn, Strafe", "Niederschrift, Rezitation, Auswendiglernen, Handeln"], "Die Gelehrten lehren gewöhnlich vier Stufen: Allahs ewiges Wissen um alles, Seine Niederschrift davon in der wohlverwahrten Tafel, Seinen Willen, durch den geschieht, was Er will, und Seine Erschaffung aller Dinge, einschließlich der Taten der Diener."],
    ar: ["أيّ القوائم تذكر مراتب الإيمان بالقدر الأربع كما تُدرَّس عادةً؟", ["العلم والكتابة والمشيئة والخلق", "العلم والقدرة والكلام والحياة", "النية والعمل والثواب والعقاب", "الكتابة والتلاوة والحفظ والعمل"], "المشهور أن مراتب القدر أربع: علم الله الأزلي بكل شيء، وكتابته ذلك في اللوح المحفوظ، ومشيئته النافذة، وخلقه لكل شيء ومنه أفعال العباد."] },

  { id: "aq-077", s: "aqidah", g: 3, d: 4, t: ["qadar", "levels-of-qadar"], src: "Ibn Kathīr, Tafsīr, on 57:22", tr: ["sunni"], v: "57:22", w: 12,
    en: ["The highlighted word states that every calamity is in something before it occurs. Which level of qadar does this verse most directly establish?", ["Writing (kitāba)", "Creation (khalq)", "Will (mashīʾa)", "Permission (idhn)"], "The verse says every misfortune is recorded in a Book before Allah brings it into being, which is the level of writing in the Preserved Tablet. Knowledge is implied, but the explicit point is the prior record."],
    de: ["Das hervorgehobene Wort sagt, dass jedes Unglück vor seinem Eintreten in etwas steht. Welche Stufe des Qadar begründet dieser Vers am direktesten?", ["Die Niederschrift (kitāba)", "Die Erschaffung (ḫalq)", "Den Willen (mašīʾa)", "Die Erlaubnis (iḏn)"], "Der Vers sagt, dass jedes Unglück in einem Buch verzeichnet ist, bevor Allah es entstehen lässt; das ist die Stufe der Niederschrift in der wohlverwahrten Tafel. Das Wissen ist mitgemeint, doch ausdrücklich geht es um die vorherige Aufzeichnung."],
    ar: ["تذكر الكلمة المظللة أن كل مصيبة مثبتة قبل وقوعها، فأيّ مراتب القدر تقررها الآية مباشرة؟", ["الكتابة", "الخلق", "المشيئة", "الإذن"], "تخبر الآية أن كل مصيبة مكتوبة في كتاب قبل أن يبرأها الله، وهذه مرتبة الكتابة في اللوح المحفوظ، والعلم لازم لها لكن المنصوص هو الكتابة السابقة."] },

  { id: "aq-078", s: "aqidah", g: 3, d: 4, t: ["qadar", "levels-of-qadar"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Qadar (hadith of ʿAbd Allāh ibn ʿAmr)", tr: ["sunni"],
    en: ["According to the hadith of ʿAbd Allāh ibn ʿAmr in Ṣaḥīḥ Muslim, when did Allah write the measures of creation?", ["Fifty thousand years before creating the heavens and the earth", "On the Night of Decree, renewed in every single year", "When the soul is breathed into the foetus in the womb", "One thousand years before the creation of Ādam"], "The hadith states that Allah wrote the measures of all creation fifty thousand years before He created the heavens and the earth. The yearly decree on Laylat al-Qadr and the writing for the foetus are further, detailed records."],
    de: ["Wann schrieb Allah laut dem Hadith von ʿAbdallāh ibn ʿAmr im Ṣaḥīḥ Muslim die Maße der Schöpfung nieder?", ["Fünfzigtausend Jahre vor der Erschaffung der Himmel und der Erde", "In der Nacht der Bestimmung, jedes Jahr aufs Neue", "Wenn dem Embryo im Mutterleib die Seele eingehaucht wird", "Tausend Jahre vor der Erschaffung Ādams"], "Der Hadith sagt, dass Allah die Maße aller Geschöpfe fünfzigtausend Jahre vor der Erschaffung der Himmel und der Erde niederschrieb. Die jährliche Bestimmung in der Laylat al-Qadr und die Niederschrift für den Embryo sind weitere, ausführliche Aufzeichnungen."],
    ar: ["بحسب حديث عبد الله بن عمرو في صحيح مسلم، متى كتب الله مقادير الخلائق؟", ["قبل أن يخلق السماوات والأرض بخمسين ألف سنة", "في ليلة القدر من كل عام", "عند نفخ الروح في الجنين", "قبل خلق آدم بألف سنة"], "في الحديث أن الله كتب مقادير الخلائق قبل أن يخلق السماوات والأرض بخمسين ألف سنة، أما التقدير السنوي في ليلة القدر والكتابة للجنين فتقديرات تفصيلية بعده."] },

  { id: "aq-079", s: "aqidah", g: 3, d: 3, t: ["qadar", "levels-of-qadar"], src: "Ibn Kathīr, Tafsīr, on 85:22", tr: ["sunni"],
    en: ["In what is everything that Allah decreed recorded, according to the creed of Ahl al-Sunna?", ["The Preserved Tablet (al-Lawḥ al-Maḥfūẓ)", "The scrolls of the recording angels", "The Bayt al-Maʿmūr", "The Kursī"], "Ahl al-Sunna believe that Allah recorded everything until the Day of Resurrection in the Preserved Tablet. The recording angels write the deeds of each person as they happen, which is a different record."],
    de: ["Worin ist nach der Glaubenslehre der Ahl as-Sunna alles verzeichnet, was Allah bestimmt hat?", ["In der wohlverwahrten Tafel (al-Lauḥ al-Maḥfūẓ)", "In den Blättern der aufzeichnenden Engel", "Im Bait al-Maʿmūr", "Im Kursī"], "Ahl as-Sunna glauben, dass Allah alles bis zum Tag der Auferstehung in der wohlverwahrten Tafel verzeichnet hat. Die aufzeichnenden Engel schreiben die Taten jedes Menschen, während sie geschehen; das ist eine andere Aufzeichnung."],
    ar: ["في أيّ شيء كُتب كل ما قدّره الله بحسب عقيدة أهل السنة؟", ["اللوح المحفوظ", "صحف الملائكة الكاتبين", "البيت المعمور", "الكرسي"], "يعتقد أهل السنة أن الله كتب كل شيء إلى يوم القيامة في اللوح المحفوظ، أما الملائكة الكاتبون فيكتبون أعمال كل إنسان عند وقوعها، وهي كتابة أخرى."] },

  { id: "aq-080", s: "aqidah", g: 3, d: 4, t: ["resurrection", "last-day"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, on 39:68 (hadith of Abū Hurayra)", tr: ["sunni"],
    en: ["According to the hadith of Abū Hurayra in al-Bukhārī and Muslim, which part of the human body does not decay and is the origin of re-creation?", ["The base of the spine (ʿajb al-dhanab)", "The heart (al-qalb)", "The skull (al-jumjuma)", "The tip of the tongue (ṭaraf al-lisān)"], "The Prophet said that every part of the human being decays except ʿajb al-dhanab, the tip of the tailbone, from which he was created and from which he will be re-created. Ahl al-Sunna affirm a bodily resurrection."],
    de: ["Welcher Teil des menschlichen Körpers zerfällt laut dem Hadith von Abū Huraira bei al-Buḫārī und Muslim nicht und ist der Ursprung der Neuerschaffung?", ["Das Ende der Wirbelsäule (ʿaǧb aḏ-ḏanab)", "Das Herz (al-qalb)", "Der Schädel (al-ǧumǧuma)", "Die Zungenspitze (ṭaraf al-lisān)"], "Der Prophet sagte, dass jeder Teil des Menschen zerfällt außer ʿaǧb aḏ-ḏanab, der Spitze des Steißbeins, aus der er erschaffen wurde und aus der er neu erschaffen wird. Ahl as-Sunna bekräftigen eine leibliche Auferstehung."],
    ar: ["بحسب حديث أبي هريرة في الصحيحين، أيّ جزء من جسد الإنسان لا يبلى ومنه يُركَّب الخلق يوم القيامة؟", ["عَجْب الذَّنَب", "القلب", "الجمجمة", "طرف اللسان"], "أخبر النبي ﷺ أن كل ابن آدم يبلى إلا عجب الذنب منه خُلق وفيه يُركَّب، وأهل السنة يثبتون البعث بالأجساد والأرواح."] },

  { id: "aq-081", s: "aqidah", g: 3, d: 3, t: ["resurrection", "intercession"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Faḍāʾil (I am the master of the children of Ādam)", tr: ["sunni"],
    en: ["According to the hadith in Ṣaḥīḥ Muslim, who is the first for whom the grave will split open on the Day of Resurrection?", ["The Prophet Muḥammad", "The Prophet Ādam", "The Prophet Ibrāhīm", "The Prophet Mūsā"], "The Prophet said that he is the master of the children of Ādam on the Day of Resurrection, the first for whom the grave splits open, the first to intercede and the first whose intercession is accepted."],
    de: ["Wer ist laut dem Hadith im Ṣaḥīḥ Muslim der Erste, für den sich am Tag der Auferstehung das Grab öffnet?", ["Der Prophet Muḥammad", "Der Prophet Ādam", "Der Prophet Ibrāhīm", "Der Prophet Mūsā"], "Der Prophet sagte, dass er am Tag der Auferstehung der Herr der Kinder Ādams ist, der Erste, für den sich das Grab öffnet, der erste Fürsprecher und der Erste, dessen Fürsprache angenommen wird."],
    ar: ["بحسب الحديث في صحيح مسلم، مَن أول من ينشق عنه القبر يوم القيامة؟", ["النبي محمد ﷺ", "النبي آدم", "النبي إبراهيم", "النبي موسى"], "أخبر النبي ﷺ أنه سيد ولد آدم يوم القيامة وأول من ينشق عنه القبر وأول شافع وأول مشفَّع."] },

  { id: "aq-082", s: "aqidah", g: 3, d: 4, t: ["signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Fitan (hadith of al-Nawwās ibn Samʿān)", tr: ["sunni"],
    en: ["According to the hadith of al-Nawwās ibn Samʿān in Ṣaḥīḥ Muslim, where will ʿĪsā kill the Dajjāl?", ["At the gate of Ludd", "At the Damascus mosque", "On Mount Sinai", "At the walls of Medina"], "The hadith relates that ʿĪsā descends near the white minaret east of Damascus, pursues the Dajjāl and kills him at the gate of Ludd. Other hadith state that the Dajjāl cannot enter Medina."],
    de: ["Wo wird ʿĪsā laut dem Hadith von an-Nawwās ibn Samʿān im Ṣaḥīḥ Muslim den Daǧǧāl töten?", ["Am Tor von Ludd", "In der Moschee von Damaskus", "Am Berg Sinai", "An den Mauern Medinas"], "Der Hadith berichtet, dass ʿĪsā beim weißen Minarett östlich von Damaskus herabsteigt, den Daǧǧāl verfolgt und ihn am Tor von Ludd tötet. Andere Hadithe sagen, dass der Daǧǧāl Medina nicht betreten kann."],
    ar: ["بحسب حديث النواس بن سمعان في صحيح مسلم، أين يقتل عيسى الدجال؟", ["بباب لُدّ", "في مسجد دمشق", "على جبل الطور", "عند أسوار المدينة"], "في الحديث أن عيسى ينزل عند المنارة البيضاء شرقي دمشق فيطلب الدجال حتى يدركه بباب لد فيقتله، وفي أحاديث أخرى أن الدجال لا يدخل المدينة."] },

  { id: "aq-083", s: "aqidah", g: 3, d: 3, t: ["signs-of-the-hour"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tafsīr, on 6:158", tr: ["sunni"], v: "6:158",
    en: ["The Prophet connected the verse shown with which major sign, after which faith or repentance no longer benefits one who had not believed before?", ["The rising of the sun from the west", "The appearance of the smoke", "The coming of Yaʾjūj and Maʾjūj", "The fire that drives people to the gathering"], "In al-Bukhārī the Prophet said that the Hour will not come until the sun rises from the west, and when people see it they will all believe, but that is when faith does not benefit a soul that had not believed before; he then recited this verse."],
    de: ["Mit welchem großen Zeichen verband der Prophet den angezeigten Vers, nach dem Glaube oder Reue dem nicht mehr nützen, der vorher nicht geglaubt hat?", ["Dem Aufgang der Sonne im Westen", "Dem Erscheinen des Rauches", "Dem Kommen von Yaʾǧūǧ und Maʾǧūǧ", "Dem Feuer, das die Menschen zur Versammlung treibt"], "Bei al-Buḫārī sagte der Prophet, die Stunde komme nicht, bis die Sonne im Westen aufgeht; wenn die Menschen das sehen, glauben alle, doch dann nützt einer Seele der Glaube nicht, die vorher nicht geglaubt hat; danach rezitierte er diesen Vers."],
    ar: ["ربط النبي ﷺ الآية المعروضة بأيّ علامة كبرى لا ينفع بعدها إيمان من لم يكن آمن من قبل؟", ["طلوع الشمس من مغربها", "ظهور الدخان", "خروج يأجوج ومأجوج", "النار التي تحشر الناس"], "في البخاري أن النبي ﷺ قال: لا تقوم الساعة حتى تطلع الشمس من مغربها، فإذا رآها الناس آمنوا أجمعون، وذلك حين لا ينفع نفسًا إيمانها لم تكن آمنت من قبل، ثم تلا الآية."] },

  { id: "aq-084", s: "aqidah", g: 3, d: 4, t: ["signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Fitan (hadith of Ḥudhayfa ibn Asīd)", tr: ["sunni"],
    en: ["How many major signs of the Hour are listed in the hadith of Ḥudhayfa ibn Asīd in Ṣaḥīḥ Muslim?", ["Ten", "Seven", "Five", "Twelve"], "The hadith lists ten signs: the smoke, the Dajjāl, the Beast, the sun rising from the west, the descent of ʿĪsā, Yaʾjūj and Maʾjūj, three landslides (in the east, the west and Arabia), and a fire from Yemen driving people to their gathering."],
    de: ["Wie viele große Zeichen der Stunde werden im Hadith von Ḥuḏaifa ibn Asīd im Ṣaḥīḥ Muslim aufgezählt?", ["Zehn", "Sieben", "Fünf", "Zwölf"], "Der Hadith nennt zehn Zeichen: den Rauch, den Daǧǧāl, das Tier, den Sonnenaufgang im Westen, das Herabsteigen ʿĪsās, Yaʾǧūǧ und Maʾǧūǧ, drei Erdeinbrüche (im Osten, im Westen und in Arabien) und ein Feuer aus dem Jemen, das die Menschen zu ihrer Versammlung treibt."],
    ar: ["كم علامة كبرى للساعة ذُكرت في حديث حذيفة بن أسيد في صحيح مسلم؟", ["عشر", "سبع", "خمس", "اثنتا عشرة"], "ذكر الحديث عشر آيات: الدخان والدجال والدابة وطلوع الشمس من مغربها ونزول عيسى ويأجوج ومأجوج وثلاثة خسوف بالمشرق والمغرب وجزيرة العرب ونارًا تخرج من اليمن تطرد الناس إلى محشرهم."] },

  { id: "aq-085", s: "aqidah", g: 3, d: 3, t: ["mizan", "last-day"], src: "Ibn Kathīr, Tafsīr, on 21:47", tr: ["sunni"], v: "21:47", w: 2,
    en: ["What do Ahl al-Sunna affirm about the scales mentioned in the highlighted word?", ["Real scales with pans, set up on that Day", "Only a metaphor for Allah's perfect justice", "Scales set up only for the disbelievers", "Scales held by the prophets for their peoples"], "Ahl al-Sunna affirm a real balance; the hadith of the card (al-biṭāqa) in al-Tirmidhī mentions its pans. Taking it as a mere metaphor for justice was the view of some outside Ahl al-Sunna."],
    de: ["Was bekräftigen Ahl as-Sunna über die im hervorgehobenen Wort genannten Waagen?", ["Wirkliche Waagen mit Schalen, an jenem Tag aufgestellt", "Nur ein Bild für Allahs vollkommene Gerechtigkeit", "Waagen, die nur für die Ungläubigen aufgestellt werden", "Waagen, die die Propheten für ihre Völker halten"], "Ahl as-Sunna bekräftigen eine wirkliche Waage; der Hadith der Karte (al-biṭāqa) bei at-Tirmiḏī erwähnt ihre Schalen. Sie nur als Bild für Gerechtigkeit zu verstehen, war die Ansicht einiger außerhalb der Ahl as-Sunna."],
    ar: ["ماذا يثبت أهل السنة في الموازين المذكورة في الكلمة المظللة؟", ["موازين حقيقية لها كفتان تُنصب يومئذ", "مجاز عن عدل الله الكامل فحسب", "موازين تُنصب للكفار وحدهم", "موازين يحملها الأنبياء لأقوامهم"], "يثبت أهل السنة ميزانًا حقيقيًّا، وفي حديث البطاقة عند الترمذي ذكر كفتيه، أما حمله على مجرد العدل فقول بعض من خالف أهل السنة."] },

  { id: "aq-086", s: "aqidah", g: 3, d: 3, t: ["paradise-and-hell"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Jihād (degrees of the mujāhidīn)", tr: ["sunni"],
    en: ["According to the hadith in Ṣaḥīḥ al-Bukhārī, which level of Paradise is the highest, with the Throne of the Most Merciful above it?", ["Al-Firdaws", "Jannat ʿAdn", "Jannat al-Maʾwā", "Dār al-Salām"], "The Prophet said that when you ask Allah, ask Him for al-Firdaws, for it is the middle and highest part of Paradise, above it is the Throne of the Most Merciful, and from it the rivers of Paradise flow."],
    de: ["Welche Stufe des Paradieses ist laut dem Hadith im Ṣaḥīḥ al-Buḫārī die höchste, über der der Thron des Allerbarmers ist?", ["Al-Firdaus", "Ǧannat ʿAdn", "Ǧannat al-Maʾwā", "Dār as-Salām"], "Der Prophet wies an, Allah um al-Firdaus zu bitten, denn es sei die Mitte und der höchste Teil des Paradieses, darüber sei der Thron des Allerbarmers, und von dort entsprängen die Flüsse des Paradieses."],
    ar: ["بحسب الحديث في صحيح البخاري، ما أعلى درجات الجنة التي فوقها عرش الرحمن؟", ["الفردوس", "جنة عدن", "جنة المأوى", "دار السلام"], "قال النبي ﷺ: إذا سألتم الله فاسألوه الفردوس فإنه أوسط الجنة وأعلى الجنة، وفوقه عرش الرحمن، ومنه تفجّر أنهار الجنة."] },

  { id: "aq-087", s: "aqidah", g: 3, d: 3, t: ["angels", "last-day"], src: "Ibn Kathīr, Tafsīr, on 69:17", tr: ["sunni"], v: "69:17", w: 9,
    en: ["According to the highlighted word, how many will bear the Throne of your Lord above them on that Day?", ["Eight", "Four", "Seven", "Twelve"], "The verse states that on that Day eight will carry the Throne of your Lord above them. Some reports say they are four before the Day of Judgment, completed to eight on that Day."],
    de: ["Wie viele werden laut dem hervorgehobenen Wort an jenem Tag den Thron des Herrn über sich tragen?", ["Acht", "Vier", "Sieben", "Zwölf"], "Der Vers sagt, dass an jenem Tag acht den Thron des Herrn über sich tragen werden. Manche Berichte sagen, es seien vor dem Tag des Gerichts vier, die an jenem Tag auf acht ergänzt werden."],
    ar: ["بحسب الكلمة المظللة، كم يحمل عرش ربك فوقهم يومئذ؟", ["ثمانية", "أربعة", "سبعة", "اثنا عشر"], "تخبر الآية أن عرش ربك يحمله فوقهم يومئذ ثمانية، وفي بعض الآثار أنهم أربعة قبل يوم القيامة ويُكمَّلون ثمانية يومئذ."] },

  { id: "aq-088", s: "aqidah", g: 3, d: 4, t: ["angels"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Badʾ al-Khalq (hadith of the Miʿrāj)", tr: ["sunni"],
    en: ["According to the hadith of the Miʿrāj in al-Bukhārī and Muslim, how many angels enter al-Bayt al-Maʿmūr every day, never to return to it?", ["Seventy thousand", "Seven thousand", "Seven hundred thousand", "Seventy"], "In the hadith of the Miʿrāj the Prophet was shown al-Bayt al-Maʿmūr, which seventy thousand angels enter every day and never return to. Scholars cite it to show the vast number of angels, known fully only to Allah (74:31)."],
    de: ["Wie viele Engel betreten laut dem Hadith der Miʿrāǧ bei al-Buḫārī und Muslim täglich al-Bait al-Maʿmūr, ohne je dorthin zurückzukehren?", ["Siebzigtausend", "Siebentausend", "Siebenhunderttausend", "Siebzig"], "Im Hadith der Miʿrāǧ wurde dem Propheten al-Bait al-Maʿmūr gezeigt, das täglich siebzigtausend Engel betreten, die nie zurückkehren. Die Gelehrten führen es an, um die gewaltige Zahl der Engel zu zeigen, die nur Allah vollständig kennt (74:31)."],
    ar: ["بحسب حديث المعراج في الصحيحين، كم ملكًا يدخل البيت المعمور كل يوم ثم لا يعودون إليه؟", ["سبعون ألفًا", "سبعة آلاف", "سبعمائة ألف", "سبعون"], "في حديث المعراج رُفع للنبي ﷺ البيت المعمور يدخله كل يوم سبعون ألف ملك لا يعودون إليه، ويستدل به العلماء على كثرة الملائكة التي لا يحصيها إلا الله (المدثر 31)."] },

  { id: "aq-089", s: "aqidah", g: 3, d: 3, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 82:10–12", tr: ["sunni"], v: "82:11", w: 2,
    en: ["The highlighted word describes the angels who guard over people as doing what?", ["Writing down their deeds", "Taking their souls", "Bringing them rain", "Carrying the Throne"], "Sūrat al-Infiṭār describes guardians over people who are noble and who write, knowing what people do. These are the recording angels; elsewhere one on the right and one on the left are mentioned (50:17)."],
    de: ["Was tun laut dem hervorgehobenen Wort die Engel, die über die Menschen wachen?", ["Sie schreiben ihre Taten auf", "Sie nehmen ihre Seelen", "Sie bringen ihnen Regen", "Sie tragen den Thron"], "Sūrat al-Infiṭār beschreibt Hüter über den Menschen, die edel sind und schreiben und wissen, was die Menschen tun. Das sind die aufzeichnenden Engel; an anderer Stelle werden einer rechts und einer links erwähnt (50:17)."],
    ar: ["بمَ تصف الكلمة المظللة الملائكةَ الحافظين على الناس؟", ["بأنهم يكتبون أعمالهم", "بأنهم يقبضون أرواحهم", "بأنهم يأتونهم بالمطر", "بأنهم يحملون العرش"], "وصفت سورة الانفطار الحافظين على الناس بأنهم كرام كاتبون يعلمون ما يفعلون، وهم الملائكة الكتبة، وفي سورة ق ذكر قعيد عن اليمين وقعيد عن الشمال (17)."] },

  { id: "aq-090", s: "aqidah", g: 3, d: 4, t: ["miracles", "karamat"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya, on the karāmāt of the awliyāʾ; al-Bayjūrī, Tuḥfat al-Murīd", tr: ["sunni"],
    en: ["What distinguishes a karāma from a muʿjiza in Sunni creed?", ["It occurs for a righteous believer who claims no prophethood", "It can only occur after the death of the righteous person", "It is always greater in scale than any muʿjiza", "It is a natural event that science can explain"], "Both break the normal course of things. A muʿjiza accompanies a claim of prophethood with a challenge, while a karāma is an honour for a righteous follower who claims no prophethood. Ahl al-Sunna affirm the karāmāt of the awliyāʾ."],
    de: ["Was unterscheidet in der sunnitischen Glaubenslehre eine Karāma von einer Muʿǧiza?", ["Sie geschieht einem rechtschaffenen Gläubigen ohne Anspruch auf Prophetentum", "Sie kann nur nach dem Tod des rechtschaffenen Menschen geschehen", "Sie ist stets größer im Ausmaß als jede Muʿǧiza", "Sie ist ein natürliches, wissenschaftlich erklärbares Ereignis"], "Beide durchbrechen den gewohnten Lauf der Dinge. Eine Muʿǧiza begleitet einen Anspruch auf Prophetentum mit Herausforderung, eine Karāma ist eine Ehrung für einen rechtschaffenen Anhänger, der kein Prophetentum beansprucht. Ahl as-Sunna bekräftigen die Karāmāt der Gottesfreunde."],
    ar: ["ما الذي يميّز الكرامة عن المعجزة في عقيدة أهل السنة؟", ["تجري لمؤمن صالح لا يدّعي النبوة", "لا تقع إلا بعد موت الرجل الصالح", "أعظم دائمًا من كل معجزة", "حادثة طبيعية يفسرها العلم"], "كلاهما خارق للعادة، لكن المعجزة تقترن بدعوى النبوة والتحدي، والكرامة إكرام لولي صالح متبع لا يدّعي النبوة، وأهل السنة يثبتون كرامات الأولياء."] },

  { id: "aq-091", s: "aqidah", g: 3, d: 4, t: ["miracles", "messengers"], src: "al-Bayjūrī, Tuḥfat al-Murīd sharḥ Jawharat al-Tawḥīd, on the muʿjiza", tr: ["sunni"],
    en: ["Which element is part of the theologians' definition of a muʿjiza?", ["It is coupled with a challenge (taḥaddī) by one claiming prophethood", "It must be witnessed by every member of the community", "It must occur in the Ḥaram of Mecca", "It must leave a physical trace until the Last Day"], "Theologians define a muʿjiza as an event breaking the normal course of things, coupled with a challenge by one who claims prophethood, and which cannot be matched. This distinguishes it from a karāma and from sorcery."],
    de: ["Welches Element gehört zur Definition einer Muʿǧiza bei den Theologen?", ["Sie ist mit einer Herausforderung (taḥaddī) durch einen verbunden, der Prophetentum beansprucht", "Jedes Mitglied der Gemeinschaft muss sie bezeugen", "Sie muss im Ḥaram von Mekka geschehen", "Sie muss bis zum Jüngsten Tag eine sichtbare Spur hinterlassen"], "Die Theologen definieren eine Muʿǧiza als ein Ereignis, das den gewohnten Lauf durchbricht, verbunden mit einer Herausforderung durch den, der Prophetentum beansprucht, und dem nichts entgegengesetzt werden kann. Das unterscheidet sie von Karāma und Zauberei."],
    ar: ["أيّ القيود من تعريف المتكلمين للمعجزة؟", ["أنها مقرونة بالتحدي ممن يدّعي النبوة", "أن يشاهدها كل أفراد الأمة", "أن تقع في الحرم المكي", "أن يبقى لها أثر حسي إلى يوم القيامة"], "عرّف المتكلمون المعجزة بأنها أمر خارق للعادة مقرون بالتحدي ممن يدّعي النبوة سالم عن المعارضة، وبهذا تفترق عن الكرامة والسحر."] },

  { id: "aq-092", s: "aqidah", g: 3, d: 4, t: ["divine-attributes", "approaches-to-attributes"], src: "al-Bayhaqī, al-Asmāʾ wa-l-Ṣifāt, chapter on istiwāʾ", tr: ["sunni"], v: "20:5", w: 4,
    en: ["Asked how the act in the highlighted word is, which imam famously replied that it is known, its 'how' is not comprehended, believing in it is obligatory and asking about it is an innovation?", ["Mālik ibn Anas", "Abū Ḥanīfa", "Al-Shāfiʿī", "Al-Awzāʿī"], "This answer is widely reported from Imām Mālik, with similar words from his teacher Rabīʿa. Atharīs, Ashʿarīs and Māturīdīs all cite it, while reading it in light of their own approaches to the attributes."],
    de: ["Welcher Imam antwortete auf die Frage, wie die Handlung im hervorgehobenen Wort sei, berühmt, sie sei bekannt, ihr Wie sei nicht begreifbar, an sie zu glauben sei Pflicht und danach zu fragen eine Neuerung?", ["Mālik ibn Anas", "Abū Ḥanīfa", "Aš-Šāfiʿī", "Al-Auzāʿī"], "Diese Antwort wird weithin von Imām Mālik überliefert, mit ähnlichen Worten von seinem Lehrer Rabīʿa. Athariten, Ašʿariten und Māturīditen führen sie alle an und lesen sie im Licht ihres jeweiligen Zugangs zu den Eigenschaften."],
    ar: ["لما سُئل عن كيفية ما في الكلمة المظللة، أيّ الأئمة اشتهر جوابه بأنه معلوم والكيف غير معقول والإيمان به واجب والسؤال عنه بدعة؟", ["مالك بن أنس", "أبو حنيفة", "الشافعي", "الأوزاعي"], "اشتهر هذا الجواب عن الإمام مالك، ورُوي نحوه عن شيخه ربيعة، ويستشهد به الأثرية والأشاعرة والماتريدية جميعًا مع قراءة كل منهم له وفق منهجه في الصفات."] },

  { id: "aq-093", s: "aqidah", g: 3, d: 3, t: ["divine-attributes", "tanzih"], src: "Ibn Kathīr, Tafsīr, on 42:11", tr: ["sunni"], v: "42:11", w: 15,
    en: ["The highlighted expression and the end of the verse are cited by all Sunni schools as the basis for which principle?", ["Negating any likeness to Allah while affirming His attributes", "Interpreting every attribute in a metaphorical sense", "Affirming the attributes with a likeness to creatures", "Refraining from mentioning any attribute at all"], "The verse negates that anything is like Him, then affirms that He is the All-Hearing, the All-Seeing. Scholars derive from it the balance between tanzīh (negating likeness) and affirmation, avoiding both tashbīh and taʿṭīl."],
    de: ["Der hervorgehobene Ausdruck und das Ende des Verses werden von allen sunnitischen Schulen als Grundlage welchen Prinzips angeführt?", ["Jede Ähnlichkeit mit Allah zu verneinen und Seine Eigenschaften zu bekräftigen", "Jede Eigenschaft in einem bildlichen Sinn zu deuten", "Die Eigenschaften mit Ähnlichkeit zu den Geschöpfen zu bekräftigen", "Überhaupt keine Eigenschaft zu erwähnen oder zu nennen"], "Der Vers verneint, dass Ihm irgendetwas gleicht, und bekräftigt dann, dass Er der Allhörende, der Allsehende ist. Die Gelehrten leiten daraus das Gleichgewicht zwischen Tanzīh (Verneinung der Ähnlichkeit) und Bekräftigung ab und meiden sowohl Tašbīh als auch Taʿṭīl."],
    ar: ["يستدل جميع مذاهب أهل السنة بالعبارة المظللة وختام الآية على أيّ أصل؟", ["نفي المماثلة عن الله مع إثبات صفاته", "تأويل كل صفة على المجاز", "إثبات الصفات مع التشبيه بالمخلوق", "الإمساك عن ذكر أي صفة"], "نفت الآية أن يكون كمثله شيء ثم أثبتت أنه السميع البصير، فاستنبط العلماء منها الجمع بين التنزيه والإثبات مع اجتناب التشبيه والتعطيل."] },

  { id: "aq-094", s: "aqidah", g: 3, d: 3, t: ["shirk", "minor-shirk"], src: "Abū Dāwūd, al-Sunan, Kitāb al-Ṭibb (on ṭiyara)", tr: ["sunni"],
    en: ["In the hadith of Ibn Masʿūd in the Sunan of Abū Dāwūd and al-Tirmidhī, how did the Prophet describe taking evil omens (ṭiyara)?", ["As shirk", "As merely disliked", "As permitted when travelling", "As a form of trust in Allah"], "The Prophet said that ṭiyara is shirk, repeating it, because it attributes harm and benefit to omens. Scholars classify it as minor shirk unless one believes the omen itself causes events."],
    de: ["Wie beschrieb der Prophet im Hadith von Ibn Masʿūd in den Sunan von Abū Dāwūd und at-Tirmiḏī das Ziehen böser Vorzeichen (ṭiyara)?", ["Als Širk", "Als bloß verpönt", "Als auf Reisen erlaubt", "Als eine Form des Gottvertrauens"], "Der Prophet sagte, Ṭiyara sei Širk, und wiederholte es, weil sie Schaden und Nutzen Vorzeichen zuschreibt. Die Gelehrten ordnen sie als kleinen Širk ein, es sei denn, man glaubt, das Vorzeichen selbst bewirke die Ereignisse."],
    ar: ["في حديث ابن مسعود عند أبي داود والترمذي، بمَ وصف النبي ﷺ الطِّيَرة؟", ["بأنها شرك", "بأنها مكروهة فحسب", "بأنها جائزة في السفر", "بأنها من التوكل"], "قال النبي ﷺ: الطيرة شرك، وكرّرها، لأنها تعليق للنفع والضر بما لا تأثير له، ويعدّها العلماء من الشرك الأصغر إلا إذا اعتقد أن الطائر نفسه هو الفاعل."] },

  { id: "aq-095", s: "aqidah", g: 3, d: 3, t: ["nifaq", "shirk"], src: "Ibn Rajab, Jāmiʿ al-ʿUlūm wa-l-Ḥikam, hadith on the signs of the hypocrite", tr: ["sunni"],
    en: ["What distinguishes major hypocrisy (nifāq iʿtiqādī) from minor hypocrisy (nifāq ʿamalī)?", ["Major conceals disbelief under outward Islam; minor is traits like lying", "Major is lying in speech; minor is concealing disbelief in the heart", "Major concerns those in authority; minor concerns ordinary people", "Major is expiated by fasting and charity; minor is never expiated"], "Major hypocrisy is outwardly showing Islam while concealing disbelief, and takes one out of the religion. Minor hypocrisy consists of traits such as lying, breaking promises and betraying trusts, mentioned in the hadith of al-Bukhārī and Muslim; it is sinful but does not by itself remove one from Islam."],
    de: ["Was unterscheidet die große Heuchelei (nifāq iʿtiqādī) von der kleinen (nifāq ʿamalī)?", ["Die große verbirgt Unglauben unter äußerem Islam; die kleine sind Züge wie Lügen", "Die große ist Lügen in der Rede; die kleine das Verbergen von Unglauben", "Die große betrifft Machthaber; die kleine betrifft gewöhnliche Menschen", "Die große wird durch Fasten und Spenden getilgt; die kleine nie"], "Große Heuchelei heißt, äußerlich den Islam zu zeigen und Unglauben zu verbergen; sie führt aus der Religion. Kleine Heuchelei sind Eigenschaften wie Lügen, Wortbruch und Veruntreuung, erwähnt im Hadith bei al-Buḫārī und Muslim; sie ist sündhaft, führt aber für sich nicht aus dem Islam."],
    ar: ["ما الفرق بين النفاق الاعتقادي والنفاق العملي؟", ["الاعتقادي إبطان الكفر مع إظهار الإسلام، والعملي خصال كالكذب", "الاعتقادي الكذب في الحديث، والعملي إبطان الكفر في القلب", "الاعتقادي في أهل السلطان، والعملي في عامة الناس", "الاعتقادي يكفّره الصوم والصدقة، والعملي لا يُكفَّر"], "النفاق الاعتقادي إظهار الإسلام وإبطان الكفر وهو مخرج من الملة، والعملي خصال كالكذب في الحديث وإخلاف الوعد وخيانة الأمانة كما في حديث الصحيحين، وهو معصية لا يخرج من الملة بذاته."] },

  { id: "aq-096", s: "aqidah", g: 3, d: 3, t: ["paradise-and-hell", "tahawiyya"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya, on Paradise and the Fire", tr: ["sunni"],
    en: ["What does al-ʿAqīda al-Ṭaḥāwiyya state about Paradise and the Fire?", ["They are already created and will never perish or end", "They will be created only after the Day of Judgment", "They exist now but will both come to an end", "They are states of the soul, not real places"], "Al-Ṭaḥāwī states that Paradise and the Fire are created, and will never perish or come to an end. That they already exist is supported by the Quran's description of them as prepared, and by hadith of the Miʿrāj."],
    de: ["Was sagt al-ʿAqīda aṭ-Ṭaḥāwiyya über das Paradies und das Feuer?", ["Sie sind bereits erschaffen und werden nie vergehen oder enden", "Sie werden erst nach dem Tag des Gerichts erschaffen", "Sie existieren jetzt, werden aber beide enden", "Sie sind Zustände der Seele, keine wirklichen Orte"], "Aṭ-Ṭaḥāwī sagt, dass Paradies und Feuer erschaffen sind und nie vergehen oder enden. Dass sie bereits existieren, stützt sich auf die Beschreibung im Koran als bereitet und auf die Hadithe der Miʿrāǧ."],
    ar: ["ماذا تقرر العقيدة الطحاوية في شأن الجنة والنار؟", ["أنهما مخلوقتان لا تفنيان ولا تبيدان", "أنهما تُخلقان بعد يوم القيامة", "أنهما موجودتان الآن وتفنيان", "أنهما حالان للنفس لا مكانان حقيقيان"], "قرر الطحاوي أن الجنة والنار مخلوقتان لا تفنيان أبدًا ولا تبيدان، ووجودهما الآن دلّ عليه وصف القرآن لهما بأنهما أُعدّتا، وأحاديث المعراج."] },

  { id: "aq-097", s: "aqidah", g: 3, d: 4, t: ["creeds-and-authors", "tahawiyya"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, introduction", tr: ["athari"],
    en: ["Which commentary on al-ʿAqīda al-Ṭaḥāwiyya, by a Ḥanafī judge of the 8th century AH, became the standard reference in Atharī circles?", ["The commentary of Ibn Abī al-ʿIzz", "The commentary of al-Taftāzānī", "The commentary of al-Bayjūrī", "The commentary of al-Sanūsī"], "Ṣadr al-Dīn Ibn Abī al-ʿIzz al-Ḥanafī wrote a commentary on the Ṭaḥāwiyya drawing heavily on Ibn Taymiyya and Ibn al-Qayyim; it became the most used commentary in Atharī teaching. Other commentaries on the Ṭaḥāwiyya follow the Māturīdī reading."],
    de: ["Welcher Kommentar zu al-ʿAqīda aṭ-Ṭaḥāwiyya, verfasst von einem ḥanafitischen Richter des 8. Jahrhunderts n. H., wurde in atharitischen Kreisen zum Standardwerk?", ["Der Kommentar von Ibn Abī l-ʿIzz", "Der Kommentar von at-Taftāzānī", "Der Kommentar von al-Bāǧūrī", "Der Kommentar von as-Sanūsī"], "Ṣadr ad-Dīn Ibn Abī l-ʿIzz al-Ḥanafī schrieb einen Kommentar zur Ṭaḥāwiyya, der sich stark auf Ibn Taimiyya und Ibn al-Qayyim stützt; er wurde der meistgenutzte Kommentar im atharitischen Unterricht. Andere Kommentare zur Ṭaḥāwiyya folgen der māturīditischen Lesart."],
    ar: ["أيّ شروح العقيدة الطحاوية، لقاضٍ حنفي من القرن الثامن الهجري، صار المرجع المعتمد عند الأثرية؟", ["شرح ابن أبي العز", "شرح التفتازاني", "شرح البيجوري", "شرح السنوسي"], "شرح صدر الدين ابن أبي العز الحنفي الطحاوية مستفيدًا كثيرًا من ابن تيمية وابن القيم، فصار أشهر شروحها في التدريس عند الأثرية، ولها شروح أخرى على طريقة الماتريدية."] },

  { id: "aq-098", s: "aqidah", g: 4, d: 5, t: ["creeds-and-authors", "ahl-al-sunna"], src: "al-Saffārīnī, Lawāmiʿ al-Anwār al-Bahiyya, introduction", tr: ["athari", "ashari", "maturidi"],
    en: ["Which Ḥanbalī scholar wrote in Lawāmiʿ al-Anwār al-Bahiyya that Ahl al-Sunna wa-l-Jamāʿa comprise three groups: the Athariyya, the Ashʿariyya and the Māturīdiyya?", ["Muḥammad al-Saffārīnī", "Ibn Qudāma al-Maqdisī", "Ibn Rajab al-Ḥanbalī", "Marʿī ibn Yūsuf al-Karmī"], "Al-Saffārīnī, in his commentary on his own poem al-Durra al-Muḍiyya, names three groups of Ahl al-Sunna: the Athariyya with Imām Aḥmad as their imam, the Ashʿariyya and the Māturīdiyya. The statement is often cited when describing the scope of Sunni creed."],
    de: ["Welcher ḥanbalitische Gelehrte schrieb in Lawāmiʿ al-Anwār al-Bahiyya, dass die Ahl as-Sunna wa-l-Ǧamāʿa drei Gruppen umfassen: die Athariyya, die Ašʿariyya und die Māturīdiyya?", ["Muḥammad as-Saffārīnī", "Ibn Qudāma al-Maqdisī", "Ibn Raǧab al-Ḥanbalī", "Marʿī ibn Yūsuf al-Karmī"], "As-Saffārīnī nennt in seinem Kommentar zu seinem eigenen Gedicht ad-Durra al-Muḍiyya drei Gruppen der Ahl as-Sunna: die Athariyya mit Imām Aḥmad als ihrem Imam, die Ašʿariyya und die Māturīdiyya. Die Aussage wird oft angeführt, wenn der Umfang der sunnitischen Glaubenslehre beschrieben wird."],
    ar: ["أيّ عالم حنبلي ذكر في لوامع الأنوار البهية أن أهل السنة والجماعة ثلاث فرق: الأثرية والأشعرية والماتريدية؟", ["محمد السفاريني", "ابن قدامة المقدسي", "ابن رجب الحنبلي", "مرعي بن يوسف الكرمي"], "ذكر السفاريني في شرحه على منظومته الدرة المضية أن أهل السنة ثلاث فرق: الأثرية وإمامهم أحمد، والأشعرية، والماتريدية، وكثيرًا ما يُستشهد بكلامه في بيان سعة مسمّى أهل السنة."] },

  { id: "aq-099", s: "aqidah", g: 4, d: 4, t: ["creeds-and-authors", "ashari-maturidi"], src: "Ibn ʿAsākir, Tabyīn Kadhib al-Muftarī, on al-Ashʿarī's early life", tr: ["ashari"],
    en: ["Under which Muʿtazilī teacher did Abū al-Ḥasan al-Ashʿarī study before he left the Muʿtazila?", ["Abū ʿAlī al-Jubbāʾī", "Al-Qāḍī ʿAbd al-Jabbār", "Wāṣil ibn ʿAṭāʾ", "Al-Naẓẓām"], "Al-Ashʿarī studied for years under Abū ʿAlī al-Jubbāʾī, head of the Basran Muʿtazila, before publicly leaving them. Wāṣil and al-Naẓẓām lived earlier, and al-Qāḍī ʿAbd al-Jabbār later."],
    de: ["Bei welchem muʿtazilitischen Lehrer studierte Abū l-Ḥasan al-Ašʿarī, bevor er die Muʿtazila verließ?", ["Abū ʿAlī al-Ǧubbāʾī", "Al-Qāḍī ʿAbd al-Ǧabbār", "Wāṣil ibn ʿAṭāʾ", "An-Naẓẓām"], "Al-Ašʿarī studierte jahrelang bei Abū ʿAlī al-Ǧubbāʾī, dem Haupt der basrischen Muʿtazila, bevor er sich öffentlich von ihnen lossagte. Wāṣil und an-Naẓẓām lebten früher, al-Qāḍī ʿAbd al-Ǧabbār später."],
    ar: ["على أيّ شيخ معتزلي درس أبو الحسن الأشعري قبل أن يفارق المعتزلة؟", ["أبي علي الجبائي", "القاضي عبد الجبار", "واصل بن عطاء", "النظّام"], "لازم الأشعري أبا علي الجبائي شيخ معتزلة البصرة سنين ثم أعلن مفارقتهم، أما واصل والنظام فقبله، والقاضي عبد الجبار بعده."] },

  { id: "aq-100", s: "aqidah", g: 4, d: 5, t: ["creeds-and-authors", "ashari-maturidi"], src: "Ibn ʿAsākir, Tabyīn Kadhib al-Muftarī, list of al-Ashʿarī's works", tr: ["ashari"],
    en: ["Which work of al-Ashʿarī is a survey of the doctrines of the various Muslim groups?", ["Maqālāt al-Islāmiyyīn", "Al-Ibāna ʿan Uṣūl al-Diyāna", "Al-Lumaʿ", "Risāla ilā Ahl al-Thaghr"], "Maqālāt al-Islāmiyyīn wa-Ikhtilāf al-Muṣallīn records the views of the various groups, and is a key early source for the history of theology. Al-Ibāna and al-Lumaʿ present his own creed and arguments, and the Risāla ilā Ahl al-Thaghr is a creed sent to scholars of a frontier region."],
    de: ["Welches Werk al-Ašʿarīs ist eine Übersicht über die Lehren der verschiedenen muslimischen Gruppen?", ["Maqālāt al-Islāmiyyīn", "Al-Ibāna ʿan Uṣūl ad-Diyāna", "Al-Lumaʿ", "Risāla ilā Ahl aṯ-Ṯaġr"], "Maqālāt al-Islāmiyyīn wa-ḫtilāf al-Muṣallīn verzeichnet die Ansichten der verschiedenen Gruppen und ist eine frühe Schlüsselquelle zur Geschichte der Theologie. Al-Ibāna und al-Lumaʿ legen seine eigene Lehre und Argumente dar, die Risāla ilā Ahl aṯ-Ṯaġr ist ein Bekenntnis an Gelehrte einer Grenzregion."],
    ar: ["أيّ كتب الأشعري عرض فيه مقالات الفرق الإسلامية؟", ["مقالات الإسلاميين", "الإبانة عن أصول الديانة", "اللمع", "رسالة إلى أهل الثغر"], "كتاب مقالات الإسلاميين واختلاف المصلين يحكي أقوال الفرق، وهو من أقدم مصادر تاريخ علم الكلام، أما الإبانة واللمع ففيهما تقرير مذهبه وحججه، ورسالة أهل الثغر عقيدة كتبها لعلماء أحد الثغور."] },

  { id: "aq-101", s: "aqidah", g: 4, d: 5, t: ["creeds-and-authors", "nasafiyya"], src: "Ibn Quṭlūbughā, Tāj al-Tarājim, entries on the Nasafīs", tr: ["maturidi"],
    en: ["Several scholars bear the nisba al-Nasafī. Which work is by Abū al-Muʿīn Maymūn al-Nasafī, a major Māturīdī theologian?", ["Tabṣirat al-Adilla", "Al-ʿAqāʾid al-Nasafiyya", "Madārik al-Tanzīl", "Kanz al-Daqāʾiq"], "Abū al-Muʿīn al-Nasafī wrote Tabṣirat al-Adilla, a detailed Māturīdī summa. Al-ʿAqāʾid al-Nasafiyya is by Najm al-Dīn ʿUmar al-Nasafī, while Madārik al-Tanzīl (tafsīr) and Kanz al-Daqāʾiq (Ḥanafī fiqh) are by Abū al-Barakāt al-Nasafī."],
    de: ["Mehrere Gelehrte tragen die Nisba an-Nasafī. Welches Werk stammt von Abū l-Muʿīn Maimūn an-Nasafī, einem bedeutenden māturīditischen Theologen?", ["Tabṣirat al-Adilla", "Al-ʿAqāʾid an-Nasafiyya", "Madārik at-Tanzīl", "Kanz ad-Daqāʾiq"], "Abū l-Muʿīn an-Nasafī schrieb Tabṣirat al-Adilla, eine ausführliche māturīditische Gesamtdarstellung. Al-ʿAqāʾid an-Nasafiyya stammt von Naǧm ad-Dīn ʿUmar an-Nasafī, Madārik at-Tanzīl (Tafsīr) und Kanz ad-Daqāʾiq (ḥanafitischer Fiqh) von Abū l-Barakāt an-Nasafī."],
    ar: ["يُنسب إلى نسف عدة علماء، فأيّ هذه الكتب لأبي المعين ميمون النسفي من كبار متكلمي الماتريدية؟", ["تبصرة الأدلة", "العقائد النسفية", "مدارك التنزيل", "كنز الدقائق"], "ألّف أبو المعين النسفي تبصرة الأدلة وهو من أوسع كتب الماتريدية، أما العقائد النسفية فلنجم الدين عمر النسفي، ومدارك التنزيل في التفسير وكنز الدقائق في الفقه الحنفي فلأبي البركات النسفي."] },

  { id: "aq-102", s: "aqidah", g: 4, d: 4, t: ["creeds-and-authors", "ashari-maturidi"], src: "al-Bayjūrī, Tuḥfat al-Murīd sharḥ Jawharat al-Tawḥīd, introduction", tr: ["ashari"],
    en: ["Who composed the didactic poem Jawharat al-Tawḥīd, widely taught in Ashʿarī circles and commented on by al-Bayjūrī?", ["Ibrāhīm al-Laqānī", "Muḥammad ibn Yūsuf al-Sanūsī", "Abū Bakr al-Bāqillānī", "Ibn ʿĀshir"], "Jawharat al-Tawḥīd is the poem of the Egyptian Mālikī scholar Ibrāhīm al-Laqānī; al-Bayjūrī's Tuḥfat al-Murīd is one of its best-known commentaries. Al-Sanūsī wrote Umm al-Barāhīn, and Ibn ʿĀshir wrote al-Murshid al-Muʿīn."],
    de: ["Wer verfasste das Lehrgedicht Ǧauharat at-Tauḥīd, das in ašʿaritischen Kreisen weit gelehrt und von al-Bāǧūrī kommentiert wurde?", ["Ibrāhīm al-Laqānī", "Muḥammad ibn Yūsuf as-Sanūsī", "Abū Bakr al-Bāqillānī", "Ibn ʿĀšir"], "Ǧauharat at-Tauḥīd ist das Gedicht des ägyptischen mālikitischen Gelehrten Ibrāhīm al-Laqānī; al-Bāǧūrīs Tuḥfat al-Murīd ist einer seiner bekanntesten Kommentare. As-Sanūsī schrieb Umm al-Barāhīn, Ibn ʿĀšir al-Muršid al-Muʿīn."],
    ar: ["مَن ناظم جوهرة التوحيد المتداولة في التدريس عند الأشاعرة وشرحها البيجوري؟", ["إبراهيم اللقاني", "محمد بن يوسف السنوسي", "أبو بكر الباقلاني", "ابن عاشر"], "جوهرة التوحيد منظومة العالم المالكي المصري إبراهيم اللقاني، ومن أشهر شروحها تحفة المريد للبيجوري، أما السنوسي فصاحب أم البراهين، وابن عاشر صاحب المرشد المعين."] },

  { id: "aq-103", s: "aqidah", g: 4, d: 5, t: ["divine-attributes", "ashari-maturidi"], src: "al-Sanūsī, Umm al-Barāhīn, on the necessary attributes", tr: ["ashari"],
    en: ["In al-Sanūsī's Umm al-Barāhīn, how many attributes are listed in detail as necessary (wājib) for Allah?", ["Twenty", "Thirteen", "Seven", "Ninety-nine"], "Al-Sanūsī lists twenty necessary attributes: one nafsiyya (existence), five salbiyya, seven of maʿānī and seven maʿnawiyya. Those who do not count the maʿnawiyya separately arrive at thirteen; seven is the number of the maʿānī alone."],
    de: ["Wie viele Eigenschaften werden in as-Sanūsīs Umm al-Barāhīn im Einzelnen als für Allah notwendig (wāǧib) aufgezählt?", ["Zwanzig", "Dreizehn", "Sieben", "Neunundneunzig"], "As-Sanūsī zählt zwanzig notwendige Eigenschaften auf: eine nafsiyya (das Dasein), fünf salbiyya, sieben des Maʿānī und sieben maʿnawiyya. Wer die maʿnawiyya nicht gesondert zählt, kommt auf dreizehn; sieben ist allein die Zahl der Maʿānī."],
    ar: ["كم صفة واجبة لله تعالى عدّها السنوسي تفصيلًا في أم البراهين؟", ["عشرون", "ثلاث عشرة", "سبع", "تسع وتسعون"], "عدّ السنوسي عشرين صفة واجبة: صفة نفسية هي الوجود، وخمس سلبية، وسبع معانٍ، وسبع معنوية، ومن لم يعدّ المعنوية مستقلة جعلها ثلاث عشرة، والسبع عدد صفات المعاني وحدها."] },

  { id: "aq-104", s: "aqidah", g: 4, d: 5, t: ["divine-attributes", "ashari-maturidi"], src: "al-Sanūsī, Umm al-Barāhīn, on the salbī attributes", tr: ["ashari"],
    en: ["In al-Sanūsī's classification, which attribute is counted among the five salbī (negating) attributes?", ["Dissimilarity to creation (mukhālafa)", "Existence itself (al-wujūd)", "Eternal knowledge (al-ʿilm)", "Being All-Hearing (kawnuhu samīʿan)"], "The five salbī attributes negate something unfitting: beginninglessness (qidam), everlastingness (baqāʾ), dissimilarity to created things, self-subsistence and oneness. Wujūd is the nafsiyya attribute, ʿilm is one of the maʿānī, and being All-Hearing is one of the maʿnawiyya."],
    de: ["Welche Eigenschaft zählt in as-Sanūsīs Einteilung zu den fünf salbī (verneinenden) Eigenschaften?", ["Andersartigkeit gegenüber der Schöpfung (muḫālafa)", "Das Dasein selbst (al-wuǧūd)", "Das ewige Wissen (al-ʿilm)", "Das Allhörend-Sein (kawnuhu samīʿan)"], "Die fünf salbī-Eigenschaften verneinen etwas Unziemliches: Anfangslosigkeit (qidam), Fortdauer (baqāʾ), Andersartigkeit gegenüber dem Geschaffenen, Durch-sich-selbst-Bestehen und Einheit. Wuǧūd ist die nafsiyya-Eigenschaft, ʿilm gehört zu den Maʿānī, das Allhörend-Sein zu den maʿnawiyya."],
    ar: ["في تقسيم السنوسي، أيّ هذه الصفات من الصفات السلبية الخمس؟", ["مخالفته تعالى للحوادث", "الوجود", "العلم", "كونه تعالى سميعًا"], "الصفات السلبية الخمس تسلب ما لا يليق: القدم والبقاء ومخالفته للحوادث وقيامه بنفسه والوحدانية، أما الوجود فصفة نفسية، والعلم من المعاني، وكونه سميعًا من المعنوية."] },

  { id: "aq-105", s: "aqidah", g: 4, d: 5, t: ["divine-attributes", "ashari-maturidi"], src: "Abū al-Muʿīn al-Nasafī, Tabṣirat al-Adilla, on takwīn; al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya", tr: ["maturidi", "ashari"],
    en: ["Which statement correctly describes the difference between Māturīdīs and Ashʿarīs regarding takwīn (bringing into being)?", ["Māturīdīs: a distinct eternal attribute; Ashʿarīs: a relation of power, not a separate attribute", "Ashʿarīs: a distinct eternal attribute; Māturīdīs: they deny any attribute of this kind", "Both schools: takwīn is created in time together with each created thing", "Both schools: takwīn is simply another name for the attribute of knowledge"], "Māturīdīs affirm takwīn as an eternal attribute subsisting in Allah, distinct from power, whose effects occur at their appointed times. Ashʿarīs do not count it as a separate eternal attribute but explain it through the actualising relations of power."],
    de: ["Welche Aussage beschreibt den Unterschied zwischen Māturīditen und Ašʿariten bezüglich takwīn (Ins-Dasein-Bringen) zutreffend?", ["Māturīditen: eigene ewige Eigenschaft; Ašʿariten: eine Beziehung der Macht, keine eigene Eigenschaft", "Ašʿariten: eigene ewige Eigenschaft; Māturīditen: sie verneinen jede Eigenschaft dieser Art", "Beide Schulen: takwīn ist zeitlich, zusammen mit jedem Geschöpf erschaffen", "Beide Schulen: takwīn ist nur ein anderer Name für die Eigenschaft des Wissens"], "Māturīditen bejahen takwīn als ewige, in Allah bestehende Eigenschaft, verschieden von der Macht, deren Wirkungen zu ihren bestimmten Zeiten eintreten. Ašʿariten zählen sie nicht als eigene ewige Eigenschaft, sondern erklären sie durch die verwirklichenden Beziehungen der Macht."],
    ar: ["أيّ العبارات تصف الخلاف بين الماتريدية والأشاعرة في صفة التكوين وصفًا صحيحًا؟", ["الماتريدية: صفة أزلية مستقلة، والأشاعرة: من تعلقات القدرة لا صفة مستقلة", "الأشاعرة: صفة أزلية مستقلة، والماتريدية: ينفون كل صفة من هذا النوع", "المذهبان: التكوين حادث مع كل مخلوق في وقته", "المذهبان: التكوين اسم آخر لصفة العلم بعينها"], "يثبت الماتريدية التكوين صفة أزلية قائمة بذاته تعالى غير القدرة، وتحدث آثاره في أوقاتها، والأشاعرة لا يعدّونه صفة أزلية مستقلة بل يرجعونه إلى تعلقات القدرة التنجيزية."] },

  { id: "aq-106", s: "aqidah", g: 4, d: 5, t: ["divine-speech", "ashari-maturidi"], src: "al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya, on the attribute of speech", tr: ["ashari", "maturidi"],
    en: ["What term do Ashʿarīs and Māturīdīs use for Allah's eternal speech subsisting in His essence, as distinct from the recited and written expressions?", ["Al-kalām al-nafsī", "Al-kalām al-lafẓī", "Al-waḥy al-ilhāmī", "Al-ḥadīth al-qudsī"], "Ashʿarīs and Māturīdīs distinguish the eternal speech subsisting in Allah (al-kalām al-nafsī) from the expressions that are recited, written and memorised (al-kalām al-lafẓī), while both call the Quran the uncreated speech of Allah. The Atharī tradition formulates the attribute of speech differently."],
    de: ["Welchen Begriff verwenden Ašʿariten und Māturīditen für Allahs ewige, in Seinem Wesen bestehende Rede, im Unterschied zu den rezitierten und geschriebenen Ausdrücken?", ["Al-kalām an-nafsī", "Al-kalām al-lafẓī", "Al-waḥy al-ilhāmī", "Al-ḥadīṯ al-qudsī"], "Ašʿariten und Māturīditen unterscheiden die in Allah bestehende ewige Rede (al-kalām an-nafsī) von den rezitierten, geschriebenen und auswendig gelernten Ausdrücken (al-kalām al-lafẓī), wobei beide den Koran die unerschaffene Rede Allahs nennen. Der atharitische Lehrstrang formuliert die Eigenschaft der Rede anders."],
    ar: ["ما المصطلح الذي يستعمله الأشاعرة والماتريدية لكلام الله الأزلي القائم بذاته تمييزًا له عن الألفاظ المتلوة والمكتوبة؟", ["الكلام النفسي", "الكلام اللفظي", "الوحي الإلهامي", "الحديث القدسي"], "يفرّق الأشاعرة والماتريدية بين الكلام النفسي القائم بذاته تعالى والكلام اللفظي المتلو المكتوب المحفوظ، مع قولهم جميعًا إن القرآن كلام الله غير مخلوق، وللأثرية صياغة أخرى في صفة الكلام."] },

  { id: "aq-107", s: "aqidah", g: 4, d: 5, t: ["approaches-to-attributes", "divine-attributes"], src: "Ibn al-Jawzī, Dafʿ Shubah al-Tashbīh; Ibn Qudāma, Dhamm al-Taʾwīl", tr: ["athari", "ashari", "maturidi"],
    en: ["Regarding texts such as the one shown, which approach consigns the precise meaning to Allah while negating likeness, and is held by many Ashʿarīs and Māturīdīs as the way of the early generations?", ["Tafwīḍ", "Taʾwīl", "Ithbāt with known meaning", "Tashbīh"], "Tafwīḍ affirms the text, negates likeness and leaves its precise meaning to Allah. Taʾwīl interprets it by a meaning supported by Arabic usage, an approach found among many later Ashʿarīs and Māturīdīs; Atharīs affirm the apparent meaning while leaving the 'how' to Allah. All three reject tashbīh."],
    de: ["Welcher Zugang zu Texten wie dem angezeigten überlässt die genaue Bedeutung Allah und verneint zugleich jede Ähnlichkeit, und wird von vielen Ašʿariten und Māturīditen als der Weg der frühen Generationen angesehen?", ["Tafwīḍ", "Taʾwīl", "Iṯbāt mit bekannter Bedeutung", "Tašbīh"], "Tafwīḍ bekräftigt den Text, verneint die Ähnlichkeit und überlässt die genaue Bedeutung Allah. Taʾwīl deutet ihn mit einer durch den arabischen Sprachgebrauch gestützten Bedeutung, ein Zugang vieler späterer Ašʿariten und Māturīditen; Athariten bekräftigen die offenkundige Bedeutung und überlassen das Wie Allah. Alle drei lehnen Tašbīh ab."],
    ar: ["في نصوص مثل الآية المعروضة، أيّ المناهج يفوّض المعنى المراد إلى الله مع نفي المماثلة، ويراه كثير من الأشاعرة والماتريدية طريقة السلف؟", ["التفويض", "التأويل", "الإثبات مع العلم بالمعنى", "التشبيه"], "التفويض إثبات اللفظ ونفي المماثلة وتفويض المعنى المراد إلى الله، والتأويل حمله على معنى يحتمله اللسان العربي وعليه كثير من متأخري الأشاعرة والماتريدية، والأثرية يثبتون المعنى الظاهر ويفوّضون الكيفية، والجميع يردّون التشبيه."], v: "20:5" },

  { id: "aq-108", s: "aqidah", g: 4, d: 5, t: ["qadar", "divine-will"], src: "Ibn Taymiyya, al-ʿAqīda al-Wāsiṭiyya; Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on irāda", tr: ["athari"],
    en: ["In Atharī terminology, what is the name of Allah's will by which everything that occurs comes to be, including what He does not love?", ["Al-irāda al-kawniyya", "Al-irāda al-sharʿiyya", "Al-irāda al-dīniyya", "Al-irāda al-ʿamaliyya"], "Atharīs distinguish al-irāda al-kawniyya (creative will), which necessarily occurs and includes what Allah dislikes, from al-irāda al-sharʿiyya or dīniyya (legislative will), which is tied to His love and may not be obeyed. Ashʿarīs and Māturīdīs express the same point through the distinction between will and command or pleasure."],
    de: ["Wie heißt in der atharitischen Terminologie der Wille Allahs, durch den alles Geschehende entsteht, auch was Er nicht liebt?", ["Al-irāda al-kauniyya", "Al-irāda aš-šarʿiyya", "Al-irāda ad-dīniyya", "Al-irāda al-ʿamaliyya"], "Athariten unterscheiden al-irāda al-kauniyya (schöpferischer Wille), die notwendig eintritt und auch das umfasst, was Allah missfällt, von al-irāda aš-šarʿiyya oder ad-dīniyya (gesetzgebender Wille), die mit Seiner Liebe verbunden ist und nicht immer befolgt wird. Ašʿariten und Māturīditen drücken denselben Punkt durch die Unterscheidung zwischen Wille und Gebot bzw. Wohlgefallen aus."],
    ar: ["ما اسم إرادة الله التي يقع بها كل ما يكون، ومنه ما لا يحبه، في اصطلاح الأثرية؟", ["الإرادة الكونية", "الإرادة الشرعية", "الإرادة الدينية", "الإرادة العملية"], "يفرّق الأثرية بين الإرادة الكونية القدرية التي لا بد من وقوعها وتشمل ما يكرهه الله، والإرادة الشرعية الدينية المتعلقة بمحبته وقد لا تقع، ويعبّر الأشاعرة والماتريدية عن المعنى نفسه بالتفريق بين الإرادة والأمر أو الرضا."] },

  { id: "aq-109", s: "aqidah", g: 4, d: 4, t: ["qadar", "human-acts"], src: "al-Bayjūrī, Tuḥfat al-Murīd sharḥ Jawharat al-Tawḥīd, on kasb", tr: ["ashari"],
    en: ["Which term do the Ashʿarīs use for the human being's connection to the voluntary acts that Allah creates?", ["Kasb (acquisition)", "Jabr (compulsion)", "Ikhtirāʿ (origination)", "Tawallud (generation)"], "Ashʿarīs teach that Allah creates the acts of servants and the servant acquires them (kasb), which is the basis of moral responsibility. Jabr denies human choice, ikhtirāʿ (the servant originating his acts independently) is the Muʿtazilī formulation, and tawallud is a Muʿtazilī notion."],
    de: ["Welchen Begriff verwenden die Ašʿariten für die Verbindung des Menschen mit den willentlichen Taten, die Allah erschafft?", ["Kasb (Aneignung)", "Ǧabr (Zwang)", "Iḫtirāʿ (Urheberschaft)", "Tawallud (Hervorgehen)"], "Die Ašʿariten lehren, dass Allah die Taten der Diener erschafft und der Diener sie sich aneignet (kasb), was die Grundlage der Verantwortung ist. Ǧabr verneint die menschliche Wahl, Iḫtirāʿ (der Diener bringe seine Taten selbständig hervor) ist die muʿtazilitische Formulierung, und Tawallud ist ein muʿtazilitischer Begriff."],
    ar: ["ما المصطلح الذي يعبّر به الأشاعرة عن صلة العبد بأفعاله الاختيارية التي يخلقها الله؟", ["الكسب", "الجبر", "الاختراع", "التولّد"], "يقرر الأشاعرة أن الله خالق أفعال العباد والعبد كاسب لها، وعليه يقوم التكليف، أما الجبر فنفي لاختيار العبد، والاختراع أي إيجاد العبد أفعاله استقلالًا عبارة المعتزلة، والتولد من مصطلحات المعتزلة."] },

  { id: "aq-110", s: "aqidah", g: 4, d: 5, t: ["iman-definition", "istithna"], src: "al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya, on istithnāʾ; Ibn Taymiyya, Kitāb al-Īmān", tr: ["athari", "ashari", "maturidi"],
    en: ["On saying \"I am a believer, in shāʾ Allāh\" (istithnāʾ in īmān), which description of the positions is correct?", ["Many Atharīs and Ashʿarīs permit it, not as doubt; Ḥanafī-Māturīdīs generally disapprove", "All Sunni schools forbid it, since it expresses doubt in one's present faith", "Ḥanafī-Māturīdīs make it obligatory, while Atharīs and Ashʿarīs forbid it", "Only the Ashʿarīs discussed the issue; the other schools never addressed it"], "Atharīs permit it with reference to the completeness of faith and avoiding self-praise, and Ashʿarīs with reference to one's final state (al-muwāfāt). Ḥanafī-Māturīdīs generally disapprove of it because it may sound like doubt in present faith. All agree that doubt in faith itself is not acceptable."],
    de: ["Zur Aussage „Ich bin gläubig, in šāʾ Allāh“ (istiṯnāʾ im Īmān): Welche Beschreibung der Positionen ist zutreffend?", ["Viele Athariten und Ašʿariten erlauben sie, nicht als Zweifel; Ḥanafiten-Māturīditen missbilligen sie meist", "Alle sunnitischen Schulen verbieten sie, da sie Zweifel am gegenwärtigen Glauben ausdrückt", "Ḥanafiten-Māturīditen machen sie zur Pflicht, Athariten und Ašʿariten verbieten sie", "Nur die Ašʿariten erörterten die Frage; die anderen Schulen behandelten sie nie"], "Athariten erlauben sie im Hinblick auf die Vollständigkeit des Glaubens und die Vermeidung von Selbstlob, Ašʿariten im Hinblick auf den Endzustand (al-muwāfāt). Ḥanafiten-Māturīditen missbilligen sie meist, weil sie wie Zweifel am gegenwärtigen Glauben klingen kann. Alle sind sich einig, dass Zweifel am Glauben selbst nicht zulässig ist."],
    ar: ["في قول «أنا مؤمن إن شاء الله» (الاستثناء في الإيمان)، أيّ وصف للأقوال صحيح؟", ["يجيزه كثير من الأثرية والأشاعرة لا على وجه الشك، ويمنعه الحنفية الماتريدية غالبًا", "تمنعه جميع مذاهب أهل السنة لأنه شك في الإيمان الحاضر", "يوجبه الحنفية الماتريدية، ويمنعه الأثرية والأشاعرة", "لم يتكلم فيه إلا الأشاعرة، ولم تتعرض له المذاهب الأخرى"], "يجيزه الأثرية باعتبار كمال الإيمان وترك تزكية النفس، والأشاعرة باعتبار الموافاة، ويمنعه الحنفية الماتريدية غالبًا لأنه يوهم الشك في الإيمان الحاضر، والجميع متفقون على أن الشك في أصل الإيمان لا يجوز."] },

  { id: "aq-111", s: "aqidah", g: 4, d: 5, t: ["iman-definition", "pillars-of-islam"], src: "Ibn Rajab, Jāmiʿ al-ʿUlūm wa-l-Ḥikam, hadith 2", tr: ["sunni"],
    en: ["Which principle do many scholars, such as Ibn Rajab, state about the terms islām and īmān?", ["Together they differ in meaning; apart, each includes the other", "They always mean exactly the same thing, wherever they occur", "Islām always refers to the heart, and īmān always to the limbs", "They are never both applied to one and the same person"], "In the hadith of Jibrīl, where both are mentioned together, islām refers to outward acts and īmān to inward belief. Where one is mentioned alone, it includes the meaning of the other. Scholars summarise this in the formula: when they come together they separate, and when they separate they come together."],
    de: ["Welches Prinzip formulieren viele Gelehrte, etwa Ibn Raǧab, über die Begriffe Islām und Īmān?", ["Zusammen unterscheiden sie sich; getrennt umfasst jeder den anderen", "Sie bedeuten überall und immer genau dasselbe", "Islām bezieht sich stets auf das Herz, Īmān stets auf die Glieder", "Sie werden nie beide für ein und dieselbe Person verwendet"], "Im Hadith von Ǧibrīl, wo beide zusammen genannt werden, bezieht sich Islām auf die äußeren Taten und Īmān auf den inneren Glauben. Wird einer allein genannt, umfasst er die Bedeutung des anderen. Die Gelehrten fassen dies in der Formel zusammen: Kommen sie zusammen, trennen sie sich; trennen sie sich, kommen sie zusammen."],
    ar: ["ما القاعدة التي يذكرها كثير من العلماء كابن رجب في لفظي الإسلام والإيمان؟", ["إذا اجتمعا افترقا وإذا افترقا اجتمعا", "معناهما واحد دائمًا حيثما وردا", "الإسلام للقلب دائمًا والإيمان للجوارح", "لا يُطلقان على شخص واحد أبدًا"], "في حديث جبريل اجتمعا ففُسّر الإسلام بالأعمال الظاهرة والإيمان بالاعتقاد الباطن، وإذا ذُكر أحدهما منفردًا دخل فيه معنى الآخر، ولخّص العلماء ذلك بقولهم: إذا اجتمعا افترقا وإذا افترقا اجتمعا."] },

  { id: "aq-112", s: "aqidah", g: 4, d: 4, t: ["ihsan", "hadith-jibril"], src: "Ibn Rajab, Jāmiʿ al-ʿUlūm wa-l-Ḥikam, hadith 2", tr: ["sunni"],
    en: ["Ibn Rajab explains that the definition of iḥsān in the hadith of Jibrīl contains two levels. What is the lower of the two?", ["Worshipping with awareness that Allah sees you", "Worshipping as though you see Allah", "Worshipping only in congregation", "Worshipping with perfect recitation"], "The higher level is to worship as though one sees Allah (often called mushāhada). The second is to worship knowing that Allah sees you (murāqaba); whoever finds the first hard can rely on the second."],
    de: ["Ibn Raǧab erklärt, dass die Definition des Iḥsān im Hadith von Ǧibrīl zwei Stufen enthält. Welche ist die niedrigere?", ["Anbetung im Bewusstsein, dass Allah einen sieht", "Anbetung, als sähe man Allah", "Anbetung nur in der Gemeinschaft", "Anbetung mit vollkommener Rezitation"], "Die höhere Stufe ist, Allah anzubeten, als sähe man Ihn (oft mušāhada genannt). Die zweite ist, anzubeten im Wissen, dass Allah einen sieht (murāqaba); wem die erste schwerfällt, der stützt sich auf die zweite."],
    ar: ["بيّن ابن رجب أن تعريف الإحسان في حديث جبريل يتضمن مقامين، فما أدناهما؟", ["أن يعبد الله مستحضرًا أن الله يراه", "أن يعبد الله كأنه يراه", "أن يعبد الله في الجماعة فقط", "أن يعبد الله بتلاوة متقنة"], "المقام الأعلى أن يعبد الله كأنه يراه ويُسمّى مقام المشاهدة، والثاني أن يعبده عالمًا بأن الله يراه وهو مقام المراقبة، فمن شقّ عليه الأول استعان بالثاني."] },

  { id: "aq-113", s: "aqidah", g: 4, d: 5, t: ["qadar", "hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (account of Yaḥyā ibn Yaʿmar)", tr: ["sunni"],
    en: ["In Ṣaḥīḥ Muslim, Ibn ʿUmar narrates the hadith of Jibrīl after being asked about people in Basra who denied qadar. Who is named as the first to speak about this there?", ["Maʿbad al-Juhanī", "Wāṣil ibn ʿAṭāʾ", "Jahm ibn Ṣafwān", "Ghaylān al-Dimashqī"], "Yaḥyā ibn Yaʿmar reports that the first to speak about (denying) qadar in Basra was Maʿbad al-Juhanī. He and Ḥumayd then asked Ibn ʿUmar, who disavowed that view and narrated the hadith of Jibrīl with its sixth pillar."],
    de: ["Im Ṣaḥīḥ Muslim überliefert Ibn ʿUmar den Hadith von Ǧibrīl, nachdem er nach Leuten in Basra gefragt wurde, die den Qadar leugneten. Wer wird als Erster genannt, der dort darüber sprach?", ["Maʿbad al-Ǧuhanī", "Wāṣil ibn ʿAṭāʾ", "Ǧahm ibn Ṣafwān", "Ġailān ad-Dimašqī"], "Yaḥyā ibn Yaʿmar berichtet, dass der Erste, der in Basra über den Qadar (leugnend) sprach, Maʿbad al-Ǧuhanī war. Er und Ḥumaid fragten daraufhin Ibn ʿUmar, der sich von dieser Ansicht lossagte und den Hadith von Ǧibrīl mit seiner sechsten Säule überlieferte."],
    ar: ["في صحيح مسلم روى ابن عمر حديث جبريل بعد أن سُئل عن قوم بالبصرة ينفون القدر، فمن أول من تكلم في ذلك بها؟", ["معبد الجهني", "واصل بن عطاء", "جهم بن صفوان", "غيلان الدمشقي"], "روى يحيى بن يعمر أن أول من قال في القدر بالبصرة معبد الجهني، فسأل هو وحميد ابن عمر فتبرأ من قولهم وروى حديث جبريل وفيه الركن السادس."] },

  { id: "aq-114", s: "aqidah", g: 4, d: 5, t: ["seeing-allah", "paradise-and-hell"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Ṣuhayb on the vision)", tr: ["sunni"], v: "10:26", w: 4,
    en: ["In the hadith of Ṣuhayb in Ṣaḥīḥ Muslim, the Prophet recited the verse shown after mentioning what, so that the highlighted word is explained by it?", ["The lifting of the veil and the vision of their Lord", "The doubling of the reward for spending in charity", "The wide spaces of the palaces of the believers", "The water of the Prophet's basin on that Day"], "Ṣuhayb reports that when the people of Paradise enter it, the veil is lifted and nothing they were given is dearer to them than looking at their Lord; then the Prophet recited this verse. Many exegetes therefore explain the 'more' (ziyāda) as the vision of Allah."],
    de: ["Im Hadith von Ṣuhaib im Ṣaḥīḥ Muslim rezitierte der Prophet den angezeigten Vers, nachdem er was erwähnt hatte, sodass das hervorgehobene Wort dadurch erklärt wird?", ["Das Aufheben des Schleiers und das Sehen ihres Herrn", "Die Verdoppelung des Lohns für das Spenden", "Die weiten Räume der Paläste der Gläubigen", "Das Wasser des Beckens des Propheten an jenem Tag"], "Ṣuhaib berichtet: Wenn die Bewohner des Paradieses es betreten, wird der Schleier aufgehoben, und nichts, was ihnen gegeben wurde, ist ihnen lieber als der Blick auf ihren Herrn; dann rezitierte der Prophet diesen Vers. Viele Exegeten erklären das ‚Mehr‘ (ziyāda) daher als das Sehen Allahs."],
    ar: ["في حديث صهيب في صحيح مسلم تلا النبي ﷺ الآية المعروضة بعد أن ذكر ماذا، فصارت الكلمة المظللة مفسَّرة به؟", ["كشف الحجاب ورؤية المؤمنين ربهم", "مضاعفة أجر الصدقة", "سعة قصور المؤمنين", "ماء حوض النبي ﷺ"], "روى صهيب أن أهل الجنة إذا دخلوها كُشف الحجاب فما أُعطوا شيئًا أحب إليهم من النظر إلى ربهم، ثم تلا النبي ﷺ هذه الآية، ولذلك فسّر كثير من المفسرين الزيادة بالرؤية."] },

  { id: "aq-115", s: "aqidah", g: 4, d: 5, t: ["mizan", "last-day"], src: "Ibn Kathīr, Tafsīr, on 7:8–9 and 21:47; Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on the mīzān", tr: ["sunni"],
    en: ["Which statement correctly describes the scholarly discussion about what is placed on the scale?", ["Texts mention deeds, records and the doer; some say all three are weighed", "There is agreement that only the person's body is weighed", "There is agreement that only the intentions are weighed", "There is agreement that nothing is weighed, as it is a metaphor"], "Scholars mention three views based on different texts: the deeds themselves given form, the records of deeds (as in the hadith of the card), or the doer himself (as in the hadith of Ibn Masʿūd's legs). Ibn Kathīr and others consider that all three may be weighed."],
    de: ["Welche Aussage beschreibt die Gelehrtendiskussion darüber, was auf die Waage gelegt wird, zutreffend?", ["Texte nennen Taten, Aufzeichnungen und den Handelnden; manche sagen, alle drei werden gewogen", "Es besteht Einigkeit, dass nur der Körper des Menschen gewogen wird", "Es besteht Einigkeit, dass nur die Absichten gewogen werden", "Es besteht Einigkeit, dass nichts gewogen wird, da es ein Bild ist"], "Die Gelehrten nennen drei Ansichten aufgrund verschiedener Texte: die Taten selbst in Gestalt, die Aufzeichnungen der Taten (wie im Hadith der Karte) oder den Handelnden selbst (wie im Hadith über die Beine Ibn Masʿūds). Ibn Kaṯīr und andere halten es für möglich, dass alle drei gewogen werden."],
    ar: ["أيّ العبارات تصف خلاف العلماء فيما يوضع في الميزان وصفًا صحيحًا؟", ["وردت النصوص بوزن الأعمال والصحف والعامل، وجمع بعضهم بوزن الثلاثة", "اتفقوا على أن بدن الإنسان وحده هو الذي يوزن", "اتفقوا على أن النيات وحدها هي التي توزن", "اتفقوا على أنه لا يوزن شيء لأن الميزان مجاز"], "ذكر العلماء ثلاثة أقوال لنصوص مختلفة: وزن الأعمال نفسها مجسّمة، ووزن الصحائف كما في حديث البطاقة، ووزن العامل كما في حديث ساقَي ابن مسعود، ورأى ابن كثير وغيره أن الجميع قد يوزن."] },

  { id: "aq-116", s: "aqidah", g: 4, d: 5, t: ["messengers", "isma"], src: "al-Qāḍī ʿIyāḍ, al-Shifā, section on minor sins of the prophets; Ibn Taymiyya, Majmūʿ al-Fatāwā", tr: ["comparative"],
    en: ["Which statement correctly describes the scholarly positions on the prophets and minor sins?", ["Disputed: many allow minor slips that are promptly corrected; others affirm full protection", "Consensus that prophets fall into minor sins habitually, as other people do", "Consensus that protection began only after revelation and covers only major sins", "The question was never discussed by any scholar of the early or later periods"], "There is agreement on protection in conveying the message and from major sins. On minor sins not involving baseness, many scholars held they could occur but are not persisted in and are corrected at once, while al-Qāḍī ʿIyāḍ and others held that the prophets are protected from them too."],
    de: ["Welche Aussage beschreibt die Gelehrtenpositionen zu den Propheten und kleinen Sünden zutreffend?", ["Umstritten: viele erlauben kleine, sofort berichtigte Verfehlungen; andere lehren vollen Schutz", "Konsens, dass Propheten gewohnheitsmäßig kleine Sünden begehen wie andere Menschen", "Konsens, dass der Schutz erst nach der Offenbarung begann und nur große Sünden betrifft", "Die Frage wurde von keinem frühen oder späteren Gelehrten je erörtert"], "Einigkeit besteht über den Schutz bei der Übermittlung der Botschaft und vor großen Sünden. Bei kleinen Sünden ohne Niedrigkeit hielten viele Gelehrte sie für möglich, aber ohne Beharren und mit sofortiger Berichtigung, während al-Qāḍī ʿIyāḍ und andere lehrten, dass die Propheten auch davor geschützt sind."],
    ar: ["أيّ العبارات تصف أقوال العلماء في وقوع الصغائر من الأنبياء وصفًا صحيحًا؟", ["مختلف فيه: كثيرون يجيزون الصغيرة مع المبادرة إلى التوبة، وآخرون يقولون بالعصمة التامة", "أجمعوا على أن الأنبياء يقعون في الصغائر عادةً كسائر الناس", "أجمعوا على أن العصمة بعد الوحي فقط وفي الكبائر وحدها", "لم يتكلم في المسألة أحد من المتقدمين ولا المتأخرين"], "اتفقوا على العصمة في التبليغ ومن الكبائر، واختلفوا في الصغائر التي لا خسة فيها: فأجاز كثيرون وقوعها دون إقرار عليها مع المبادرة إلى التوبة، وذهب القاضي عياض وغيره إلى عصمتهم منها أيضًا."] },

  { id: "aq-117", s: "aqidah", g: 4, d: 4, t: ["beautiful-names"], src: "al-Nawawī, Sharḥ Ṣaḥīḥ Muslim, Kitāb al-Dhikr (on the ninety-nine names)", tr: ["sunni"],
    en: ["How do the scholars, as reported by al-Nawawī, understand the hadith that Allah has ninety-nine names?", ["It does not limit His names to ninety-nine; it praises enumerating these", "Allah has exactly ninety-nine names and no other names at all", "Only the names mentioned in Āyat al-Kursī are intended by it", "The number refers to the angels who are named after the names"], "Al-Nawawī reports agreement that the hadith does not limit Allah's names to this number; it informs that whoever enumerates these ninety-nine enters Paradise. Another hadith speaks of names Allah has kept in the knowledge of the unseen with Him."],
    de: ["Wie verstehen die Gelehrte laut an-Nawawī den Hadith, dass Allah neunundneunzig Namen hat?", ["Er beschränkt Seine Namen nicht auf neunundneunzig; er lobt das Erfassen dieser", "Allah hat genau neunundneunzig Namen und überhaupt keine anderen", "Gemeint sind nur die im Thronvers erwähnten Namen", "Die Zahl bezieht sich auf die Engel, die nach den Namen benannt sind"], "An-Nawawī berichtet Einigkeit darüber, dass der Hadith Allahs Namen nicht auf diese Zahl beschränkt; er teilt mit, dass wer diese neunundneunzig erfasst, ins Paradies eintritt. Ein anderer Hadith spricht von Namen, die Allah im Wissen des Verborgenen bei sich behalten hat."],
    ar: ["كيف يفهم العلماء، كما نقل النووي، حديث أن لله تسعة وتسعين اسمًا؟", ["لا يحصر أسماءه في تسعة وتسعين، وإنما يرغّب في إحصاء هذه", "لله تسعة وتسعون اسمًا فقط ولا اسم له غيرها", "المراد الأسماء المذكورة في آية الكرسي وحدها", "العدد للملائكة المسمَّين بهذه الأسماء"], "نقل النووي اتفاق العلماء على أن الحديث ليس فيه حصر لأسمائه تعالى، وإنما المقصود الإخبار بأن من أحصى هذه التسعة والتسعين دخل الجنة، وفي حديث آخر ذكر ما استأثر الله به في علم الغيب عنده."] },

  { id: "aq-118", s: "aqidah", g: 4, d: 5, t: ["beautiful-names"], src: "Ibn al-Qayyim, Badāʾiʿ al-Fawāʾid, on the names being tawqīfī; al-Bayjūrī, Tuḥfat al-Murīd", tr: ["jumhur"],
    en: ["According to the majority of Ahl al-Sunna, how are the divine names established?", ["Only by revelation (tawqīfī): no name without a text", "By any word whose meaning is praiseworthy", "By the consensus of the people of each language", "By the intellect, independently of revelation"], "The majority hold that the names of Allah are tawqīfī: one only names Him by what the Quran or the Sunna has named Him. Some theologians allowed names based on sound meaning, and many distinguish naming from describing or informing about Him (ikhbār), which is wider."],
    de: ["Wie werden die göttlichen Namen nach Ansicht der Mehrheit der Ahl as-Sunna festgelegt?", ["Nur durch Offenbarung (tauqīfī): kein Name ohne Textbeleg", "Durch jedes Wort mit lobenswerter Bedeutung", "Durch den Konsens der Sprecher jeder Sprache", "Durch den Verstand, unabhängig von der Offenbarung"], "Die Mehrheit lehrt, dass die Namen Allahs tauqīfī sind: Man benennt Ihn nur mit dem, womit Koran oder Sunna Ihn benannt haben. Einige Theologen erlaubten Namen aufgrund richtiger Bedeutung, und viele unterscheiden das Benennen vom Beschreiben oder Mitteilen über Ihn (iḫbār), das weiter gefasst ist."],
    ar: ["عند جمهور أهل السنة، بمَ تثبت أسماء الله تعالى؟", ["بالتوقيف وحده فلا يُسمّى الله إلا بما ورد به النص", "بكل لفظ معناه محمود", "باتفاق أهل كل لغة", "بالعقل مستقلًا عن الوحي"], "الجمهور على أن أسماء الله توقيفية فلا يُسمّى إلا بما سمّى به نفسه في الكتاب أو السنة، وأجاز بعض المتكلمين ما صحّ معناه، وكثير من العلماء يفرّقون بين التسمية وباب الإخبار الذي هو أوسع."] },

  { id: "aq-119", s: "aqidah", g: 4, d: 4, t: ["major-sins", "creeds-and-authors"], src: "al-Shahrastānī, al-Milal wa-l-Niḥal, chapter on the Muʿtazila", tr: ["sunni"],
    en: ["The doctrine that a Muslim who commits a major sin is in \"a station between the two stations\" (neither believer nor disbeliever) is associated with whom?", ["The Muʿtazila, from Wāṣil ibn ʿAṭāʾ", "The Murjiʾa, from Jahm ibn Ṣafwān", "The Ashʿarīs, from al-Bāqillānī", "The Atharīs, from Aḥmad ibn Ḥanbal"], "Al-Shahrastānī and others report that Wāṣil ibn ʿAṭāʾ held this view and separated from the circle of al-Ḥasan al-Baṣrī, and it became one of the five principles of the Muʿtazila. Ahl al-Sunna hold that such a person remains a believer with deficient faith."],
    de: ["Mit wem ist die Lehre verbunden, ein Muslim, der eine große Sünde begeht, befinde sich in „einer Stellung zwischen den beiden Stellungen“ (weder Gläubiger noch Ungläubiger)?", ["Mit der Muʿtazila, ausgehend von Wāṣil ibn ʿAṭāʾ", "Mit der Murǧiʾa, ausgehend von Ǧahm ibn Ṣafwān", "Mit den Ašʿariten, ausgehend von al-Bāqillānī", "Mit den Athariten, ausgehend von Aḥmad ibn Ḥanbal"], "Aš-Šahrastānī und andere berichten, dass Wāṣil ibn ʿAṭāʾ diese Ansicht vertrat und sich vom Kreis al-Ḥasan al-Baṣrīs trennte; sie wurde einer der fünf Grundsätze der Muʿtazila. Ahl as-Sunna lehren, dass ein solcher Mensch Gläubiger mit mangelhaftem Glauben bleibt."],
    ar: ["القول بأن مرتكب الكبيرة في «منزلة بين المنزلتين» لا مؤمن ولا كافر يُنسب إلى مَن؟", ["المعتزلة ابتداءً من واصل بن عطاء", "المرجئة ابتداءً من جهم بن صفوان", "الأشاعرة ابتداءً من الباقلاني", "الأثرية ابتداءً من أحمد بن حنبل"], "ذكر الشهرستاني وغيره أن واصل بن عطاء قال بذلك فاعتزل مجلس الحسن البصري، وصارت أحد الأصول الخمسة للمعتزلة، ومذهب أهل السنة أنه مؤمن ناقص الإيمان."] },

  { id: "aq-120", s: "aqidah", g: 4, d: 5, t: ["creeds-and-authors", "lumat-al-itiqad"], src: "Ibn Rajab, Dhayl Ṭabaqāt al-Ḥanābila, biography of Ibn Qudāma", tr: ["athari"],
    en: ["Besides Lumʿat al-Iʿtiqād, which creedal treatise was written by Ibn Qudāma al-Maqdisī?", ["Taḥrīm al-Naẓar fī Kutub Ahl al-Kalām", "Al-ʿAqīda al-Wāsiṭiyya", "Al-Ibāna ʿan Uṣūl al-Diyāna", "Al-Tabṣīr fī al-Dīn"], "Ibn Qudāma wrote Taḥrīm al-Naẓar fī Kutub Ahl al-Kalām, a critique of studying kalām books, as well as Dhamm al-Taʾwīl. Al-Wāsiṭiyya is by Ibn Taymiyya, al-Ibāna by al-Ashʿarī, and al-Tabṣīr fī al-Dīn by Abū al-Muẓaffar al-Isfarāyīnī."],
    de: ["Welche Abhandlung zur Glaubenslehre schrieb Ibn Qudāma al-Maqdisī neben Lumʿat al-Iʿtiqād?", ["Taḥrīm an-Naẓar fī Kutub Ahl al-Kalām", "Al-ʿAqīda al-Wāsiṭiyya", "Al-Ibāna ʿan Uṣūl ad-Diyāna", "At-Tabṣīr fī d-Dīn"], "Ibn Qudāma schrieb Taḥrīm an-Naẓar fī Kutub Ahl al-Kalām, eine Kritik am Studium der Kalām-Bücher, sowie Ḏamm at-Taʾwīl. Al-Wāsiṭiyya stammt von Ibn Taimiyya, al-Ibāna von al-Ašʿarī und at-Tabṣīr fī d-Dīn von Abū l-Muẓaffar al-Isfarāyīnī."],
    ar: ["أيّ رسائل الاعتقاد ألّفها ابن قدامة المقدسي إلى جانب لمعة الاعتقاد؟", ["تحريم النظر في كتب أهل الكلام", "العقيدة الواسطية", "الإبانة عن أصول الديانة", "التبصير في الدين"], "ألّف ابن قدامة تحريم النظر في كتب أهل الكلام في ذم الاشتغال بكتب الكلام، وذم التأويل، أما الواسطية فلابن تيمية، والإبانة للأشعري، والتبصير في الدين لأبي المظفر الإسفراييني."] },

  { id: "aq-121", s: "aqidah", g: 4, d: 4, t: ["creeds-and-authors"], src: "Ibn ʿAbd al-Hādī, al-ʿUqūd al-Durriyya, on the Wāsiṭiyya", tr: ["athari"],
    en: ["Which creed did Ibn Taymiyya write at the request of a judge from Wāsiṭ?", ["Al-ʿAqīda al-Wāsiṭiyya", "Al-ʿAqīda al-Ḥamawiyya", "Al-Risāla al-Tadmuriyya", "Lumʿat al-Iʿtiqād"], "Ibn Taymiyya wrote al-Wāsiṭiyya for a judge from Wāsiṭ who asked for a concise creed. Al-Ḥamawiyya answered a question from Ḥamāh, al-Tadmuriyya one from Tadmur (Palmyra), and Lumʿat al-Iʿtiqād is by Ibn Qudāma."],
    de: ["Welches Glaubensbekenntnis schrieb Ibn Taimiyya auf Bitte eines Richters aus Wāsiṭ?", ["Al-ʿAqīda al-Wāsiṭiyya", "Al-ʿAqīda al-Ḥamawiyya", "Ar-Risāla at-Tadmuriyya", "Lumʿat al-Iʿtiqād"], "Ibn Taimiyya schrieb al-Wāsiṭiyya für einen Richter aus Wāsiṭ, der um ein knappes Bekenntnis bat. Al-Ḥamawiyya beantwortete eine Frage aus Ḥamāh, at-Tadmuriyya eine aus Tadmur (Palmyra), und Lumʿat al-Iʿtiqād stammt von Ibn Qudāma."],
    ar: ["أيّ عقيدة كتبها ابن تيمية بطلب قاضٍ من واسط؟", ["العقيدة الواسطية", "العقيدة الحموية", "الرسالة التدمرية", "لمعة الاعتقاد"], "كتب ابن تيمية الواسطية لقاضٍ من واسط سأله عقيدة مختصرة، والحموية جواب سؤال من حماة، والتدمرية جواب سؤال من تدمر، أما لمعة الاعتقاد فلابن قدامة."] },

  { id: "aq-122", s: "aqidah", g: 4, d: 5, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 1:3 and 59:22", tr: ["sunni"], v: "59:22", w: 12,
    en: ["A widely cited explanation distinguishes the name in the highlighted word from the name after it. Which distinction is meant?", ["Al-Raḥmān: mercy for all creation; al-Raḥīm: mercy specific to believers", "Al-Raḥmān is mercy in this world only; al-Raḥīm mercy for the angels", "Al-Raḥmān is an attribute of action; al-Raḥīm a name without meaning", "Al-Raḥmān may be used of humans; al-Raḥīm is used only of Allah"], "Many exegetes explain al-Raḥmān as the One whose mercy encompasses all creatures, and al-Raḥīm as the One whose mercy is specific to the believers, citing 33:43. Al-Raḥmān is a name used only for Allah, whereas raḥīm is also used of people (9:128)."],
    de: ["Eine oft angeführte Erklärung unterscheidet den Namen im hervorgehobenen Wort von dem folgenden. Welche Unterscheidung ist gemeint?", ["Ar-Raḥmān: Barmherzigkeit für alle Schöpfung; ar-Raḥīm: den Gläubigen eigen", "Ar-Raḥmān ist Barmherzigkeit nur im Diesseits, ar-Raḥīm für die Engel", "Ar-Raḥmān ist eine Handlungseigenschaft, ar-Raḥīm ein Name ohne Bedeutung", "Ar-Raḥmān darf für Menschen gebraucht werden, ar-Raḥīm nur für Allah"], "Viele Exegeten erklären ar-Raḥmān als den, dessen Barmherzigkeit alle Geschöpfe umfasst, und ar-Raḥīm als den, dessen Barmherzigkeit den Gläubigen eigen ist, unter Verweis auf 33:43. Ar-Raḥmān wird nur für Allah gebraucht, während raḥīm auch für Menschen verwendet wird (9:128)."],
    ar: ["يفرّق تفسير مشهور بين الاسم في الكلمة المظللة والاسم بعده، فما هذا الفرق؟", ["الرحمن ذو الرحمة الواسعة لجميع الخلق والرحيم ذو الرحمة الخاصة بالمؤمنين", "الرحمن رحمة الدنيا فقط والرحيم رحمة الملائكة", "الرحمن صفة فعل والرحيم اسم بلا معنى", "الرحمن يُسمّى به البشر والرحيم خاص بالله"], "فسّر كثير من المفسرين الرحمن بذي الرحمة الواسعة لجميع الخلق، والرحيم بذي الرحمة الخاصة بالمؤمنين مستدلين بآية الأحزاب (43)، والرحمن اسم مختص بالله، أما رحيم فيوصف به غيره كما في التوبة (128)."] },

  { id: "aq-123", s: "aqidah", g: 4, d: 5, t: ["beautiful-names", "ayat-al-kursi", "tanzih"], src: "Ibn Kathīr, Tafsīr, on 2:255; Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on negation in the attributes", tr: ["sunni"], v: "2:255", w: 10,
    en: ["The verse negates of Allah what the highlighted word names, and sleep. Following the principle that a negation in the attributes implies an affirmed perfection, which perfection is shown?", ["The perfection of His life and His sustaining", "The perfection of His mercy toward sinners", "The perfection of His speech and His command", "The perfection of His wisdom in legislation"], "The highlighted word means drowsiness. Negating drowsiness and sleep shows the perfection of His being al-Ḥayy al-Qayyūm, named at the start of the verse: His life never weakens and His sustaining of creation never lapses. Scholars note that pure negation without an implied perfection is not praise."],
    de: ["Der Vers verneint für Allah das, was das hervorgehobene Wort benennt, und den Schlaf. Nach dem Prinzip, dass eine Verneinung bei den Eigenschaften eine bejahte Vollkommenheit einschließt: Welche Vollkommenheit wird gezeigt?", ["Die Vollkommenheit Seines Lebens und Erhaltens", "Die Vollkommenheit Seiner Barmherzigkeit gegenüber Sündern", "Die Vollkommenheit Seiner Rede und Seines Befehls", "Die Vollkommenheit Seiner Weisheit in der Gesetzgebung"], "Das hervorgehobene Wort bedeutet Schläfrigkeit. Die Verneinung von Schläfrigkeit und Schlaf zeigt die Vollkommenheit dessen, dass Er al-Ḥayy al-Qayyūm ist, wie am Anfang des Verses genannt: Sein Leben wird nie schwach, und Sein Erhalten der Schöpfung setzt nie aus. Die Gelehrten betonen, dass reine Verneinung ohne eingeschlossene Vollkommenheit kein Lob ist."],
    ar: ["تنفي الآية عن الله ما تسمّيه الكلمة المظللة والنوم، فعلى قاعدة أن النفي في الصفات يتضمن إثبات كمال، أيّ كمال يُثبت هنا؟", ["كمال حياته وقيوميته", "كمال رحمته بالعصاة", "كمال كلامه وأمره", "كمال حكمته في التشريع"], "الكلمة المظللة معناها النعاس، ونفي النعاس والنوم يتضمن كمال حياته وقيوميته المذكورين في أول الآية، فلا تضعف حياته ولا يفتر قيامه على خلقه، وقرر العلماء أن النفي المحض الذي لا يتضمن كمالًا ليس مدحًا."] },

];
